      const done = { sig: cardSig, footageId: up.footageId }
      setCardUpload(done)
      return done
    } catch (e) {
      if (!aliveRef.current) return null
      if (uploadGone(e)) return null // KINEO-BUSINESS-POS-AMOSTRA-2026-10-12
      setPlanError(uploadError(e, copy.plan.cardFailed))
