const CHECKOUT_RESUME_SESSION_COOKIE = 'kineo_checkout_session'
const CHECKOUT_RESUME_DISMISSED_COOKIE = 'kineo_checkout_resume_dismissed'
const CHECKOUT_RESUME_MAX_AGE_SECONDS = 30 * 24 * 60 * 60

function rememberRecurringCheckout(response: NextResponse, sessionId: string): NextResponse {
  // Store only Stripe's opaque Session id. All ownership, price and plan data
  // are reloaded from Stripe by the authenticated resume endpoint.
  response.cookies.set({
    name: CHECKOUT_RESUME_SESSION_COOKIE,
    value: sessionId,
    httpOnly: true,
    secure: true,
    sameSite: 'lax',
    path: '/',
    maxAge: CHECKOUT_RESUME_MAX_AGE_SECONDS,
  })
  // A newly created purchase intent supersedes a previous dismissal.
  response.cookies.set({
    name: CHECKOUT_RESUME_DISMISSED_COOKIE,
    value: '',
    httpOnly: true,
    secure: true,
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  })
  // A newer recurring decision supersedes an older one-time Pilot decision.
  // Keeping both would render two competing reminders for the same buyer.
  for (const name of [
    AUTOPILOT_PILOT_SESSION_COOKIE,
    AUTOPILOT_PILOT_DISMISSED_COOKIE,
    AUTOPILOT_PILOT_RESUME_HINT_COOKIE,
  ]) {
    response.cookies.set({
      name,
      value: '',
      httpOnly: true,
      secure: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 0,
    })
  }
  return response
}

function rememberAutopilotPilotCheckout(response: NextResponse, sessionId: string): NextResponse {
  response.cookies.set({
    name: AUTOPILOT_PILOT_SESSION_COOKIE,
    value: sessionId,
    httpOnly: true,
    secure: true,
    sameSite: 'lax',
    path: '/',
    maxAge: CHECKOUT_RESUME_MAX_AGE_SECONDS,
  })
  response.cookies.set({
    name: AUTOPILOT_PILOT_DISMISSED_COOKIE,
    value: '',
    httpOnly: true,
    secure: true,
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  })
  response.cookies.set({
    name: AUTOPILOT_PILOT_RESUME_HINT_COOKIE,
    value: '1',
    secure: true,
    sameSite: 'lax',
    path: '/',
    maxAge: CHECKOUT_RESUME_MAX_AGE_SECONDS,
  })
  // The Pilot is the buyer's newest explicit decision. Remove a stale saved
  // subscription so only the one-time product can own the global reminder.
  for (const name of [CHECKOUT_RESUME_SESSION_COOKIE, CHECKOUT_RESUME_DISMISSED_COOKIE]) {
    response.cookies.set({
      name,
      value: '',
      httpOnly: true,
      secure: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 0,
    })
  }
  return response
}

function isPrivatePackPromotion(raw: string): boolean {
  return raw.toUpperCase().startsWith('KINEO5-')
}

function isStripeResourceMissing(error: unknown): boolean {
  const stripeError = error as { code?: string; type?: string; statusCode?: number } | null
  return stripeError?.code === 'resource_missing' ||
    (stripeError?.type === 'StripeInvalidRequestError' && stripeError?.statusCode === 404)
}

function isMissingStripeCustomer(error: unknown): boolean {
  const stripeError = error as { code?: string; param?: string; message?: string; statusCode?: number } | null
  if (!isStripeResourceMissing(error)) return false
  return stripeError?.param === 'customer' || /no such customer/i.test(stripeError?.message ?? '')
}

// KINEO-ANUNCIO-MOTOR-2026-10-07 — o clique pago (anúncio) que o SourceCapture guardou no cookie deste navegador, como
// chaves paid_* prontas para o evento. Só atribuição: nunca entra na sessão da Stripe, no preço nem na idempotência, e
// qualquer falha (cookie ausente, adulterado, velho, fora do escopo da requisição) devolve {} — o evento sai como antes.
function paidClickMetadataFromRequest(): ReturnType<typeof paidClickEventMetadata> {
  try {
    return paidClickEventMetadata(parsePaidClick(cookies().get(PAID_CLICK_COOKIE)?.value, Date.now()))
  } catch {
