  }
}

// ═══ KINEO-CHECKOUT-HONESTO-2026-10-07 — QUEM ABRIU O PAGAMENTO (só telemetria) ═══════════════════════════════════════
// O fundador viu "9 checkouts" no admin e 1–2 na Stripe. Desde a compra sem login (06/10 ~22:47 UTC) todo clique num
// plano abre uma sessão na Stripe — gente, robô que segue link, teste da casa — e o evento do servidor não tinha como
// separar um do outro: 6 dos 8 checkout_started de convidado desde a ligada vieram sem session_id (o pedido não trazia
// o cookie kineo_event_session_id) e nenhum evento daqui trazia IP ou classe de navegador. O carimbo grava, no writer
// único (recordCheckoutEvent), em TODO evento de checkout:
//   · session_id — o mesmo cookie de sempre; quem chamou sem a sessão recebe a do cookie (as chamadas de hoje já passam
//                  a sessão; isto fecha a porta para a próxima);
//   · ip_hash    — hashIp(clientIp()) de lib/requestIdentity, a MESMA função do sink /api/events (IP cru nunca);
//   · ua_class   — 'browser' | 'bot' | 'unknown': os dois ramos de recordBotSuspicion (UA que casa = bot; UA ausente =
//                  unknown, porque proxy corporativo também apaga o UA — nunca somados num número só);
//   · prefetch   — a régua de isSpeculativeRequest (Sec-Purpose / Purpose: prefetch…).
// NUNCA entra na resposta, no redirect, nos cookies nem nos parâmetros da Stripe: o guardião
// scripts/test-checkout-honesto-2026-10-07.mjs roda a rota com e sem o carimbo e compara a resposta byte a byte.
// Leitura que falha (fora do pedido, cabeçalho ilegível) = nada carimbado; o evento sai como antes.
// Quem lê: lib/admin/checkoutHonesto.ts (o card "Pagamento · 24h" do /admin).
function checkoutUaClass(ua: string | null): 'browser' | 'bot' | 'unknown' {
  const trimmed = (ua ?? '').trim()
  if (!trimmed) return 'unknown'
  return isLikelyBotUserAgent(trimmed) ? 'bot' : 'browser'
}

function stampCheckoutOrigin(eventRow: Record<string, unknown>): void {
  if (eventRow.session_id === null || eventRow.session_id === undefined) {
    try {
      const raw = cookies().get('kineo_event_session_id')?.value ?? ''
      if (/^[A-Za-z0-9_-]{8,64}$/.test(raw)) eventRow.session_id = raw
    } catch {
      // fora do pedido: a coluna fica como veio
    }
  }
  try {
    const h = requestHeaders()
    eventRow.metadata = {
      ...(eventRow.metadata as Record<string, unknown>),
      ip_hash: hashIp(clientIp(h)),
      ua_class: checkoutUaClass(h.get('user-agent')),
      prefetch: isSpeculativeRequest({ headers: h }),
    }
  } catch {
    // sem os cabeçalhos do pedido: o evento sai como antes
  }
}
// ═══ FIM KINEO-CHECKOUT-HONESTO-2026-10-07 ═══════════════════════════════════════════════════════════════════════════

// KINEO-RECOVERY-2026-07-15 — checkout telemetry is written server-side so
// the immediate navigation to Stripe cannot cancel it. This also records the
// anonymous auth wall, which client-only click tracking could never see.
async function recordCheckoutEvent(
  name:
    | 'checkout_attempted'
    | 'checkout_auth_required'
    | 'checkout_started'
    | 'checkout_failed'
    | 'checkout_prefetch_blocked'
    // KINEO-SCANNER-DENOMINADOR-2026-08-16 — OBSERVA, não barra. Ver o bloco
    // grande sobre `recordBotSuspicion` abaixo para o porquê de não bloquear.
    | 'checkout_bot_suspected'
    // KINEO-BULK-2026-07-27 — funil de atacado, nomeado. Server-only (declarado
    // em app/api/events/route.ts): se o sink do browser pudesse cunhá-lo, o
    // denominador do único canal de receita novo viraria ficção.
    | 'bulk_checkout_started'
    | 'ads_checkout_started' // KINEO-STUDIO-ADS-2026-09-25
    // KINEO-COMPRA-SEM-LOGIN-2026-10-06 — sessão Stripe aberta por quem ainda não tem conta, e o pedido que podia ser
    // de convidado mas voltou ao caminho de hoje, com o motivo (os dois SERVER_ONLY).
    | 'checkout_guest_started'
    | 'guest_checkout_fallback',
  userId: string | null,
  metadata: Record<string, unknown>,
  sessionId?: string,
): Promise<void> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY
  if (!url || !key) return
  try {
    const admin = createAdminClient(url, key, {
      auth: { persistSession: false, autoRefreshToken: false },
    })
    const eventRow: Record<string, unknown> = {
      name,
      user_id: userId,
      path: '/api/stripe/checkout',
      session_id: sessionId ?? null,
      // KINEO-ANUNCIO-MOTOR-2026-10-07 — + o último clique pago deste navegador (cookie do SourceCapture, saneado em
      // lib/growth/paidClickAttribution.ts). Sem anúncio = nenhuma chave nova. É daqui que o webhook copia para o
      // payment_success: logado ou convidado, a compra passa a dizer se veio de anúncio.
      metadata: { ...metadata, ...paidClickMetadataFromRequest() },
    }
    stampCheckoutOrigin(eventRow) // KINEO-CHECKOUT-HONESTO-2026-10-07 — sessão, ip_hash, ua_class e prefetch (só telemetria)
    // Stripe idempotency can return the same Checkout Session to two racing
    // requests. Give checkout_started a deterministic UUID so analytics also
    // remain idempotent instead of counting the same session twice.
    const stripeSessionId = typeof metadata.stripe_session_id === 'string' ? metadata.stripe_session_id : null
    // KINEO-COMPRA-SEM-LOGIN-2026-10-06 — o evento do convidado ganha o MESMO id determinístico (nome:sessão): dois
    // cliques na janela de idempotência devolvem a mesma sessão e não podem contar duas compras abertas.
    const deterministicCheckoutEvent = name === 'checkout_started' || name === 'checkout_guest_started'
    if (deterministicCheckoutEvent && stripeSessionId) {
      const hex = createHash('sha256').update(`${name}:${stripeSessionId}`).digest('hex').slice(0, 32)
      eventRow.id = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
    }
    const { error } = await admin.from('events').insert(eventRow)
    if (error?.code === '23505' && deterministicCheckoutEvent) return
    if (error) console.error('[stripe/checkout] event insert failed:', name, error.code, error.message)
  } catch (error) {
    console.error('[stripe/checkout] event insert threw:', name, error)
  }
}

// KINEO-CHECKOUT-TRIAGE-2026-07-25 — the browser session id minted by
// lib/analytics.ts (kineo_event_session_id) is mirrored into a cookie so every
// server-side checkout event lands on the SAME session as the client-side
// checkout_click. Without this, checkout_* rows show 0 distinct sessions.
function browserSessionIdFrom(req: NextRequest): string | undefined {
  const raw = req.cookies.get('kineo_event_session_id')?.value ?? ''
  return /^[A-Za-z0-9_-]{8,64}$/.test(raw) ? raw : undefined
}

// KINEO-PACK-INTENT-2026-09-23 — UMA sanitização de `intent_campaign` para as
// duas rotas de sessão. Até aqui só a assinatura (buildAndRedirect) lia e
// gravava a campanha; o pack de US$4,90 (buildPackAndRedirect) gravava só
// supabase_user_id/pack/pack_credits, e toda medição "quantos packs vieram da
// campanha X" dava 0 — não porque ninguém comprou, mas porque o dado nunca
// viajou. Mesmo padrão (alfanumérico . _ ~ -, 1-100) que a assinatura já usa
// e que lib/growth/pricingPlanChoiceAttribution.ts usa no cliente.
function intentCampaignFrom(req: NextRequest): string | undefined {
  const raw = (req.nextUrl.searchParams.get('intent_campaign') ?? '').trim()
  return /^[A-Za-z0-9._~-]{1,100}$/.test(raw) ? raw : undefined
}

type CheckoutIntentSnapshot = {
  videosOk: number | null
  creditsIntact: boolean | null
  hadFinishedScript: boolean | null
}

async function readCheckoutIntentSnapshot(
  userId: string,
  browserSessionId: string | null,
  profile: {
    video_credits?: unknown
    trial_credits_granted?: unknown
    trial_credits_used?: unknown
  },
): Promise<CheckoutIntentSnapshot> {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY
  if (!url || !key) return { videosOk: null, creditsIntact: null, hadFinishedScript: null }

  try {
    const admin = createAdminClient(url, key, {
      auth: { persistSession: false, autoRefreshToken: false },
    })
    const since = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
    const completedRequest = admin
      .from('videos')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', userId)
      .eq('status', 'completed')
    let scriptSignalsRequest = admin
      .from('events')
      .select('name, metadata')
      .eq('user_id', userId)
      .in('name', [
        'activation_autostart_eligible',
        'activation_autostart_dispatched',
        'chatgpt_quickstart_selected',
      ])
      .gte('created_at', since)
      .order('created_at', { ascending: false })
      .limit(50)
    if (browserSessionId) scriptSignalsRequest = scriptSignalsRequest.eq('session_id', browserSessionId)

    const [completedResult, scriptSignalsResult] = await Promise.all([
      completedRequest,
      scriptSignalsRequest,
    ])
    const videosOk = completedResult.error ? null : completedResult.count ?? 0
    const hadFinishedScript = scriptSignalsResult.error
      ? null
      : (scriptSignalsResult.data ?? []).some((row) => {
          const metadata = row.metadata && typeof row.metadata === 'object'
            ? row.metadata as Record<string, unknown>
            : {}
          if (row.name === 'chatgpt_quickstart_selected') {
            return metadata.input_type === 'finished_script'
          }
          const promptLength = Number(metadata.prompt_length ?? 0)
          return metadata.script_mode === 'verbatim' && Number.isFinite(promptLength) && promptLength >= 40
        })

    const balance = Number(profile.video_credits)
    const granted = Number(profile.trial_credits_granted)
    const used = Number(profile.trial_credits_used)
    const hasTrialLedger = Number.isFinite(granted) && granted > 0 && Number.isFinite(used)
    const creditsIntact = hasTrialLedger && Number.isFinite(balance)
      ? used === 0 && balance >= granted
      : null
    return { videosOk, creditsIntact, hadFinishedScript }
  } catch (error) {
    console.warn('[stripe/checkout] intent snapshot unavailable:', error instanceof Error ? error.name : 'unknown')
    return { videosOk: null, creditsIntact: null, hadFinishedScript: null }
  }
}

// Close the client-effect race only for the subscription checkout that can
// create recurring affiliate value. AffiliateAutoTrigger normally stamps the
// profile after signup, but a fast CTA can reach this route first. The shared
// server primitive verifies the protected click, creates/reads the canonical
// referral and confirms the legacy profile cache before Stripe Session create.
// No entitlement, price or webhook behavior changes here.
async function resolveCustomAffiliateBeforeSubscription(
  req: NextRequest,
  user: { id: string; email?: string | null; created_at?: string | null },
  profile: { email?: string | null; affiliate_id?: string | null } | null | undefined,
): Promise<string | null> {
  const result = await attributeAffiliateForUser(
    req.cookies.get('sf_aff')?.value,
    {
      id: user.id,
      email: profile?.email ?? user.email ?? null,
      createdAt: user.created_at,
    },
    {
      allowNewAttribution: true,
      clickId: normalizeAffiliateClickId(req.cookies.get('sf_aff_click')?.value),
    },
  )
  if (result.ok) return result.affiliateId
  if (!['invalid_code', 'invalid_click_proof', 'ineligible_existing_account'].includes(result.reason)) {
    console.warn('[stripe/checkout] affiliate attribution not finalized:', result.reason)
  }
  // Preserve established behavior during a transient attribution lookup. The
  // canonical route normally keeps this cache repaired; this fallback neither
  // creates a new owner nor changes the checkout's price or entitlement.
  return profile?.affiliate_id ?? null
}

// KINEO-CHECKOUT-TRIAGE-2026-07-25 — produção mostrou rajadas de
// checkout_auth_required com 2-8 ms entre elas, uma por tier, sem user_id e sem
// session_id: isso é um prefetcher/scanner abrindo TODOS os <a href> de uma
// página (ou de um e-mail de recuperação) de uma vez.
//
// A prefetched request must never create a real Stripe Checkout Session:
// it inflates telemetry, burns Stripe rate limit and produces "abandoned"
// sessions for tiers nobody clicked. A genuine click is always a top-level
// navigation (Sec-Fetch-Mode: navigate), so we only block requests that
// explicitly announce themselves as speculative.
function isSpeculativeRequest(req: { headers: { get(name: string): string | null } }): boolean { // KINEO-CHECKOUT-HONESTO-2026-10-07 — tipo estrutural: o carimbo passa só os cabeçalhos
  const h = req.headers
  const secPurpose = (h.get('sec-purpose') ?? '').toLowerCase()
  if (secPurpose.includes('prefetch') || secPurpose.includes('prerender')) return true
  const purpose = (h.get('purpose') ?? h.get('x-purpose') ?? '').toLowerCase()
  if (purpose === 'prefetch' || purpose === 'preview') return true
  if ((h.get('x-moz') ?? '').toLowerCase() === 'prefetch') return true
  if (h.get('next-router-prefetch') === '1') return true
  return false
}

// A prefetch is not an error for the buyer — nobody is looking at it. Answer
// with a body-less 204 so no Stripe call, no cookie and no redirect happen.
// KINEO-AUTOPILOT-FORA-2026-10-09 — o Autopilot (US$ 299, Lite US$ 59, piloto US$ 99) saiu da vitrine por decisão do fundador. Compra NOVA
// da família é recusada aqui, ANTES de qualquer sessão Stripe, com 410 'plan_unavailable' — exceto conta interna
// (lista exata da casa, pelo e-mail do auth). Assinante existente não passa por aqui: renovação, webhook e agenda
// seguem intactos. null = pode seguir (SKU de fora da família, interruptor ligado ou conta da casa).
async function refuseClosedAutopilotCheckout(req: NextRequest, sku: string): Promise<NextResponse | null> {
  if (!isAutopilotFamilySku(sku)) return null
  let email: string | null = null
  let userId: string | null = null
  try {
    const { data: { user } } = await createClient().auth.getUser()
    email = user?.email ?? null
    userId = user?.id ?? null
  } catch {
    // sem sessão legível = não é a casa: recusa (falha fechada)
  }
  if (autopilotCheckoutOpen(sku, isAdsInternalEmail(email))) return null
  await recordCheckoutEvent(
    'checkout_failed',
    userId,
    { selection: sku, stage: 'plan_gate', reason: AUTOPILOT_UNAVAILABLE_REASON },
    browserSessionIdFrom(req),
  )
  return NextResponse.json(
    { error: AUTOPILOT_UNAVAILABLE_REASON, message: AUTOPILOT_UNAVAILABLE_MESSAGE, pricing: '/pricing' },
    { status: 410 },
  )
}

// KINEO-PAGINAS-QUE-VENDEM-2026-10-12 — os pacotes avulsos de agência (bulk10/20/30/50, vendidos em filmes Kineo 1) saíram
// da vitrine (lib/bulkPacksPublic.ts). Compra NOVA é recusada aqui com 410 'pack_unavailable', ANTES de qualquer sessão
// Stripe — exceto conta interna. Mesmo padrão do Autopilot acima. Quem já comprou não passa por aqui: o webhook (Path A,
// metadata.pack bulk*), o crédito concedido e o acesso legado ao Kineo 1 seguem intactos. null = pode seguir.
async function refuseClosedBulkPackCheckout(req: NextRequest, sku: string): Promise<NextResponse | null> {
