          unit_amount: chargeAmount,
          recurring: { interval },
        },
        quantity: 1,
      }

  // ═══ KINEO-TAXA-ENTRADA-LINE-ITEM-2026-09-09 — O DÓLAR PRECISA SER COBRÁVEL
