  async function jsonError(msg: string, status: number, reasonOverride?: string) {
    await recordCheckoutEvent(
      'checkout_failed',
      failureUserId,
      { ...skuContext, stage: 'json', status, reason: reasonOverride ?? checkoutFailureReason(msg) },
      browserSessionId,
