  if (!process.env.STRIPE_SECRET_KEY) {
    console.error('[stripe/checkout] STRIPE_SECRET_KEY is not set')
    return isGet ? redirectError('Payment service is not configured. Please contact support.') : jsonError('Payment service is not configured. Please contact support.', 500)
  }

  const country = req.headers.get('x-vercel-ip-country') ?? 'US'
  const currency: Currency = resolveCheckoutCurrency(country)
  const sliderUsd = topupId === CREDIT_SLIDER_PACK_ID ? sliderPriceUsdMinor(sliderCredits) : null
  if (topupId === CREDIT_SLIDER_PACK_ID && (sliderUsd === null || sliderCredits === null)) {
    const msg = `Choose between ${CREDIT_SLIDER_MIN} and ${CREDIT_SLIDER_MAX.toLocaleString('en-US')} credits.`
    return isGet ? redirectError(msg, '/studio', 'slider_credits_invalid') : jsonError(msg, 400, 'slider_credits_invalid')
  }
  const topup = topupId === CREDIT_SLIDER_PACK_ID
    ? { credits: sliderCredits as number, name: `Kineo — +${(sliderCredits as number).toLocaleString('en-US')} credits`, description: `One-time: ${(sliderCredits as number).toLocaleString('en-US')} credits (${describeSeedanceMix(sliderCredits as number)}). No subscription.`, prices: { usd: sliderUsd as number } as Record<Currency, number> }
    : CREDIT_TOPUPS[topupId]
  const unitAmount = topup.prices[currency]
  skuContext.currency = currency
  skuContext.unit_amount = unitAmount
  // KINEO-MOEDA-LOCAL-2026-09-09 — preço de lista em USD; a sessão nasce na
  // moeda do país (Brasil = reais pela fórmula da casa, terminando em ,90).
  // Pix aparece sozinho nas sessões em BRL de pagamento único (mode 'payment').
  const settlement = resolveSettlementCurrency({
    ipCountry: req.headers.get('x-vercel-ip-country') ?? 'US',
    acceptLanguage: req.headers.get('accept-language'),
    forced: req.nextUrl.searchParams.get('currency'),
  })
  const chargeCurrency = settlement.currency
  const chargeAmount = settlementAmountMinor(unitAmount, chargeCurrency)
  skuContext.settlement_currency = chargeCurrency
  skuContext.charge_amount = chargeAmount

  const supabase = createClient()
  const { data: { user }, error: authError } = await supabase.auth.getUser()
  failureUserId = user?.id ?? null
  await recordCheckoutEvent('checkout_attempted', user?.id ?? null, skuContext, browserSessionId)
  if (authError || !user) {
    await recordCheckoutEvent('checkout_auth_required', null, skuContext, browserSessionId)
    // KINEO-CHECKOUT-RESUME-2026-07-07 — resume the top-up checkout after sign-in.
    // `resumed=1` = loop guard (visible error instead of login↔checkout forever).
    if (!isGet) return jsonError('You must be signed in to buy credits.', 401)
    if (req.nextUrl.searchParams.get('resumed') === '1') {
      return redirectError('We could not confirm your sign-in. Please sign in and try again.')
    }
    const resume = `${req.nextUrl.pathname}${req.nextUrl.search}${req.nextUrl.search ? '&' : '?'}resumed=1`
    return NextResponse.redirect(`${appUrl}/login?reason=checkout&redirect=${encodeURIComponent(resume)}`)
  }

  const { data: profile } = await supabase
    .from('profiles')
    .select('email, stripe_customer_id, plan')
    .eq('id', user.id)
    .single()

  // Gate: AI credit top-ups are a Creator/Studio benefit (the AI engine lives on
  // those plans). Free/Starter users are sent to /pricing to subscribe instead.
  if (!canPurchaseCreditTopup(profile?.plan)) {
    return isGet
      ? redirectError(
          'Credit top-ups are for Creator & Studio plans. Choose a plan to continue.',
          '/pricing',
          'topup_requires_creator_plus',
        )
      : jsonError('Credit top-ups require a Creator or Studio plan.', 403, 'topup_requires_creator_plus')
  }

  const sessionParams: Stripe.Checkout.SessionCreateParams = {
    mode: 'payment',
    line_items: [
      {
        price_data: {
          currency: chargeCurrency,
          product_data: { name: topup.name, description: topup.description },
          unit_amount: chargeAmount,
        },
        quantity: 1,
      },
    ],
    client_reference_id: user.id,
    success_url: `${appUrl}/generate?success=true&topup=${topupId}&session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${appUrl}/generate`,
    metadata: {
      supabase_user_id: user.id,
