//
// Só USD. Ver a justificativa em lib/checkoutPricing.ts (BULK_PACKS): o fundador
// aprovou quatro números em dólar e inventar câmbio para um SKU de atacado não é
// decisão de Development.
async function buildBulkPackAndRedirect(
  req: NextRequest,
  bulkId: BulkPackId,
  isGet: boolean,
): Promise<NextResponse> {
  const appUrl = req.nextUrl.origin
  const browserSessionId = browserSessionIdFrom(req)
  const pack = BULK_PACKS[bulkId]
  let failureUserId: string | null = null
  const skuContext: Record<string, unknown> = {
    sku: bulkId,
    mode: 'payment',
    bulk_videos: pack.videos,
    bulk_credits: pack.credits,
    bulk_checkout_truth_version: BULK_CHECKOUT_TRUTH_VERSION,
  }

  async function redirectError(msg: string) {
    await recordCheckoutEvent(
      'checkout_failed',
      failureUserId,
      { ...skuContext, stage: 'redirect', reason: checkoutFailureReason(msg) },
      browserSessionId,
    )
    return NextResponse.redirect(`${appUrl}/pricing?checkout_error=${encodeURIComponent(msg)}`)
  }
  async function jsonError(msg: string, status: number) {
    await recordCheckoutEvent(
      'checkout_failed',
      failureUserId,
      { ...skuContext, stage: 'json', status, reason: checkoutFailureReason(msg) },
      browserSessionId,
    )
    return NextResponse.json({ error: msg }, { status })
  }

  if (!process.env.STRIPE_SECRET_KEY) {
    console.error('[stripe/checkout] STRIPE_SECRET_KEY is not set')
    return isGet
      ? redirectError('Payment service is not configured. Please contact support.')
      : jsonError('Payment service is not configured. Please contact support.', 500)
  }

  // Preço de atacado é em dólar, sempre — não segue o país do IP como os outros.
  const currency: Currency = 'usd'
  const unitAmount = pack.usdMinor
  skuContext.currency = currency
  skuContext.unit_amount = unitAmount
  // KINEO-MOEDA-LOCAL-2026-09-09 — preço de lista em USD; a sessão nasce na
  // moeda do país (Brasil = reais pela fórmula da casa, terminando em ,90).
  // Pix aparece sozinho nas sessões em BRL de pagamento único (mode 'payment').
  const settlement = resolveSettlementCurrency({
    ipCountry: req.headers.get('x-vercel-ip-country') ?? 'US',
    acceptLanguage: req.headers.get('accept-language'),
    forced: req.nextUrl.searchParams.get('currency'),
  })
  const chargeCurrency = settlement.currency
  const chargeAmount = settlementAmountMinor(unitAmount, chargeCurrency)
  skuContext.settlement_currency = chargeCurrency
  skuContext.charge_amount = chargeAmount

  const supabase = createClient()
  const { data: { user }, error: authError } = await supabase.auth.getUser()
  failureUserId = user?.id ?? null
  await recordCheckoutEvent('checkout_attempted', user?.id ?? null, skuContext, browserSessionId)
  if (authError || !user) {
    await recordCheckoutEvent('checkout_auth_required', null, skuContext, browserSessionId)
    if (!isGet) return jsonError('You must be signed in to buy a video pack.', 401)
    // `resumed=1` = trava de laço (erro visível em vez de login↔checkout eterno).
    if (req.nextUrl.searchParams.get('resumed') === '1') {
      return redirectError('We could not confirm your sign-in. Please sign in and try again.')
    }
    const resume = `${req.nextUrl.pathname}${req.nextUrl.search}${req.nextUrl.search ? '&' : '?'}resumed=1`
    return NextResponse.redirect(`${appUrl}/login?reason=checkout&redirect=${encodeURIComponent(resume)}`)
  }

  const { data: profile } = await supabase
    .from('profiles')
    .select('email, stripe_customer_id')
    .eq('id', user.id)
    .single()

  const sessionParams: Stripe.Checkout.SessionCreateParams = {
    mode: 'payment',
    line_items: [
      {
        price_data: {
          currency: chargeCurrency,
          product_data: {
            name: `Kineo — ${pack.videos} Shorts`,
            description: bulkCheckoutDescription(pack),
          },
          unit_amount: chargeAmount,
        },
        quantity: 1,
      },
    ],
    client_reference_id: user.id,
    success_url: `${appUrl}/generate?success=true&pack=${bulkId}&session_id={CHECKOUT_SESSION_ID}`,
    // Preserve the exact B2B choice when Stripe is closed. Sending this buyer
    // to generic subscription pricing erased the pack, volume and one-time
    // purchase context at the highest-intent reversible exit.
    cancel_url: buildAgencyCheckoutCancelUrl(appUrl, bulkId),
    metadata: {
      supabase_user_id: user.id,
      // ⚠️ metadata.pack é a ÚNICA coisa que distingue bulk10 de autopilot_pilot:
      // os dois custam 9900 em USD. O webhook se RECUSA a resolver esse valor por
      // fallback (AMBIGUOUS_ONE_TIME_USD_AMOUNTS), então esta chave não é
      // conveniência — é o que impede um pacote de 10 vídeos de virar um plano
      // Autopilot de $299/mês.
      pack: bulkId,
      pack_credits: String(pack.credits),
      bulk_videos: String(pack.videos),
      bulk_checkout_truth_version: BULK_CHECKOUT_TRUTH_VERSION,
    },
  }
  if (profile?.stripe_customer_id) sessionParams.customer = profile.stripe_customer_id
  else sessionParams.customer_email = profile?.email ?? user.email ?? undefined

  // KINEO-CHECKOUT-TRIAGE-2026-07-25 — um clique = no máximo uma sessão Stripe.
  // Produção mostrou 1 usuário gerando 7 sessions em 2,8s quando os SKUs avulsos
  // não tinham chave nenhuma. Nasce com chave.
  const bulkIdempotencyKey = oneTimeIdempotencyKey({
    sku: bulkId,
    user_id: user.id,
    currency: chargeCurrency,
    unit_amount: chargeAmount,
    contract_version: BULK_CHECKOUT_TRUTH_VERSION,
    customer: sessionParams.customer ?? null,
  })

  let session: Stripe.Checkout.Session
  try {
    session = await stripe.checkout.sessions.create(sessionParams, { idempotencyKey: bulkIdempotencyKey })
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    // Um customer criado em BRL/INR não aceita uma sessão em USD. Cai para
    // customer_email, exatamente como os outros SKUs one-time fazem.
    if (msg.toLowerCase().includes('cannot combine currencies')) {
      delete sessionParams.customer
      sessionParams.customer_email = profile?.email ?? user.email ?? undefined
      try {
        session = await stripe.checkout.sessions.create(sessionParams, {
          idempotencyKey: `${bulkIdempotencyKey}:email`,
        })
      } catch (retryErr) {
        const rmsg = retryErr instanceof Error ? retryErr.message : String(retryErr)
        console.error('[stripe/checkout] bulk retry failed:', rmsg)
        return isGet
          ? redirectError(`Payment session failed: ${rmsg || 'Please try again'}`)
          : jsonError('Payment session failed.', 500)
      }
    } else {
      console.error('[stripe/checkout] bulk session error:', msg)
      return isGet
        ? redirectError(`Payment session failed: ${msg || 'Please try again'}`)
        : jsonError('Payment session failed.', 500)
    }
  }

  console.log(
    `[stripe/checkout] bulk session: ${bulkId} user=${user.id.slice(0, 8)} amount=${unitAmount} ${currency}`,
  )
  await recordCheckoutEvent(
    'checkout_started',
    user.id,
    { ...skuContext, stripe_session_id: session.id },
    browserSessionId,
  )
  // KINEO-BULK-2026-07-27 — evento nomeado do funil de atacado. `checkout_started`
  // continua sendo emitido (o funil geral não pode ganhar um buraco), mas contar
  // atacado a partir dele exige filtrar metadata.sku. Um nome próprio torna o
  // funil de atacado contável direto.
  await recordCheckoutEvent(
    'bulk_checkout_started',
    user.id,
    { ...skuContext, stripe_session_id: session.id },
    browserSessionId,
  )
  return isGet ? NextResponse.redirect(session.url!) : NextResponse.json({ url: session.url })
}

// ═══ KINEO-STUDIO-ADS-2026-09-25 — passe do Studio Ads (?pack=ads_pass) ════════════════════════════
// Decisões do fundador (24/09): passe ÚNICO de US$19,90 com 60 créditos, 365 dias de acesso, preço global em dólar
// (Brasil paga em reais pela fórmula da casa; o resto pela conversão da Stripe). Fonte única dos números:
// lib/ads/offer.ts. O webhook (Path A) concede os créditos pela metadata.pack_credits e o acesso
// (profiles.ads_access_until) no MESMO UPDATE, fail-closed. DESLIGADO enquanto NEXT_PUBLIC_ADS_PASS_LIVE !== '1':
// só contas internas compram (canário), todo o resto recebe um erro visível — nunca uma sessão da Stripe.
async function buildAdsPassAndRedirect(req: NextRequest, isGet: boolean): Promise<NextResponse> {
  const appUrl = req.nextUrl.origin
  const browserSessionId = browserSessionIdFrom(req)
  let failureUserId: string | null = null
  const skuContext: Record<string, unknown> = {
    sku: ADS_PASS_ID,
    mode: 'payment',
    ads_credits: ADS_PASS_CREDITS,
    ads_offer_version: ADS_OFFER_VERSION,
  }
  async function redirectError(msg: string) {
    await recordCheckoutEvent('checkout_failed', failureUserId, { ...skuContext, stage: 'redirect', reason: checkoutFailureReason(msg) }, browserSessionId)
    return NextResponse.redirect(`${appUrl}/ads?checkout_error=${encodeURIComponent(msg)}`)
  }
  async function jsonError(msg: string, status: number) {
    await recordCheckoutEvent('checkout_failed', failureUserId, { ...skuContext, stage: 'json', status, reason: checkoutFailureReason(msg) }, browserSessionId)
    return NextResponse.json({ error: msg }, { status })
  }
  if (!process.env.STRIPE_SECRET_KEY) {
    console.error('[stripe/checkout] STRIPE_SECRET_KEY is not set')
    return isGet ? redirectError('Payment service is not configured. Please contact support.') : jsonError('Payment service is not configured. Please contact support.', 500)
  }

  const currency: Currency = 'usd'
  const unitAmount = ADS_PASS_USD_MINOR
  const settlement = resolveSettlementCurrency({
    ipCountry: req.headers.get('x-vercel-ip-country') ?? 'US',
    acceptLanguage: req.headers.get('accept-language'),
    forced: req.nextUrl.searchParams.get('currency'),
  })
  const chargeCurrency = settlement.currency
  const chargeAmount = settlementAmountMinor(unitAmount, chargeCurrency)
  skuContext.currency = currency
  skuContext.unit_amount = unitAmount
  skuContext.settlement_currency = chargeCurrency
  skuContext.charge_amount = chargeAmount

  const supabase = createClient()
  const { data: { user }, error: authError } = await supabase.auth.getUser()
  failureUserId = user?.id ?? null
  await recordCheckoutEvent('checkout_attempted', user?.id ?? null, skuContext, browserSessionId)
  if (authError || !user) {
    await recordCheckoutEvent('checkout_auth_required', null, skuContext, browserSessionId)
    if (!isGet) return jsonError('You must be signed in to buy the Studio Ads pass.', 401)
    if (req.nextUrl.searchParams.get('resumed') === '1') {
      return redirectError('We could not confirm your sign-in. Please sign in and try again.')
    }
    const resume = `${req.nextUrl.pathname}${req.nextUrl.search}${req.nextUrl.search ? '&' : '?'}resumed=1`
    return NextResponse.redirect(`${appUrl}/login?reason=checkout&redirect=${encodeURIComponent(resume)}`)
  }
  // Interruptor: desligado, só conta interna passa (canário). Recusa visível, com o motivo gravado.
  // KINEO-STUDIO-ADS-REVISAO-2026-09-24 — interna = lista EXATA + apelidos do fundador, pelo e-mail do auth (os
  // padrões LIKE de métrica casavam com estranhos: 'test%', '%mailinator%').
  if (!adsPassLive() && !isAdsInternalEmail(user.email)) {
    return isGet ? redirectError('Studio Ads opens soon.') : jsonError('Studio Ads opens soon.', 403)
  }
  // Nunca cobrar antes de a coluna do acesso existir: sem ela o webhook falha, a Stripe desiste depois de dias de
  // reenvio e a pessoa fica cobrada sem acesso. Sonda barata (limit 0) com a chave de serviço.
  {
    const svcUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
    const svcKey = process.env.SUPABASE_SERVICE_ROLE_KEY
    const probe = svcUrl && svcKey
      ? await createAdminClient(svcUrl, svcKey, { auth: { persistSession: false, autoRefreshToken: false } }).from('profiles').select(ADS_ACCESS_COLUMN).limit(0)
      : { error: { code: 'no_service_key', message: 'service key missing' } }
    if (probe.error) {
      console.error('[stripe/checkout] ads pass blocked: access column not ready', probe.error.code, probe.error.message)
      skuContext.blocked = 'migration_missing'
      return isGet ? redirectError('Studio Ads opens soon.') : jsonError('Studio Ads opens soon.', 503)
    }
  }

  const { data: profile } = await supabase
    .from('profiles')
    .select('email, stripe_customer_id')
    .eq('id', user.id)
    .single()

  const sessionParams: Stripe.Checkout.SessionCreateParams = {
    mode: 'payment',
    line_items: [
      {
        price_data: {
          currency: chargeCurrency,
          product_data: {
            name: `Kineo — ${ADS_PRODUCT_NAME} pass`,
            description: `${ADS_PASS_CREDITS} credits and 12 months of Studio Ads. ${minutesLine(ADS_PASS_CREDITS)} (alternative uses of the same credits). One-time payment, no subscription.`,
          },
          unit_amount: chargeAmount,
        },
        quantity: 1,
      },
    ],
    client_reference_id: user.id,
    success_url: `${appUrl}/ads/new?resume=pass&session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${appUrl}/ads?checkout=cancelled`,
    metadata: {
      supabase_user_id: user.id,
      // metadata.pack é o que o webhook lê para conceder o acesso; sem ela a sessão cai no "valor desconhecido".
      pack: ADS_PASS_ID,
      pack_credits: String(ADS_PASS_CREDITS),
      ads_offer_version: ADS_OFFER_VERSION,
    },
  }
  if (profile?.stripe_customer_id) sessionParams.customer = profile.stripe_customer_id
  else sessionParams.customer_email = profile?.email ?? user.email ?? undefined

  const adsIdempotencyKey = oneTimeIdempotencyKey({
    sku: ADS_PASS_ID,
    user_id: user.id,
    currency: chargeCurrency,
    unit_amount: chargeAmount,
    contract_version: ADS_OFFER_VERSION,
    // A copy-only deploy must not reuse a Stripe key with different product parameters.
    description: sessionParams.line_items?.[0]?.price_data?.product_data?.description,
    customer: sessionParams.customer ?? null,
  })

  let session: Stripe.Checkout.Session
  try {
    session = await stripe.checkout.sessions.create(sessionParams, { idempotencyKey: adsIdempotencyKey })
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    if (msg.toLowerCase().includes('cannot combine currencies')) {
      delete sessionParams.customer
      sessionParams.customer_email = profile?.email ?? user.email ?? undefined
      try {
        session = await stripe.checkout.sessions.create(sessionParams, { idempotencyKey: `${adsIdempotencyKey}:email` })
      } catch (retryErr) {
        const rmsg = retryErr instanceof Error ? retryErr.message : String(retryErr)
        console.error('[stripe/checkout] ads pass retry failed:', rmsg)
        return isGet ? redirectError(`Payment session failed: ${rmsg || 'Please try again'}`) : jsonError('Payment session failed.', 500)
      }
    } else {
      console.error('[stripe/checkout] ads pass session error:', msg)
      return isGet ? redirectError(`Payment session failed: ${msg || 'Please try again'}`) : jsonError('Payment session failed.', 500)
    }
  }

  console.log(`[stripe/checkout] ads pass session: user=${user.id.slice(0, 8)} amount=${chargeAmount} ${chargeCurrency}`)
  await recordCheckoutEvent('checkout_started', user.id, { ...skuContext, stripe_session_id: session.id }, browserSessionId)
  await recordCheckoutEvent('ads_checkout_started', user.id, { ...skuContext, stripe_session_id: session.id }, browserSessionId)
  return isGet ? NextResponse.redirect(session.url!) : NextResponse.json({ url: session.url })
}

// ═══ KINEO-PACOTE-3-FILMES-1610 — "3 filmes feitos por nós" (?pack=dfy_films3&order=<uuid>) ═══════════════════════
// Mesmo trilho do passe avulso e do passe do Studio Ads: Checkout Session mode 'payment', price_data inline (nenhum
// produto/preço criado na Stripe), preço de lista em USD e moeda de liquidação do país (Brasil = reais pela fórmula da
// casa), chave de idempotência por pedido. O briefing foi salvo ANTES por /api/dfy-films/order; aqui só entra o id do
// pedido, conferido contra o dono e o status 'pending_payment'. O webhook reconhece a sessão por metadata.pack exata e
// marca o pedido pago (sem crédito, sem plano: o filme é feito por gente).
async function buildDfyFilms3AndRedirect(req: NextRequest): Promise<NextResponse> {
  const appUrl = req.nextUrl.origin
  const browserSessionId = browserSessionIdFrom(req)
  let failureUserId: string | null = null
  const skuContext: Record<string, unknown> = { sku: DFY_FILMS3_PACK_ID, mode: 'payment', dfy_version: DFY_FILMS3_VERSION }
  async function redirectError(msg: string) {
    await recordCheckoutEvent('checkout_failed', failureUserId, { ...skuContext, stage: 'redirect', reason: checkoutFailureReason(msg) }, browserSessionId)
    return NextResponse.redirect(`${appUrl}/done-for-you?checkout_error=${encodeURIComponent(msg)}`)
  }
  if (!process.env.STRIPE_SECRET_KEY) {
    console.error('[stripe/checkout] STRIPE_SECRET_KEY is not set')
    return redirectError('Payment service is not configured. Please contact support.')
  }

  const unitAmount = DFY_FILMS3_PRICE_USD_MINOR
  const settlement = resolveSettlementCurrency({
    ipCountry: req.headers.get('x-vercel-ip-country') ?? 'US',
    acceptLanguage: req.headers.get('accept-language'),
    forced: req.nextUrl.searchParams.get('currency'),
  })
  const chargeCurrency = settlement.currency
  const chargeAmount = settlementAmountMinor(unitAmount, chargeCurrency)
  skuContext.currency = 'usd'
  skuContext.unit_amount = unitAmount
  skuContext.settlement_currency = chargeCurrency
  skuContext.charge_amount = chargeAmount

  const supabase = createClient()
  const { data: { user }, error: authError } = await supabase.auth.getUser()
  failureUserId = user?.id ?? null
  await recordCheckoutEvent('checkout_attempted', user?.id ?? null, skuContext, browserSessionId)
  if (authError || !user) {
    await recordCheckoutEvent('checkout_auth_required', null, skuContext, browserSessionId)
    // A página exige login; quem chega aqui sem sessão volta para ela depois do cadastro (o briefing é refeito lá).
    return NextResponse.redirect(`${appUrl}/signup?redirect=${encodeURIComponent('/done-for-you')}`)
  }

  const orderId = (req.nextUrl.searchParams.get('order') ?? '').trim()
  if (!/^[0-9a-f-]{36}$/i.test(orderId)) return redirectError('Write your topic first, then pay.')
  skuContext.dfy_order_id = orderId

  const svcUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
  const svcKey = process.env.SUPABASE_SERVICE_ROLE_KEY
  if (!svcUrl || !svcKey) return redirectError('This offer is temporarily unavailable.')
  const admin = createAdminClient(svcUrl, svcKey, { auth: { persistSession: false, autoRefreshToken: false } })
  const [{ data: order, error: orderErr }, { data: profile }] = await Promise.all([
    admin.from('done_for_you_orders').select('id, user_id, status, topic, language, style').eq('id', orderId).maybeSingle(),
    admin.from('profiles').select('email, stripe_customer_id, plan').eq('id', user.id).maybeSingle(),
  ])
  if (orderErr) {
    console.error('[stripe/checkout] dfy films order read failed:', orderErr.code, orderErr.message)
    return redirectError('This offer is temporarily unavailable.')
  }
  if (!order || order.user_id !== user.id) return redirectError('We could not find your order. Please write your topic again.')
  if (order.status !== 'pending_payment') return redirectError('This order is already paid. We are on it.')
  if (!dfyFilms3Eligible(profile)) return redirectError('You already have a plan: your credits make these films in the Studio.')

  const sessionParams: Stripe.Checkout.SessionCreateParams = {
    mode: 'payment',
    line_items: [
      {
        price_data: {
          currency: chargeCurrency,
          product_data: {
            name: `Kineo — ${DFY_FILMS3_FILMS} films made for you`,
            description: `${DFY_FILMS3_FILMS} short films (~${DFY_FILMS3_FILM_SECONDS} s each) made by the Kineo team on your topic, delivered to your Library within ${DFY_FILMS3_DELIVERY_HOURS} hours. One-time payment, no subscription.`,
          },
          unit_amount: chargeAmount,
        },
        quantity: 1,
      },
    ],
    client_reference_id: user.id,
    success_url: `${appUrl}/done-for-you?paid=1&session_id={CHECKOUT_SESSION_ID}`,
    cancel_url: `${appUrl}/done-for-you?checkout=cancelled`,
    metadata: {
      supabase_user_id: user.id,
      // metadata.pack é a ÚNICA chave do webhook para este pacote (1900 também é o valor do bulk10).
      pack: DFY_FILMS3_PACK_ID,
      dfy_order_id: orderId,
      dfy_version: DFY_FILMS3_VERSION,
      ...briefMetadata({ topic: String(order.topic ?? ''), language: String(order.language ?? ''), style: typeof order.style === 'string' ? order.style : null }),
    },
  }
  if (profile?.stripe_customer_id) sessionParams.customer = profile.stripe_customer_id
  else sessionParams.customer_email = profile?.email ?? user.email ?? undefined

  const dfyIdempotencyKey = oneTimeIdempotencyKey({
    sku: DFY_FILMS3_PACK_ID,
    user_id: user.id,
    order_id: orderId,
    currency: chargeCurrency,
    unit_amount: chargeAmount,
    contract_version: DFY_FILMS3_VERSION,
    description: sessionParams.line_items?.[0]?.price_data?.product_data?.description,
    customer: sessionParams.customer ?? null,
  })

  let session: Stripe.Checkout.Session
  try {
    session = await stripe.checkout.sessions.create(sessionParams, { idempotencyKey: dfyIdempotencyKey })
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    if (msg.toLowerCase().includes('cannot combine currencies')) {
      delete sessionParams.customer
      sessionParams.customer_email = profile?.email ?? user.email ?? undefined
      try {
        session = await stripe.checkout.sessions.create(sessionParams, { idempotencyKey: `${dfyIdempotencyKey}:email` })
      } catch (retryErr) {
        console.error('[stripe/checkout] dfy films retry failed:', retryErr instanceof Error ? retryErr.message : String(retryErr))
        return redirectError('Payment session failed. Please try again.')
      }
    } else {
      console.error('[stripe/checkout] dfy films session error:', msg)
      return redirectError('Payment session failed. Please try again.')
    }
  }

  console.log(`[stripe/checkout] dfy films session: user=${user.id.slice(0, 8)} order=${orderId.slice(0, 8)} amount=${chargeAmount} ${chargeCurrency}`)
  await recordCheckoutEvent('checkout_started', user.id, { ...skuContext, stripe_session_id: session.id }, browserSessionId)
  return NextResponse.redirect(session.url!)
}

// KINEO-AVATAR-PACKS-RETIRED-2026-07-06 — buildAvatarPackAndRedirect() removed.
// Avatar packs sold profiles.avatar_credits, now unspendable (avatar generation
// costs 120 universal video_credits). ?pack=avatar* now returns a clean 410 in
// the GET handler below instead of creating a Stripe session.

// ─── GET handler (iOS Safari safe — server-side redirect) ────────────────────
// Buttons set window.location.href = '/api/stripe/checkout?tier=basic' so
// the browser navigates synchronously (no await / no gesture-chain break).
export async function GET(req: NextRequest) {
  try {
    // KINEO-CHECKOUT-TRIAGE-2026-07-25 — a speculative fetch is not a purchase.
    // Bounce it BEFORE any Supabase or Stripe work so link scanners and browser
    // preloading can never mint a Checkout Session for a tier nobody clicked.
    if (isSpeculativeRequest(req)) {
      const selection =
        req.nextUrl.searchParams.get('pack') ?? req.nextUrl.searchParams.get('tier') ?? 'basic'
      return await speculativeNoop(req, selection)
    }

    // KINEO-SCANNER-DENOMINADOR-2026-08-16 — termômetro, não portão. Roda
    // DEPOIS do ramo acima (quem se anuncia continua sendo
    // `checkout_prefetch_blocked`, sem contagem dupla) e NÃO altera o fluxo:
    // a requisição segue para o mesmo lugar de antes, com ou sem suspeita.
    // `await` porque o handler pode redirecionar em milissegundos e um
    // fire-and-forget perderia justamente as rajadas de scanner.
    await recordBotSuspicion(
      req,
      req.nextUrl.searchParams.get('pack') ?? req.nextUrl.searchParams.get('tier') ?? 'basic',
    )

    // #473 — Starter Pack one-time checkout: /api/stripe/checkout?pack=starter
    const packParam = req.nextUrl.searchParams.get('pack')
    if (packParam) {
      // KINEO-AVATAR-PACKS-RETIRED-2026-07-06 — avatar packs are gone. Avatar
      // videos now use universal credits, so avatar_credits packs are unsellable.
      // Return a clean 410 rather than crashing on the removed builder.
      if (packParam === 'avatar1' || packParam === 'avatar3' || packParam === 'avatar10') {
        return NextResponse.json(
          { error: 'Avatar packs retired — avatar videos now use universal credits' },
          { status: 410 },
        )
      }
      // KINEO-TOPUP-2026-07-06 — AI credit top-ups (Creator+).
      if (packParam === 'topup40' || packParam === 'topup120' || packParam === 'topup100' || packParam === 'topup300') {
        return await buildTopupAndRedirect(req, packParam, true)
      }
      // KINEO-BARRA-DE-CREDITOS-2026-09-23 — quantidade escolhida na barra; inválida vira erro visível, nunca outro pacote.
      if (packParam === CREDIT_SLIDER_PACK_ID) {
        return await buildTopupAndRedirect(req, CREDIT_SLIDER_PACK_ID, true, normalizeSliderCredits(req.nextUrl.searchParams.get('credits')))
      }
      // KINEO-BULK-2026-07-27 — pacotes de atacado. Precisa vir ANTES do
      // fallback buildPackAndRedirect, que venderia um Starter Pack de $4.90 no
      // lugar de um pacote de $379 sem dar erro nenhum — a mesma armadilha
      // documentada no branch do autopilot_pilot logo abaixo.
      // KINEO-STUDIO-ADS-2026-09-25 — passe do Studio Ads (desligado por NEXT_PUBLIC_ADS_PASS_LIVE; interno passa).
      if (packParam === ADS_PASS_ID) {
        return await buildAdsPassAndRedirect(req, true)
      }
      // KINEO-PACOTE-3-FILMES-1610 — "3 filmes feitos por nós" (US$ 19, único). ANTES do fallback buildPackAndRedirect,
      // que venderia um Starter Pack no lugar sem erro nenhum.
      if (packParam === DFY_FILMS3_PACK_ID) {
        return await buildDfyFilms3AndRedirect(req)
      }
      if (packParam === KIT_BF_PACK_ID) return await buildKitBfAndRedirect(req, { recordCheckoutEvent, browserSessionIdFrom, checkoutFailureReason, oneTimeIdempotencyKey }) // KINEO-KIT-BF-VENDA-2010 — ANTES do fallback buildPackAndRedirect (que venderia um Starter Pack no lugar)
      if (packParam === KIDS_PACK_ID || packParam === KIDS_AUTOPILOT_ID) return await buildKidsVendaAndRedirect(req, { recordCheckoutEvent, browserSessionIdFrom, checkoutFailureReason, oneTimeIdempotencyKey }) // KINEO-KIDS-VENDA-2010 — ANTES do fallback buildPackAndRedirect (que venderia um Starter Pack no lugar); KIDS_SALES_LIVE=false recusa quem não é da casa
      if (isBulkPackId(packParam)) {
        const closedPack = await refuseClosedBulkPackCheckout(req, packParam) // KINEO-PAGINAS-QUE-VENDEM-2026-10-12
        if (closedPack) return closedPack
        return await buildBulkPackAndRedirect(req, packParam, true)
      }
      // KINEO-PILOT-99-2026-07-26 — sem este branch o ?pack=autopilot_pilot cai
      // no buildPackAndRedirect e vende um Starter Pack de $4.90 no lugar.
      if (packParam === 'autopilot_pilot') {
        const closed = await refuseClosedAutopilotCheckout(req, packParam) // KINEO-AUTOPILOT-FORA-2026-10-09
        if (closed) return closed
        return await buildAutopilotPilotAndRedirect(req, true)
      }
      // KINEO-OFFER290-2026-07-07 — first-purchase $2.90 offer (flag-gated).
      if (packParam === 'starter290') {
        return await buildStarter290AndRedirect(req, true)
      }
      return await buildPackAndRedirect(req, true)
    }
    const tierParam = req.nextUrl.searchParams.get('tier') ?? 'basic'
    // KINEO-AUTOPILOT-299-2026-07-26 — ?tier=autopilot added. Unknown values
    // still fall through to 'basic', unchanged.
    const tier: PlanTier =
      tierParam === 'pro' ? 'pro'
        : tierParam === 'starter' ? 'starter'
          : tierParam === 'autopilot' ? 'autopilot'
            : tierParam === 'autopilot_lite' ? 'autopilot_lite' // KINEO-AUTOPILOT-LITE
              : tierParam === 'business' ? 'business' // KINEO-BUSINESS-84-2026-10-09
                : 'basic'
    // KINEO-AUTOPILOT-FORA-2026-10-09 — Autopilot / Autopilot Lite fechados para compra nova (interna passa).
    const closedTier = await refuseClosedAutopilotCheckout(req, tier)
    if (closedTier) return closedTier
    const billing: Billing = req.nextUrl.searchParams.get('billing') === 'annual' ? 'annual' : 'monthly'
    const promo = req.nextUrl.searchParams.get('promo') ?? undefined
    // KINEO-INTRO-MONTH-2026-07-13 — ?intro=1 → 1º mês com desconto.
    const intro = req.nextUrl.searchParams.get('intro') === '1'
    return await buildAndRedirect(req, tier, true, billing, promo, intro)
  } catch {
    // KINEO-CHECKOUT-SETUP-FAILURE-RETURN-V1-2026-09-01 — this terminal path
    // happens before a Stripe Session exists, so the existing redirect
    // watchdog cannot rescue it. Keep the buyer's exact, same-origin checkout
    // choice and give Pricing a deterministic retry. The exception body is
    // deliberately absent from logs and telemetry: provider errors can echo
    // customer or promotion data.
    console.error('[stripe/checkout GET] Unexpected error before checkout redirect')
    const destination = `${req.nextUrl.pathname}${req.nextUrl.search}`
    const recovery = readCheckoutSetupFailureContext(destination)
    await recordCheckoutEvent(
      'checkout_failed',
      null,
      {
        stage: 'outer_get',
        reason: 'unexpected_server_error',
        ...(recovery ? checkoutSetupFailureTelemetry(recovery) : {}),
      },
      browserSessionIdFrom(req),
    )
    const appUrl = req.nextUrl.origin
    return NextResponse.redirect(`${appUrl}${buildCheckoutSetupFailureReturnHref(destination)}`)
  }
}

