// ═══════════════════════════════════════════════════════════════════════════
// KINEO-RECUSA-COM-NOME-2026-09-07 — A RECUSA DE CARTÃO PASSA A TER DONO.
// ═══════════════════════════════════════════════════════════════════════════
// O NÚMERO QUE MANDOU ESCREVER ISTO (medido 07/09, base inteira; o instrumento
// nasceu em 03/09): `checkout_payment_failed` tem 3 linhas na história.
//   · 2 com `stage: 'renewal'` — e as DUAS têm user_id.
//   · 1 com `stage: 'initial'` (07/09 05:35 UTC, Visa PRÉ-PAGO dos EUA,
//     `card_restricted`, US$ 23,20) — e ela veio com **user_id NULL**.
// Não é coincidência, é estrutural, e a razão é mecânica:
//
//   1. Numa sessão `mode: 'subscription'`, a Stripe cria o PaymentIntent a
//      partir da FATURA. `session.metadata` e `subscription_data.metadata`
//      pousam na Sessão e na Assinatura — **nunca no PaymentIntent**
//      (`payment_intent_data` só é aceito em `mode: 'payment'`). Logo
//      `failedIntent.metadata.supabase_user_id` é null SEMPRE por aqui.
//   2. O único plano B que existia era `profiles.stripe_customer_id` — coluna
//      que só é escrita quando um pagamento DÁ CERTO
//      (`checkout.session.completed`).
//
// Junte os dois: a casa só conseguia nomear quem JÁ PAGOU alguma vez. As duas
// renovações resolveram porque o pagante já tinha a coluna preenchida; o
// primeiro comprador recusado é anônimo por construção. E é exatamente ele o
// alvo do pedido do fundador de 07/09 ("o cara do cartão recusado"): quem
// nunca pagou é o único que ainda pode virar assinante novo.
//
// Uma recusa anônima não tem remédio — não dá para escrever para ela, nem para
// contá-la por país, nem para saber que plano ela tentou. O evento nascia como
// beco sem saída.
//
// O CONSERTO NÃO INVENTA FONTE NOVA: a fatura JÁ ERA BUSCADA aqui embaixo, e
// dessa viagem só se aproveitava `billing_reason`. `invoice.subscription` leva
// à Assinatura, cuja metadata carrega `supabase_user_id`, `tier` e
// `checkout_origin`; e `checkout.sessions.list({ subscription })` devolve a
// Sessão, que é a única que carrega `ip_country` — o campo que decide se a
// hipótese Índia/Nigéria é verdade. O recurso estava sendo buscado e jogado
// fora.
//
// ⚠️ ESCADA, e a ordem importa: cada degrau é uma chamada a mais na Stripe, e
// este handler roda dentro do webhook. Para no PRIMEIRO que resolve, e nunca
// passa de 4 chamadas extras. Qualquer degrau que estoure é engolido —
// identidade é enriquecimento, e um erro de leitura aqui NÃO pode derrubar o
// registro da recusa, que é o dado que importa.
//
// ⚠️ `identity_source` viaja no evento DE PROPÓSITO: sem ele, um user_id
// preenchido não diz se veio de metadata (fato) ou de casamento por e-mail
// (inferência). Quem for mandar e-mail com base nisto precisa saber a diferença.
type PaymentIntentFailureContext = {
  hasInvoice: boolean
  billingReason: string | null
  ownerUserId: string | null
  identitySource: string
  checkoutSessionId: string | null
  subscriptionId: string | null
  tier: string | null
  ipCountry: string | null
  checkoutOrigin: string | null
}

async function resolvePaymentIntentInvoiceContext(
  paymentIntent: Stripe.PaymentIntent,
  supabase?: AdminClient,
): Promise<PaymentIntentFailureContext> {
  const runtimeIntent = paymentIntent as unknown as {
    invoice?: unknown
    latest_charge?: unknown
  }
  let invoiceId = stripeObjectId(runtimeIntent.invoice)
  let invoiceLookupUncertain = false

  if (!invoiceId) {
    const runtimeError = paymentIntent.last_payment_error as unknown as { charge?: unknown } | null
    const chargeId = stripeObjectId(runtimeError?.charge) ?? stripeObjectId(runtimeIntent.latest_charge)
    if (chargeId) {
      try {
        const charge = await stripe.charges.retrieve(chargeId)
        invoiceId = stripeObjectId((charge as Stripe.Charge & { invoice?: unknown }).invoice)
      } catch {
        // We cannot safely call this initial: the missing lookup may hide a
        // renewal invoice. Unknown is an explicit stop signal for the gate.
        invoiceLookupUncertain = true
      }
    }
  }

  // Identidade começa no degrau mais barato e mais confiável: a metadata do
  // próprio intent. Ela existe para compra avulsa (`mode: 'payment'`, onde
  // `payment_intent_data` é aceito) e nunca para assinatura.
  let ownerUserId: string | null = paymentIntent.metadata?.supabase_user_id ?? null
  let identitySource = ownerUserId ? 'intent_metadata' : 'none'
  let checkoutSessionId: string | null = null
  let subscriptionId: string | null = null
  let tier: string | null = paymentIntent.metadata?.tier ?? null
  let ipCountry: string | null = paymentIntent.metadata?.ip_country ?? null
  let checkoutOrigin: string | null = paymentIntent.metadata?.checkout_origin ?? null

  const absorve = (metadata: Stripe.Metadata | null | undefined): void => {
    if (!metadata) return
    tier = tier ?? metadata.tier ?? null
    ipCountry = ipCountry ?? metadata.ip_country ?? null
    checkoutOrigin = checkoutOrigin ?? metadata.checkout_origin ?? null
  }

  const resolvePorSessaoDeCheckout = async (
    filtro: { payment_intent: string } | { subscription: string },
  ): Promise<void> => {
    try {
      const sessions = await stripe.checkout.sessions.list({ ...filtro, limit: 1 })
      const session = sessions.data[0]
      if (!session) return
      checkoutSessionId = session.id
      absorve(session.metadata)
      const fromSession = session.metadata?.supabase_user_id ?? null
      if (!ownerUserId && fromSession) {
        ownerUserId = fromSession
        identitySource = 'checkout_session'
      }
    } catch {
      // lista indisponível: identidade continua no degrau anterior
    }
  }

  /** Últimos dois degraus, e os únicos que dependem do banco. `customer_id` só
   *  existe em quem JÁ pagou; o casamento por e-mail é o que alcança o primeiro
   *  comprador recusado — e por isso é marcado como INFERÊNCIA. */
  const resolvePorCliente = async (): Promise<void> => {
    if (ownerUserId || !supabase) return
    const customerId =
      typeof paymentIntent.customer === 'string'
        ? paymentIntent.customer
        : paymentIntent.customer?.id ?? null
    if (!customerId) return

    try {
      const { data: byCustomer } = await supabase
        .from('profiles')
        .select('id')
        .eq('stripe_customer_id', customerId)
        .limit(1)
      if (byCustomer?.[0]?.id) {
        ownerUserId = byCustomer[0].id
        identitySource = 'customer_id'
        return
      }
    } catch {
      // segue para o e-mail
    }

    try {
      const customer = await stripe.customers.retrieve(customerId)
      if (customer.deleted) return
      const email = (customer.email ?? '').trim().toLowerCase()
      if (!email) return
      const { data: byEmail } = await supabase
        .from('profiles')
        .select('id')
        .ilike('email', email)
        .limit(1)
      if (byEmail?.[0]?.id) {
        ownerUserId = byEmail[0].id
        identitySource = 'customer_email'
      }
    } catch {
      // anônima mesmo: `identity_source: 'none'` é a resposta honesta
    }
  }

  // Sem fatura: ou é compra avulsa, ou a leitura falhou. A Sessão de Checkout
  // ainda pode ser achada pelo próprio PaymentIntent — é o caminho do pacote de
  // crédito, que não passa por fatura nenhuma.
  if (!invoiceId) {
    await resolvePorSessaoDeCheckout({ payment_intent: paymentIntent.id })
    await resolvePorCliente()
    return {
      hasInvoice: invoiceLookupUncertain,
      billingReason: null,
      ownerUserId,
      identitySource,
      checkoutSessionId,
      subscriptionId,
      tier,
      ipCountry,
      checkoutOrigin,
    }
  }

  let billingReason: string | null = null
  try {
    const invoice = await stripe.invoices.retrieve(invoiceId)
    billingReason = invoice.billing_reason ?? null
    subscriptionId = stripeObjectId(
      (invoice as Stripe.Invoice & { subscription?: unknown }).subscription,
    )
  } catch {
    // A fatura existe (o id veio de algum lugar), só não pôde ser lida.
  }

  if (!ownerUserId && subscriptionId) {
    try {
      const subscription = await stripe.subscriptions.retrieve(subscriptionId)
      absorve(subscription.metadata)
      const fromSubscription = subscription.metadata?.supabase_user_id ?? null
      if (fromSubscription) {
        ownerUserId = fromSubscription
        identitySource = 'invoice_subscription'
      }
    } catch {
      // sem assinatura legível, a escada segue
    }
  }

  // A Sessão é buscada mesmo quando a Assinatura já deu o dono: ela é a ÚNICA
  // que carrega `ip_country`, e sem país esta recusa não entra na contagem por
  // país que decide trilho de pagamento.
  if (subscriptionId && (!ipCountry || !checkoutSessionId)) {
    await resolvePorSessaoDeCheckout({ subscription: subscriptionId })
  }
  await resolvePorCliente()

  return {
    hasInvoice: true,
    billingReason,
    ownerUserId,
    identitySource,
    checkoutSessionId,
    subscriptionId,
    tier,
    ipCountry,
    checkoutOrigin,
  }
}

async function isProtectedProfile(
  supabase: AdminClient,
  filter: { userId?: string; customerId?: string }
): Promise<boolean> {
  let query = supabase.from('profiles').select('email').limit(1)
  if (filter.userId) query = query.eq('id', filter.userId)
  else if (filter.customerId) query = query.eq('stripe_customer_id', filter.customerId)
  else return false

  const { data, error } = await query.single()
  if (error) {
    // No matching profile means the account is simply not protected; retain
    // the previous behavior while propagating actual database failures.
    if (error.code === 'PGRST116') return false
    throw new RetryableEntitlementError(
      `Failed to check protected profile: ${error.code ?? 'unknown'} ${error.message}`
    )
  }
  return PROTECTED_EMAILS.has((data?.email ?? '').toLowerCase())
}

// ═══ KINEO-CUPOM-AFILIADO-2026-08-21 — ATRIBUIÇÃO SEM LINK ══════════════
//
// O buraco: nosso afiliado só ganha se o comprador CLICAR no link /a/CODIGO.
// Isso funciona em post de blog e newsletter, e falha exatamente onde estão
// os criadores que queremos — TikTok, Reels e Shorts, onde não há link
// clicável no vídeo. O criador fala "usa JOAO20", a pessoa digita no
// checkout, paga, e o criador não ganha nada. Ele descobre, para de divulgar.
//
// A trava não era falta de tabela: `affiliates.coupon_code` JÁ EXISTE e o
// admin JÁ deixa preencher. O que faltava é ninguém LER na hora do dinheiro.
//
// Como funciona agora: se o comprador não tem link (affiliate_id null), a
// gente olha o código promocional que ele digitou na Stripe, traduz o ID
// para o texto do cupom, e procura um afiliado dono daquele texto. Achou →
// comissão paga E o perfil fica carimbado, então TODA RENOVAÇÃO futura já
// credita sozinha (recorrência não passa por cupom nenhum).
//
// Ordem de precedência deliberada: LINK GANHA DO CUPOM. Quem clicou primeiro
// é o dono da indicação (first-touch, mesma regra do /a/[code]). O cupom é
// só a rede de segurança de quem chegou sem link.
async function resolveAffiliateByCoupon(
  supabase: AdminClient,
  session: Stripe.Checkout.Session,
  compradorUserId: string
): Promise<string | null> {
  try {
    // Atalho barato: `amount_discount` JÁ vem no corpo do webhook. A maioria
    // esmagadora dos pagamentos não usa cupom nenhum, e sem esta linha toda
    // compra pagaria duas chamadas extras à Stripe por nada.
    if (!session.total_details?.amount_discount) return null

    // ⚠ CUIDADO AO MEXER: `session.discounts` NÃO EXISTE nesta versão do SDK
    // (stripe 16, apiVersion 2024-06-20) — escrevi assim na primeira tentativa
    // e o tsc pegou. O desconto só aparece em `total_details.breakdown`, que
    // NÃO vem no corpo do webhook: precisa de um retrieve com expand. Como
    // `ignoreBuildErrors` está ligado no next.config, um acesso a campo
    // inexistente compilaria e viraria `undefined` calado em produção — o
    // trilho inteiro nunca dispararia e ninguém perceberia.
    const cheia = await stripe.checkout.sessions.retrieve(session.id, {
      expand: ['total_details.breakdown.discounts'],
    })
    const promoRaw = cheia.total_details?.breakdown?.discounts?.[0]?.discount?.promotion_code
    if (!promoRaw) return null
    // Pode vir expandido (objeto) ou como id cru (promo_xxx). O texto que a
    // pessoa digitou ("KINEOABC123") é o `.code`.
    const code =
      typeof promoRaw === 'string'
        ? ((await stripe.promotionCodes.retrieve(promoRaw))?.code ?? '').trim()
        : (promoRaw.code ?? '').trim()
    if (!code) return null

    // ⚠ COMPARAÇÃO EXATA, NÃO `ilike`. O texto vem do cliente e o `ilike` do
    // PostgREST trata `%` e `_` como CURINGAS: um código digitado como "KINEO%"
    // casaria com o cupom de QUALQUER afiliado. Os códigos que nós cunhamos são
    // [A-Z0-9] e nunca teriam esse problema, mas o admin grava `coupon_code` em
    // texto livre — a porta existia.
    const codeUpper = code.toUpperCase()
    if (!/^[A-Z0-9]{4,24}$/.test(codeUpper)) return null
    const { data: candidatos, error: buscaErro } = await supabase
      .from('affiliates')
      .select('id, user_id, status, coupon_code')
      .eq('coupon_code', codeUpper)
      .limit(2)
    if (buscaErro) {
      throw new AffiliateLedgerIntegrityError('Could not resolve affiliate coupon owner')
    }
    // Dois afiliados com o mesmo texto = ambiguidade. Pagar ao "primeiro" seria
    // sortear o dono do dinheiro; melhor não pagar e deixar rastro no log.
    if (!candidatos || candidatos.length !== 1) {
      if (candidatos && candidatos.length > 1) {
        console.error(`[affiliate coupon] AMBIGUO: ${candidatos.length} afiliados com o cupom ${codeUpper}`)
        throw new AffiliateLedgerIntegrityError('Affiliate coupon has more than one owner')
      }
      return null
    }
    const aff = candidatos[0]
    if (aff.status !== 'active') return null

    // ⚠ AUTO-INDICAÇÃO. Sem isto, qualquer pessoa vira afiliado em dois cliques
    // (apply nasce 'active'), abre /affiliate para o cupom ser cunhado, e assina
    // com o próprio código — levando 40% de si mesma, TODO MÊS, para sempre.
    // A margem do Creator é ~$10; menos $6 de comissão sobra $4, e quem consumir
    // os créditos todos vira prejuízo permanente. O guard equivalente já existia
    // em /api/affiliate/attribute e não tinha sido espelhado aqui.
    if (aff.user_id && aff.user_id === compradorUserId) {
      console.warn(`[affiliate coupon] auto-indicacao bloqueada: user ${compradorUserId}`)
      return null
    }
    return aff.id as string
  } catch (err) {
    if (err instanceof AffiliateLedgerIntegrityError) throw err
    throw new AffiliateLedgerIntegrityError('Could not verify Stripe affiliate coupon')
  }
}

// KINEO-AGENCIAS-2026-10-13 — o tipo do parceiro (affiliates.partner_type), lido só na cobrança do Business.
// 42703 / PGRST204 = a coluna ainda não existe (migration 20261013120000_agency_program.sql não aplicada) → null (criador).
async function readAffiliatePartnerType(supabase: AdminClient, affiliateId: string): Promise<string | null> {
  const { data, error } = await supabase
    .from('affiliates')
    .select('partner_type')
    .eq('id', affiliateId)
    .maybeSingle()
  if (error) {
    if (error.code === '42703' || error.code === 'PGRST204') return null
    throw new AffiliateLedgerIntegrityError('Could not read affiliate partner type')
  }
  const value = (data as { partner_type?: unknown } | null)?.partner_type
  return typeof value === 'string' ? value : null
}

// #480 — Affiliate commission. If the paying user was attributed to an affiliate
// (profiles.affiliate_id), record a PENDING commission (rate × amount paid).
// Idempotent via unique(provider, external_id). Stays 'pending' until the admin
// approves it (so refunds inside the window simply never get approved/paid).
async function recordAffiliateCommission(
  supabase: AdminClient,
  args: {
    userId: string
    externalId: string
    amountGross: number
    currency: string
    type: 'initial' | 'recurring'
    paymentKind: AffiliatePaymentKind
    attributionSystem?: string | null
    session?: Stripe.Checkout.Session
    /** KINEO-BUSINESS-84-2026-10-09 — metadata.tier CRU da sessão/assinatura que pagou (o mesmo valor de onde sai o tier
     *  do grant). 'business' paga 20%; qualquer outro valor ou ausente = régua de sempre. */
    plan?: string | null
  }
): Promise<void> {
  // Rewardful owns this charge. Suppress the custom ledger so the same
  // initial payment or renewal can never create two affiliate liabilities.
  if (args.attributionSystem === 'rewardful') return
  if (!args.userId || !args.externalId) return

  try {
    const { data: prof, error: profileError } = await supabase
      .from('profiles')
      .select('affiliate_id')
      .eq('id', args.userId)
      .single()
    if (profileError) {
      throw new AffiliateLedgerIntegrityError('Could not read paying user affiliate attribution')
    }
    let affiliateId = (prof?.affiliate_id as string | null | undefined) ?? null

    // ⚠ ESTE BLOCO FICA ANTES DO GUARD DE VALOR, DE PROPÓSITO.
    // O `amountGross <= 0` morava três linhas acima e matava a atribuição por
    // cupom antes dela acontecer. Numa sessão que fecha em ZERO — cupom que
    // cobre o valor todo, ou trial sem cobrança — a função retornava cedo, o
    // perfil NUNCA era carimbado, e como a renovação só sabe ler
    // `profiles.affiliate_id`, o criador ficava sem receber PARA SEMPRE. Sem
    // erro, sem log, sem ninguém perceber. O carimbo é atribuição, não
    // pagamento: tem que acontecer mesmo quando não entrou dinheiro hoje.
    if (!affiliateId && args.session) {
      affiliateId = await resolveAffiliateByCoupon(supabase, args.session, args.userId)
      if (affiliateId) {
        // First-touch: a busca é por PESSOA, não por afiliado. Filtrar por
        // afiliado (como estava) não enxergava a indicação de OUTRO criador e
        // deixava o cupom sequestrar uma indicação que já tinha dono — o link
        // de A viraria comissão vitalícia de B por um código digitado.
        const { data: indicacaoExistente, error: indicacaoErro } = await supabase
          .from('affiliate_referrals')
          .select('id, affiliate_id')
          .eq('referred_user_id', args.userId)
          .maybeSingle()
        if (indicacaoErro) {
          throw new AffiliateLedgerIntegrityError('Could not verify first-touch affiliate referral')
        }

        if (indicacaoExistente && indicacaoExistente.affiliate_id !== affiliateId) {
          // Já tem dono e é outro. First-touch vence: honra o primeiro e
          // ignora o cupom. O comprador fica com o desconto; a comissão vai
          // para quem trouxe a pessoa.
          console.warn(
            `[affiliate coupon] cupom de ${affiliateId} ignorado: user ${args.userId} ja indicado por ${indicacaoExistente.affiliate_id}`
          )
          affiliateId = indicacaoExistente.affiliate_id as string
        } else {
          if (!indicacaoExistente) {
            const { error: insErro } = await supabase
              .from('affiliate_referrals')
              .insert({ affiliate_id: affiliateId, referred_user_id: args.userId, status: 'signup' })
            if (insErro && insErro.code !== '23505') {
              throw new AffiliateLedgerIntegrityError('Could not create coupon affiliate referral')
            }
            if (insErro?.code === '23505') {
              const { data: raceWinner, error: raceError } = await supabase
                .from('affiliate_referrals')
                .select('id, affiliate_id')
                .eq('referred_user_id', args.userId)
                .single()
              if (raceError || !raceWinner?.affiliate_id) {
                throw new AffiliateLedgerIntegrityError('Could not reconcile affiliate referral race')
              }
              affiliateId = raceWinner.affiliate_id as string
            }
          }
        }

        // Stamp the canonical first-touch owner, including the case where a
        // coupon lost to an older referral. Renewals only know this profile
        // field, so skipping the repair loses every later commission.
        const { data: stampedProfile, error: carimboErro } = await supabase
          .from('profiles')
          .update({ affiliate_id: affiliateId })
          .eq('id', args.userId)
          .select('id')
          .maybeSingle()
        if (carimboErro || !stampedProfile?.id) {
          throw new AffiliateLedgerIntegrityError('Could not persist canonical affiliate attribution')
        }
        console.log(`[affiliate coupon] user ${args.userId} → affiliate ${affiliateId} (sem link, via cupom)`)
      }
    }
    if (!affiliateId) return
    // Só AGORA o valor importa: atribuição já está gravada acima, e o que este
    // guard evita é lançar uma comissão de valor zero ou negativo.
    if (!args.amountGross || args.amountGross <= 0) return
    const currency = normalizeAffiliateCurrency(args.currency || 'usd')
    const { data: aff, error: affiliateError } = await supabase
      .from('affiliates')
      .select('id, commission_rate, status, created_at')
      .eq('id', affiliateId)
      .single()
    if (affiliateError) {
      throw new AffiliateLedgerIntegrityError('Could not read affiliate commission terms')
    }
    if (!aff || aff.status !== 'active') return
    // KINEO-AFILIADOS-40-2026-10-06 — era `Number(aff.commission_rate ?? 0)`: a taxa gravada na linha (0.3 nas 25
    // linhas de hoje) decidia sozinha. Agora a taxa do programa (lib/affiliateCommission.ts) é piso; maior por pessoa vale.
    // KINEO-AFILIADO-30-NOVOS-2026-10-13 — + created_at: veterano (antes do corte) tem piso 40%, novo 30%.
    const rate = effectiveAffiliateCommissionRate(aff.commission_rate, aff.created_at)
    // KINEO-BUSINESS-84-2026-10-09 — a cobrança do Business paga 20% fixo (lib/affiliateCommission.ts, mesma regra de
    // affiliateCommissionRateForPlan); qualquer outro plano segue a régua de antes (`rate`).
    // KINEO-AGENCIAS-2026-10-13 — no Business, a agência (affiliates.partner_type = 'agency') ganha 30% em vez de 20%.
    // A leitura do tipo é SEPARADA e só acontece em cobrança do Business: o select de cima, e todo plano que não é Business,
    // ficam byte a byte como antes. Coluna ainda inexistente (migration não aplicada) = criador = 20%, nunca erro;
    // qualquer outra falha de leitura lança como a leitura de cima (a Stripe reenvia) — subpagar calado uma agência
    // seria permanente, porque a comissão é gravada uma vez só por cobrança.
    const partnerType = isBusinessCommissionPlan(args.plan) ? await readAffiliatePartnerType(supabase, affiliateId) : null
    const chargeRate = isBusinessCommissionPlan(args.plan) ? businessAffiliateCommissionRate(partnerType) : rate
    const commission = calculateAffiliateCommission(args.amountGross, chargeRate)

    const { data: ref, error: referralError } = await supabase
      .from('affiliate_referrals')
      .select('id, status')
      .eq('affiliate_id', affiliateId)
      .eq('referred_user_id', args.userId)
      .maybeSingle()
    if (referralError) {
      throw new AffiliateLedgerIntegrityError('Could not read affiliate referral for commission')
    }

    const row: AffiliateCommissionRecord = {
      affiliate_id: affiliateId,
      referral_id: ref?.id ?? null,
      provider: 'stripe',
      external_id: args.externalId,
      type: args.type,
      amount_gross: args.amountGross,
      currency,
      commission_amount: commission,
      status: 'pending',
      period: new Date().toISOString().slice(0, 10),
    }

    const outcome = await commitAffiliateCommission({
      async find(provider, externalId) {
        const { data, error } = await supabase
          .from('affiliate_commissions')
          .select('affiliate_id, referral_id, provider, external_id, type, amount_gross, currency, commission_amount')
          .eq('provider', provider)
          .eq('external_id', externalId)
          .maybeSingle()
        if (error) throw new AffiliateLedgerIntegrityError('Could not reconcile affiliate commission')
        return (data as ExistingAffiliateCommission | null) ?? null
      },
      async insert(value) {
        const { error } = await supabase.from('affiliate_commissions').insert(value)
        if (!error) return 'inserted'
        if (error.code === '23505') return 'duplicate'
        throw new AffiliateLedgerIntegrityError('Could not insert affiliate commission')
      },
      async markReferralPaid(referralId, convertedAt) {
        const { data, error } = await supabase
          .from('affiliate_referrals')
          .update({ status: 'paid', converted_at: convertedAt })
          .eq('id', referralId)
          .select('id')
          .maybeSingle()
        if (error || !data?.id) {
          throw new AffiliateLedgerIntegrityError('Could not reconcile paid affiliate referral')
        }
      },
    }, row, new Date().toISOString(), { paymentKind: args.paymentKind })

    if (outcome === 'inserted') {
      console.log(`[affiliate commission] +${commission} (${args.type}) affiliate ${affiliateId} ← user ${args.userId}`)
    }
  } catch (err) {
    const reason = err instanceof AffiliateLedgerIntegrityError ? err.message : 'Unexpected affiliate ledger failure'
    console.error('[affiliate commission] retry required:', reason)
    throw new RetryableAffiliateLedgerError(reason)
  }
}

// KINEO-PAYMENT-EVENT-2026-07-15 — the checkout success page used to be the
// only writer of `payment_success`. Buyers who closed that tab were invisible
// to the funnel, while refreshes could create duplicates. Stripe is the source
// of truth: one verified, deduped webhook event now writes the canonical row.
// ═══ KINEO-RAZAO-ASSINANTE-2026-09-17 — o crédito do 1º pagamento, escrito no próprio evento ═══
// Fundador (17/09, painel ao vivo, valos87196): "73 cr = +150 Creator assinou 29/07 − 2 gastos
// ⚠ −75 sem origem. Está muito confuso." O −75 não era furo: em 29/07 o mês de intro do Creator
// concedia 50 créditos, não 150 — e o painel só podia ADIVINHAR pelo TIER_CREDITS de hoje, porque
// nenhum dos 19 payment_success dos últimos 90 dias registrava o que concedeu. A partir daqui o
// evento carrega `credits_granted` calculado pela MESMA regra do grant (bloco checkout.session.completed
// abaixo: card_trial → CARD_TRIAL_GRANT_CREDITS; trial sem cobrança → TRIAL_GRANT_CREDITS; intro válido
// → intro_credits; senão TIER_CREDITS do tier). Só assinatura; pack/pagamento único devolve null.
function firstPaymentCreditsFromSession(session: Pick<Stripe.Checkout.Session, 'mode' | 'metadata' | 'payment_status'>): number | null {
  if (session.mode !== 'subscription') return null
  const tier: CheckoutPlanTier =
    session.metadata?.tier === 'pro' ? 'pro'
      : session.metadata?.tier === 'starter' ? 'starter'
        : session.metadata?.tier === 'autopilot' ? 'autopilot'
          : session.metadata?.tier === 'autopilot_lite' ? 'autopilot_lite'
            : session.metadata?.tier === 'business' ? 'business' // KINEO-BUSINESS-84-2026-10-09
              : 'basic'
  const planCredits = TIER_CREDITS[tier]
  const introCreditsRaw = Number(session.metadata?.intro_credits ?? 0)
  const introApplied = session.metadata?.intro === '1' &&
    Number.isFinite(introCreditsRaw) &&
    introCreditsRaw > 0 &&
    introCreditsRaw <= planCredits
  const isCardTrial = session.metadata?.card_trial === '1'
  const isTrial = session.payment_status === 'no_payment_required' || isCardTrial
  return isCardTrial ? CARD_TRIAL_GRANT_CREDITS : isTrial ? TRIAL_GRANT_CREDITS : introApplied ? Math.floor(introCreditsRaw) : planCredits
}

// KINEO-DFY-UUID-2026-09-23 — o dono do evento sai de `client_reference_id`,
// que um Payment Link aceita LIVRE (a URL é editável por quem paga; dfyPaymentLink
// só exige [A-Za-z0-9_-]{1,200}). events.user_id é uuid: um valor que não é
// UUID não dá 23503 (FK) e sim 22P02 ("invalid input syntax for type uuid"),
// e o fallback "regrava sem dono" só ouvia 23503 — um pedido PAGO de US$100
// terminaria num console.error. Regra: só é dono quem passa no formato UUID;
// o resto vira null ANTES do insert, e o fallback aceita os dois códigos.
const SESSION_OWNER_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
function sessionOwnerUuid(session: Pick<Stripe.Checkout.Session, 'metadata' | 'client_reference_id'>): string | null {
  return [session.metadata?.supabase_user_id, session.client_reference_id]
    .find((v): v is string => typeof v === 'string' && SESSION_OWNER_UUID.test(v)) ?? null
}
/** 23503 = dono apagado (FK); 22P02 = user_id fora do formato uuid. Nos dois, o pagamento fica sem dono, nunca se perde. */
function isOwnerRejection(code: string | null | undefined): boolean {
  return code === '23503' || code === '22P02'
}

async function recordPaymentSuccess(
  supabase: AdminClient,
  stripeEventId: string,
  session: Stripe.Checkout.Session
): Promise<void> {
  if (session.payment_status !== 'paid') return
  // KINEO-COMPRA-SEM-LOGIN-2026-10-06 — compra de convidado ainda sem dono: quem grava é o Path B, logo depois de
  // achar/criar a conta (com o user_id). Gravar aqui deixaria uma linha sem dono que a deduplicação eternizaria.
  if (isGuestCheckoutSession(session) && !session.metadata?.supabase_user_id) return

  // Entitlement failures intentionally release the stripe_events guard so
  // Stripe can retry. Keep this analytics row idempotent across that retry.
  const { data: existingRows, error: existingError } = await supabase
    .from('events')
    .select('id')
    .eq('name', 'payment_success')
    .contains('metadata', { stripe_session_id: session.id })
    .limit(1)
  if (!existingError && existingRows && existingRows.length > 0) return
  if (existingError) {
    console.error('[stripe webhook] payment_success dedupe lookup error:', existingError.code, existingError.message)
  }

  const userId = sessionOwnerUuid(session)
  // KINEO-EMPRESAS-COCKPIT-2026-09-24 — a metadata do Payment Link (Cowork) traz tier=express|pro, e
  // 'pro' é também o nome de um tier de ASSINATURA: o funil (/api/admin/funnel) e isNewSubscriberEvent
  // liam "tier sem pack" como assinante novo. Pedido Empresas grava tier=null, kind='dfy' e dfy_tier.
  const dfyOrder = session.mode === 'payment' && isDfyOrderSession(session)
  const dfyTier = dfyOrder ? dfySessionTier(session) : null
  const customerId = typeof session.customer === 'string' ? session.customer : session.customer?.id ?? null
  const subscriptionId = typeof session.subscription === 'string'
    ? session.subscription
    : session.subscription?.id ?? null
  const rawBrowserSessionId = session.metadata?.browser_session_id ?? ''
  let browserSessionId: string | null = /^[A-Za-z0-9_-]{8,64}$/.test(rawBrowserSessionId)
    ? rawBrowserSessionId
    : null
  // Checkout idempotency deliberately ignores the originating tab. Keeping a
  // tab id in Stripe metadata would make otherwise-identical requests use the
  // same key with different parameters. Recover attribution from the
  // deterministic checkout_started event instead.
  // KINEO-ANUNCIO-MOTOR-2026-10-07 — a mesma leitura agora roda SEMPRE (antes, só sem browser_session_id) e traz também
  // o clique pago que a rota de checkout gravou no checkout_started (lib/growth/paidClickAttribution.ts, saneado de
  // novo aqui). Com isso o payment_success diz, por si, se a compra veio de anúncio — inclusive a compra sem login, cuja
  // conta nasce neste webhook sem origem nenhuma. Atribuição pura: erro aqui só perde o rótulo, nunca a venda.
  let paidClickMetadata: PaidClickMetadata = {}
  const { data: checkoutRows, error: checkoutLookupError } = await supabase
    .from('events')
    .select('session_id, metadata')
    .eq('name', 'checkout_started')
    .contains('metadata', { stripe_session_id: session.id })
    .limit(1)
  if (checkoutLookupError) {
    console.error('[stripe webhook] checkout_started attribution lookup error:', checkoutLookupError.code, checkoutLookupError.message)
  } else {
    paidClickMetadata = paidClickMetadataFromEvent(checkoutRows?.[0]?.metadata)
    const recoveredSessionId = checkoutRows?.[0]?.session_id
    if (!browserSessionId && typeof recoveredSessionId === 'string' && /^[A-Za-z0-9_-]{8,64}$/.test(recoveredSessionId)) {
      browserSessionId = recoveredSessionId
    }
  }
  const eventHex = createHash('sha256').update(`payment_success:${session.id}`).digest('hex').slice(0, 32)
  const row = {
    id: `${eventHex.slice(0, 8)}-${eventHex.slice(8, 12)}-${eventHex.slice(12, 16)}-${eventHex.slice(16, 20)}-${eventHex.slice(20)}`,
    name: 'payment_success',
    user_id: userId,
    path: '/api/stripe/webhook',
    session_id: browserSessionId,
    metadata: {
      source: 'stripe_webhook',
      stripe_event_id: stripeEventId,
      stripe_session_id: session.id,
      stripe_customer_id: customerId,
      stripe_subscription_id: subscriptionId,
      checkout_mode: session.mode,
      tier: dfyOrder ? null : (session.metadata?.tier ?? null),
      billing: session.metadata?.billing ?? null,
      pack: session.metadata?.pack ?? null,
      checkout_origin: session.metadata?.checkout_origin ?? null,
      intent_campaign: session.metadata?.intent_campaign ?? null,
      checkout_value_context: session.metadata?.checkout_value_context ?? null,
      checkout_value_variant: session.metadata?.checkout_value_variant ?? null,
      checkout_payment_guidance: session.metadata?.checkout_payment_guidance ?? null,
      checkout_value_output_count: session.metadata?.checkout_value_output_count ?? null,
      checkout_session_window_hours: session.metadata?.checkout_session_window_hours ?? null,
      checkout_session_window_version: session.metadata?.checkout_session_window_version ?? null,
      checkout_visual_proof: session.metadata?.checkout_visual_proof ?? null,
      plan_fit_planned_engine: session.metadata?.plan_fit_planned_engine ?? null,
      plan_fit_monthly_videos: session.metadata?.plan_fit_monthly_videos ?? null,
      plan_fit_monthly_credits: session.metadata?.plan_fit_monthly_credits ?? null,
      plan_fit_seconds: session.metadata?.plan_fit_seconds ?? null,
      plan_fit_recommended_tier: session.metadata?.plan_fit_recommended_tier ?? null,
      plan_fit_selected_tier_matches: session.metadata?.plan_fit_selected_tier_matches ?? null,
      plan_fit_video_id: session.metadata?.plan_fit_video_id ?? null,
      intro: session.metadata?.intro === '1',
      // KINEO-PLACAR-TRIAL-2026-09-08 — o $1 e dinheiro, mas nao e assinatura: quem le
      // o placar precisa separar "entrou no trial" de "pagou o mes".
      card_trial: session.metadata?.card_trial === '1',
      trial_days: session.metadata?.trial_days ?? null,
      amount_total: session.amount_total ?? 0,
      currency: session.currency ?? 'usd',
      // KINEO-RAZAO-ASSINANTE-2026-09-17 — ver firstPaymentCreditsFromSession. Null em pack/pagamento único.
      credits_granted: firstPaymentCreditsFromSession(session),
      // KINEO-EMPRESAS-DFY-2026-09-23 — `kind` separa no placar o que é
      // assinatura/pack do que é pedido feito-para-você ('dfy'); `payment_link`
      // identifica a venda que nasceu fora do checkout da casa. amount_total e
      // currency já estavam acima; ficam como estão (null vira 0/'usd' lá).
      kind: dfyOrder ? 'dfy' : (session.metadata?.kind ?? null),
      dfy_tier: dfyTier,
      payment_link: typeof session.payment_link === 'string'
        ? session.payment_link
        : session.payment_link?.id ?? null,
      // KINEO-COMPRA-SEM-LOGIN-2026-10-06 — só na compra de convidado (as outras linhas não mudam de forma).
      // KINEO-CUPOM-CONVIDADO-2026-10-07 — e, nela, o desconto de boas-vindas quando houve (sem ele, nada muda).
      ...(isGuestCheckoutSession(session) ? { guest_checkout: true, guest_checkout_version: GUEST_CHECKOUT_VERSION, ...guestWelcomePromoEventMetadata(session.metadata) } : {}),
      // KINEO-ANUNCIO-MOTOR-2026-10-07 — o clique pago (paid_utm_* + gclid|gbraid|wbraid|msclkid) copiado do checkout_started;
      // compra sem anúncio = nenhuma chave nova. É o que a leitura do teste de anúncio por motor soma por grupo.
      ...paidClickMetadata,
    },
  }

  const { error } = await supabase.from('events').insert(row)
  if (!error || error.code === '23505') return

  // A deleted auth user should not make us lose the revenue event. If the
  // user_id foreign key rejects the row, preserve the payment with user=null.
  if (userId && isOwnerRejection(error.code)) {
    const { error: anonymousError } = await supabase
      .from('events')
      .insert({ ...row, user_id: null })
    if (!anonymousError || anonymousError.code === '23505') return
    console.error('[stripe webhook] payment_success fallback insert error:', anonymousError.code, anonymousError.message)
    return
  }

  console.error('[stripe webhook] payment_success insert error:', error.code, error.message)
}

// KINEO-EMPRESAS-DFY-2026-09-23 — KINEO EMPRESAS por Payment Link.
//
// POR QUÊ. Nove pedidos de anúncio de empresa foram escritos no Studio em
// setembro e todos receberam um Short de curiosidades. O fundador mandou VENDER
// ANTES DE CONSTRUIR: Payment Links da Stripe criados no painel (US$100 em 23/09;
// em 24/09 virou DOIS DEGRAUS, Express US$35 e Pro US$75, e o de US$100 foi
// desativado), cartão no Studio (lib/growth/dfyOffer.ts), pedidos operados à
// mão. Este webhook é o único lugar onde o pagamento vira FATO no banco.
//
// O QUE É UM PEDIDO DFY. metadata.kind === 'dfy' (quando o link carrega a
// metadata) OU, para um Payment Link criado sem metadata, valor exato
// um valor aceito (DFY_ACCEPTED_AMOUNTS_USD_MINOR) em USD e NENHUM metadata.pack. Nota 24/09: 3500/7500
// coincidem com bulk20/bulk50 (por isso a 3ª regra exige payment_link). Por que 10000 não colidia
// com nenhum SKU one-time nem com o fallback por valor:
//   · AMBIGUOUS_ONE_TIME_USD_AMOUNTS = {} (vazia desde V8-A, 28/09: o Starter anual foi de 9900 para 12900 e o
//     piloto voltou a ser o único dono de 9900; até então era {9900}, Starter anual × piloto);
//   · packs: 499 (starter, desde 05/10; 490 antes), 290 (starter290); top-ups: 590/1490/1290/5990;
//   · bulk: 1900/3500/4900/7500; piloto Autopilot: 9900; Autopilot mensal 29900;
//   · mensais (subscription): 990/1990/5490; anuais (mode:'subscription' hoje): 8300/16700/46000
//     (KINEO-PRECO-TESTE-2026-10-08: Starter/Creator a $9,90/$19,90 no teste de 7 dias; eram 1290/2990 e 10800/25000
//     desde KINEO-ANUAL-30-2026-10-08; 9290/21500/39500 desde KINEO-ANUAL-40OFF-2026-10-05 e 12900/29900/54900 antes);
//   · legados por valor: 900 e 1900.
// Nenhum é 10000. O `!pack` é a mesma guarda que o piloto usa: uma sessão da
// casa SEMPRE carrega metadata.pack, então o fallback por valor só alcança
// sessões nascidas fora desta rota (o Payment Link).
//
// O QUE ESTE RAMO NÃO FAZ: não concede crédito, nem plano, nem has_paid — o
// filme é entregue por gente. Não aciona o guard de fulfillment (nada de
// entitlementPending): não há entitlement para reter. Só lança quando o pedido
// NÃO foi gravado (RetryableCheckoutAnalyticsError → 500 → a Stripe reenvia):
// COWORK-RELATORIO-2026-09-24 — a auditoria achou que "nunca lança" transformava
// um soluço do banco em pedido pago perdido com 200. O reenvio é seguro: o
// registro é idempotente (dedupe por stripe_session_id + id determinístico) e
// este ramo não concede nada.
// KINEO-FLUXO-NOVO-2026-09-25 — sessionPaymentLinkId, dfySessionTier e isDfyOrderSession moraram aqui até 25/09.
// Agora vêm de lib/growth/dfySession.ts (mesmo corpo, mesmo comentário do id do link como chave primeira), para
// que a rota do briefing (app/api/dfy/brief) reconheça o pedido com a MESMA regra que grava dfy_order_paid.

async function recordDfyOrderPaid(
  supabase: AdminClient,
  stripeEventId: string,
  session: Stripe.Checkout.Session,
): Promise<void> {
  try {
    const { data: existingRows, error: existingError } = await supabase
      .from('events')
      .select('id')
      .eq('name', 'dfy_order_paid')
      .contains('metadata', { stripe_session_id: session.id })
      .limit(1)
    if (!existingError && existingRows && existingRows.length > 0) return
    if (existingError) {
      console.error('[stripe webhook] dfy_order_paid dedupe lookup error:', existingError.code, existingError.message)
    }
    const userId = sessionOwnerUuid(session)
    const paymentLink = typeof session.payment_link === 'string'
      ? session.payment_link
      : session.payment_link?.id ?? null
    const eventHex = createHash('sha256').update(`dfy_order_paid:${session.id}`).digest('hex').slice(0, 32)
    const row = {
      id: `${eventHex.slice(0, 8)}-${eventHex.slice(8, 12)}-${eventHex.slice(12, 16)}-${eventHex.slice(16, 20)}-${eventHex.slice(20)}`,
      name: 'dfy_order_paid',
      user_id: userId,
      path: '/api/stripe/webhook',
      session_id: null,
      metadata: {
        source: 'stripe_webhook',
        stripe_event_id: stripeEventId,
        stripe_session_id: session.id,
        amount_total: session.amount_total ?? null,
        currency: session.currency ?? null,
        customer_email: session.customer_details?.email ?? null,
        customer_name: session.customer_details?.name ?? null,
        custom_fields: (session.custom_fields ?? []).map((f) => ({
          key: f.key,
          label: f.label?.custom ?? null,
          value: f.text?.value ?? f.dropdown?.value ?? (f.numeric?.value ?? null),
        })),
        payment_link: paymentLink,
        kind: 'dfy',
        // degrau: metadata do link (Cowork) ou o id do link; null no legado de US$100
        tier: dfySessionTier(session),
      },
    }
    const { error } = await supabase.from('events').insert(row)
    if (!error || error.code === '23505') {
      console.log('[stripe webhook] dfy_order_paid recorded:', session.id, userId ?? '(no user)', session.customer_details?.email ?? '(no email)')
      return
    }
    // client_reference_id de um usuário apagado (23503) ou fora do formato
    // uuid (22P02 — o formato já é filtrado por sessionOwnerUuid, o código fica
    // por cinto e suspensório) não pode perder o pedido pago: regrava sem dono.
    if (userId && isOwnerRejection(error.code)) {
      const { error: anonymousError } = await supabase.from('events').insert({ ...row, user_id: null })
      if (!anonymousError || anonymousError.code === '23505') {
        console.log('[stripe webhook] dfy_order_paid recorded without user:', session.id)
        return
      }
      console.error('[stripe webhook] dfy_order_paid fallback insert error:', anonymousError.code, anonymousError.message)
      throw new RetryableCheckoutAnalyticsError(`dfy_order_paid not recorded (${anonymousError.code ?? 'unknown'})`)
    }
    console.error('[stripe webhook] dfy_order_paid insert error:', error.code, error.message)
    throw new RetryableCheckoutAnalyticsError(`dfy_order_paid not recorded (${error.code ?? 'unknown'})`)
  } catch (err) {
    if (err instanceof RetryableCheckoutAnalyticsError) throw err
    console.error('[stripe webhook] dfy_order_paid threw:', err, session.id)
    throw new RetryableCheckoutAnalyticsError('dfy_order_paid threw before recording')
  }
}

// ═══ KINEO-PACOTE-3-FILMES-1610 — o pacote "3 filmes feitos por nós" (US$ 19) vira pedido PAGO ═══════════════════
// Reconhecido SÓ por metadata.pack === 'dfy_films3' (isDfyFilms3Session): 1900 é também o valor do bulk10 e do legado
// "$19 → 25 créditos" do fallback por valor logo abaixo — por isso este ramo vem ANTES de qualquer conta de crédito.
// Não concede crédito, plano nem has_paid: o filme é feito por gente. Idempotente em três camadas:
//   1. UPDATE guardado por status = 'pending_payment' (a reentrega encontra 'paid' e não regrava nada);
//   2. stripe_session_id é UNIQUE na tabela (o mesmo pagamento nunca vira dois pedidos);
//   3. o evento dfy_films3_order_paid tem id determinístico (sha256 da sessão) → 23505 na reentrega.
// Lança RetryableCheckoutAnalyticsError (→ 500 → a Stripe reenvia) só quando o pedido NÃO ficou gravado; a retomada
// do evento duplicado está liberada no guard de stripe_events (mesmo tratamento do pedido Empresas).
async function recordDfyFilms3OrderPaid(
  supabase: AdminClient,
  stripeEventId: string,
  session: Stripe.Checkout.Session,
): Promise<{ orderId: string | null; topic: string; language: string; style: string | null; fresh: boolean }> {
  const meta = session.metadata ?? {}
  const orderIdRaw = (meta.dfy_order_id ?? '').trim()
  const orderId = /^[0-9a-f-]{36}$/i.test(orderIdRaw) ? orderIdRaw : null
  const userId = sessionOwnerUuid(session)
  const nowIso = new Date().toISOString()
  const paidFields = {
    status: 'paid',
    paid_at: nowIso,
    stripe_session_id: session.id,
    amount_total: session.amount_total ?? null,
    currency: session.currency ?? null,
  }
  let topic = (meta.dfy_topic ?? '').trim()
  let language = (meta.dfy_language ?? '').trim()
  let style: string | null = (meta.dfy_style ?? '').trim() || null
  let fresh = false
  let finalOrderId: string | null = orderId

  // (1) o pedido salvo antes do pagamento passa de 'pending_payment' para 'paid' — uma vez só.
  if (orderId) {
    const { data: updated, error: updErr } = await supabase
      .from('done_for_you_orders')
      .update(paidFields)
      .eq('id', orderId)
      .eq('status', 'pending_payment')
      .select('id, topic, language, style')
    if (updErr && updErr.code !== '23505') {
      console.error('[stripe webhook] dfy_films3 order update error:', updErr.code, updErr.message)
      throw new RetryableCheckoutAnalyticsError(`dfy_films3 order not recorded (${updErr.code ?? 'unknown'})`)
    }
    if (updated && updated.length > 0) {
      fresh = true
      topic = String(updated[0].topic ?? topic)
      language = String(updated[0].language ?? language)
      style = typeof updated[0].style === 'string' ? updated[0].style : style
    }
  }

  // (2) nada mudou: ou já estava pago (reentrega), ou o pedido sumiu → grava pela cópia da metadata.
  if (!fresh) {
    const { data: existing, error: selErr } = await supabase
      .from('done_for_you_orders')
      .select('id, status, topic, language, style')
      .or(orderId ? `id.eq.${orderId},stripe_session_id.eq.${session.id}` : `stripe_session_id.eq.${session.id}`)
      .limit(1)
    if (selErr) {
      console.error('[stripe webhook] dfy_films3 order lookup error:', selErr.code, selErr.message)
      throw new RetryableCheckoutAnalyticsError(`dfy_films3 order lookup failed (${selErr.code ?? 'unknown'})`)
    }
    if (existing && existing.length > 0) {
      finalOrderId = String(existing[0].id)
      topic = String(existing[0].topic ?? topic)
      language = String(existing[0].language ?? language)
      style = typeof existing[0].style === 'string' ? existing[0].style : style
    } else {
      const row = {
        ...(orderId ? { id: orderId } : {}),
        user_id: userId,
        email: session.customer_details?.email ?? session.customer_email ?? null,
        topic: topic || '(topic missing — ask the customer)',
        language: language || 'en',
        style,
        price_usd_minor: DFY_FILMS3_PRICE_USD_MINOR,
        ...paidFields,
      }
      let { data: ins, error: insErr } = await supabase.from('done_for_you_orders').insert(row).select('id').limit(1)
      if (insErr && userId && isOwnerRejection(insErr.code)) {
        ;({ data: ins, error: insErr } = await supabase.from('done_for_you_orders').insert({ ...row, user_id: null }).select('id').limit(1))
      }
      if (insErr && insErr.code !== '23505') {
        console.error('[stripe webhook] dfy_films3 order insert error:', insErr.code, insErr.message)
        throw new RetryableCheckoutAnalyticsError(`dfy_films3 order not recorded (${insErr.code ?? 'unknown'})`)
      }
      fresh = !insErr
      finalOrderId = ins?.[0]?.id ? String(ins[0].id) : finalOrderId
    }
  }

  // (3) o evento do pedido pago, 1× por sessão (id determinístico).
  const eventHex = createHash('sha256').update(`${DFY_FILMS3_EVENTS.orderPaid}:${session.id}`).digest('hex').slice(0, 32)
  const eventRow = {
    id: `${eventHex.slice(0, 8)}-${eventHex.slice(8, 12)}-${eventHex.slice(12, 16)}-${eventHex.slice(16, 20)}-${eventHex.slice(20)}`,
    name: DFY_FILMS3_EVENTS.orderPaid,
    user_id: userId,
    path: '/api/stripe/webhook',
    session_id: null,
    metadata: {
      source: 'stripe_webhook',
      stripe_event_id: stripeEventId,
      stripe_session_id: session.id,
      order_id: finalOrderId,
      pack: DFY_FILMS3_PACK_ID,
      amount_total: session.amount_total ?? null,
      currency: session.currency ?? null,
      language,
      version: meta.dfy_version ?? null,
    },
  }
  const { error: evErr } = await supabase.from('events').insert(eventRow)
  if (evErr && evErr.code !== '23505') {
    if (userId && isOwnerRejection(evErr.code)) await supabase.from('events').insert({ ...eventRow, user_id: null })
    else console.error('[stripe webhook] dfy_films3_order_paid event error (order already recorded):', evErr.code, evErr.message)
  }
  console.log('[stripe webhook] dfy_films3 order paid:', session.id, finalOrderId ?? '(no order id)', fresh ? 'fresh' : 'already recorded')
  return { orderId: finalOrderId, topic, language, style, fresh }
}

async function recordAsyncCheckoutState(
  session: Stripe.Checkout.Session,
  outcome: StripeAsyncCheckoutOutcome,
): Promise<void> {
  const eventName = outcome === 'pending'
    ? 'checkout_payment_pending'
    : 'checkout_async_payment_failed'
  // KINEO-EMPRESAS-COCKPIT-2026-09-24 — Payment Link com Adaptive Pricing abre meios lentos (SEPA/Pix/iDEAL):
  // a sessão chega 'unpaid' e cai aqui. Um client_reference_id fora do formato uuid (URL adulterada) ou de conta
  // apagada derrubava o insert → 500 → a Stripe reenviava por dias. O dono passa pelo mesmo filtro do resto.
  const userId = sessionOwnerUuid(session)
  const sessionRef = stripeCheckoutSessionReference(session.id)
  const input = {
    name: eventName,
    userId,
    path: '/api/stripe/webhook',
    sessionId: sessionRef,
    dedupeMinutes: 24 * 60,
    metadata: buildStripeAsyncCheckoutMetadata({
      sessionId: session.id,
      outcome,
      paymentStatus: session.payment_status,
      checkoutMode: session.mode,
      amountMinor: session.amount_total,
      currency: session.currency,
      tier: session.metadata?.tier,
      billing: session.metadata?.billing,
      pack: session.metadata?.pack,
      checkoutOrigin: session.metadata?.checkout_origin,
      intentCampaign: session.metadata?.intent_campaign,
    }),
  }
  let recorded = await writeServerEvent(input)
  // COWORK-RELATORIO-2026-09-24 — o filtro de formato não pega a conta APAGADA: uuid válido, FK 23503, writeServerEvent
  // devolve false e a Stripe reenviava por dias (auditoria de 24/09, confirmada por 2 céticos). A linha vale sem dono,
  // como em recordPaymentSuccess e recordDfyOrderPaid; só lança se nem assim gravar (aí é o banco, e o reenvio ajuda).
  if (!recorded && userId) recorded = await writeServerEvent({ ...input, userId: null })
  if (!recorded) {
    throw new RetryableCheckoutAnalyticsError(`Could not persist ${eventName}`)
  }
}

// KINEO-BULK-2026-07-27 — evento de compra de atacado, com nome próprio.
//
// POR QUE UM EVENTO NOVO, se `payment_success` já grava esta sessão: porque
// `payment_success` é o balde de TODA receita, e a única forma de tirar atacado
// de lá é filtrar `metadata->>'pack'` linha a linha. O atacado é o primeiro canal
// de receita desenhado desta empresa — ele precisa de um par contável
// (`bulk_checkout_started` → `bulk_purchase_completed`) para que a taxa de
// conversão exista sem ninguém reconstruir coorte na mão.
//
// Ambos são SERVER_ONLY (app/api/events/route.ts): um burst forjado no sink do
// browser inflaria o topo do funil e faria a conversão mentir para baixo — o
// mesmo estrago que já aconteceu com viral_onboarding_viewed (9,7x) e
// generate_arrived_server (2,7x).
//
// Idempotente pelo mesmo desenho de recordPaymentSuccess: o id da linha é
// derivado do id da sessão Stripe, então uma retentativa colide em 23505 em vez
// de inflar a contagem de vendas.
async function recordBulkPurchase(
  supabase: AdminClient,
  args: {
    userId: string
    session: Stripe.Checkout.Session
    videos: number
    credits: number
    sku: string
  },
): Promise<void> {
  try {
    const { session } = args
    const eventHex = createHash('sha256')
      .update(`bulk_purchase_completed:${session.id}`)
      .digest('hex')
      .slice(0, 32)
    const row = {
      id: `${eventHex.slice(0, 8)}-${eventHex.slice(8, 12)}-${eventHex.slice(12, 16)}-${eventHex.slice(16, 20)}-${eventHex.slice(20)}`,
      name: 'bulk_purchase_completed',
      user_id: args.userId,
      path: '/api/stripe/webhook',
      metadata: {
        source: 'stripe_webhook',
        sku: args.sku,
        bulk_videos: args.videos,
        credits_granted: args.credits,
        bulk_checkout_truth_version: readBulkCheckoutTruthVersion(
          session.metadata?.bulk_checkout_truth_version,
        ),
        stripe_session_id: session.id,
        amount_total: session.amount_total ?? 0,
        currency: session.currency ?? 'usd',
      },
    }

    const { error } = await supabase.from('events').insert(row)
    if (!error || error.code === '23505') return

    // Usuário apagado no auth não pode custar o evento de receita — mesma
    // recuperação que payment_success faz.
    if (error.code === '23503') {
      const { error: anonymousError } = await supabase.from('events').insert({ ...row, user_id: null })
      if (!anonymousError || anonymousError.code === '23505') return
      console.error('[stripe webhook] bulk_purchase_completed fallback insert error:', anonymousError.code, anonymousError.message)
      return
    }
    console.error('[stripe webhook] bulk_purchase_completed insert error:', error.code, error.message)
  } catch (err) {
    // Telemetria nunca derruba uma concessão de crédito já confirmada.
    console.error('[stripe webhook] bulk_purchase_completed threw:', err)
  }
}

// KINEO-REVERSE-TRIAL-P2-2026-08-07 — REVERSE TRIAL, FASE 2 (webhook):
// pagamento bem-sucedido fecha o trial como 'converted' NA HORA, sem esperar a
// próxima passada do cron de downgrade (que já faz o mesmo por isPayingProfile,
// mas só de hora em hora — e o A/B 3d/7d conta conversão por esta coluna).
//
// Decisões que a revisão adversarial obrigou a escrever aqui:
//
// 1. SÓ 'active' e 'expired' viram 'converted' — NUNCA 'converted' (retry do
//    Stripe acha 0 linhas e não duplica o evento: idempotente por construção) e
//    NUNCA 'downgraded' (estado terminal escrito pelo cron; uma compra tardia é
//    conversão dos e-mails D3+, não do trial — reabrir o estado corromperia o
//    braço do A/B que já contou aquele trial como churn).
//    ⚠️ ATUALIZADO POR KINEO-TRIAL-REVIVE-RACE-2026-08-11 — esta regra continua
//    valendo AQUI, e a lista `.in(['active','expired'])` abaixo NÃO muda. Mas a
//    frase "estado terminal" deixou de ser verdadeira em termos absolutos:
//    recordReverseTrialRefundForRender (lib/reverseTrial.ts) agora reabre
//    'downgraded' → 'active' num caso e só um — estorno de falha de FORNECEDOR
//    que derruba o consumo abaixo do teto com o relógio vivo, atrás de 6
//    guardas. Consequência para ESTE arquivo: uma conta revivida chega aqui
//    como 'active' e é convertida normalmente, o que está certo do ponto de
//    vista do produto (ela comprou de um trial vivo) mas NÃO do ponto de vista
//    do A/B — ela passou por um churn no meio e o painel, que bucketiza por
//    `trial_status`, a contaria como conversão limpa. O evento
//    `trial_cap_refunded` carrega `ab_cohort_note='revived_after_provider_failure'`
//    para permitir identificá-la.
//    ✅ PAGO em KINEO-AB-CENSORING-2026-08-11. Duas correções ao texto acima:
//    (a) o painel do A/B é **/admin/trial-abuse**, não /admin/trial-cohort —
//    a dívida ficou registrada contra a tela errada desde o começo; (b) a
//    revivida NÃO é excluída, e sim CONTADA e exibida: "foi revivida" é uma
//    variável pós-tratamento e remover linhas por ela seleciona a amostra pelo
//    desfecho. O que o painel passou a fazer é maior que o join: o denominador
//    deixou de ser status (que anda para trás) e virou maturidade por âncora
//    imutável. Ler o cabeçalho de lá antes de citar qualquer taxa do 3d×7d.
// 2. BEST-EFFORT, nunca lança: roda DEPOIS do entitlement confirmado, e um
//    carimbo de experimento não pode custar retry de webhook nem atrasar a
//    resposta ao Stripe. Se falhar, o cron converte na rodada seguinte — a
//    rede de segurança registrada em downgradeExpiredTrial.
// 3. Atrás da flag, como todo o trial: com a flag OFF nenhum perfil tem
//    trial_status para converter (o gate poupa o round-trip). Rollback (flag
//    OFF com trials vivos) continua coberto: o cron decide SEM flag, de
//    propósito — ver o cabeçalho de trialNeedsDowngrade.
// 4. O evento 'trial_converted' só sai quando a UPDATE afetou uma linha — é o
//    par do 'trial_expired'/'trial_downgraded': acontece UMA vez por trial.
async function markTrialConverted(
  supabase: AdminClient,
  userId: string | null | undefined,
  context: { source: string; stripeRef: string | null },
): Promise<void> {
  if (!REVERSE_TRIAL_ENABLED) return
  if (!userId) return
  try {
    const { data: updated, error } = await supabase
      .from('profiles')
      .update({ trial_status: 'converted' })
      .eq('id', userId)
      .in('trial_status', ['active', 'expired', CARD_ENTRY_TRIAL_STATUS])
      .select('id')
    if (error) {
      console.error('[stripe webhook] trial_converted update failed:', error.message, userId)
      return
    }
    if (!updated || updated.length === 0) return
    console.log(`[stripe webhook] TRIAL CONVERTED user=${userId.slice(0, 8)} via=${context.source}`)
    // AWAIT pelo mesmo motivo do grant e do trial_expired (lib/reverseTrial.ts):
    // acontece uma vez por trial e é o dado que o A/B 3d vs 7d mede. Nunca lança
    // (reporta false), então o await é seguro.
    await writeServerEvent({
      name: 'trial_converted',
      userId,
      path: '/api/stripe/webhook',
      metadata: { source: context.source, stripe_ref: context.stripeRef },
    })
  } catch (err) {
    console.error('[stripe webhook] trial_converted threw:', err)
  }
}

// ═══ KINEO-DUNNING-EMAIL-2026-10-06 — o aviso de renovação recusada sai daqui, na 1ª falha de cada fatura ═══════════
// SE manda e O QUE manda: lib/billing/renewalFailedEmail.ts (puro, com o porquê). Aqui só o I/O, com três regras
// porque isto roda DENTRO do webhook da Stripe:
//  1. NUNCA LANÇA. É chamado depois de `entitlementConfirmed = true`: e-mail que falha não pode virar 500 (a Stripe
//     reenviaria o evento) nem mudar a resposta de hoje. Tudo dentro de um try/catch que só avisa no log.
//  2. AWAIT EM TUDO, com teto RENEWAL_FAILED_EMAIL_TIMEOUT_MS no Resend: `void` antes do return morre na Vercel.
//  3. CARIMBO SÓ COM O RESEND DIZENDO OK. O carimbo (RENEWAL_FAILED_EMAIL_EVENT + metadata.invoice_id) é a dedupe
//     por fatura. Falhou = evento `_failed` e nenhum carimbo: a próxima falha da MESMA fatura tenta de novo.
// Todo desfecho vira evento (enviado / pulado com motivo / falhou): sem isso "0 e-mails" não distingue "ninguém
// precisou" de "o envio está quebrado".
type RenewalFailedEmailOwner = { id: string; plan: string | null; has_paid: boolean }

async function sendRenewalFailedEmailOnce(
  supabase: AdminClient,
  input: {
    // KINEO-CARTAO-RECUSADO-1510 — + hosted_invoice_url (o botão de 1 clique, sem login) e payment_intent (o motivo).
    invoice: Pick<Stripe.Invoice, 'id' | 'billing_reason' | 'attempt_count' | 'customer_email' | 'hosted_invoice_url' | 'payment_intent'>
    subscriptionId: string
    subscriptionStatus: string
    owner: RenewalFailedEmailOwner | null
    tier: string | null
  },
): Promise<void> {
  const ownerId = input.owner?.id ?? null
  const invoiceId = input.invoice.id ?? null
  const base = {
    version: RENEWAL_FAILED_EMAIL_VERSION,
    source: 'stripe_webhook',
    invoice_id: invoiceId,
    subscription_ref: input.subscriptionId,
    attempt: typeof input.invoice.attempt_count === 'number' ? input.invoice.attempt_count : null,
    billing_reason: input.invoice.billing_reason ?? null,
  }
  try {
    // Dedupe por FATURA. Erro de leitura = desconhecido (null) = não envia agora; a próxima tentativa pergunta de novo.
    let alreadySentForInvoice: boolean | null = null
    if (invoiceId) {
      const { data: sentForInvoice, error: dedupeErr } = await supabase
        .from('events')
        .select('id')
        .eq('name', RENEWAL_FAILED_EMAIL_EVENT)
        .eq('metadata->>invoice_id', invoiceId)
        .limit(1)
      if (dedupeErr) console.error('[stripe webhook] renewal email dedupe read failed:', invoiceId, dedupeErr.message)
      else alreadySentForInvoice = (sentForInvoice?.length ?? 0) > 0
    }

    let profile: { email?: string | null; email_opted_out?: boolean | null; signup_country?: string | null; last_country?: string | null } | null = null
    if (ownerId) {
      const { data, error: profileErr } = await supabase
        .from('profiles')
        .select('email, email_opted_out, signup_country, last_country')
        .eq('id', ownerId)
        .maybeSingle()
      if (profileErr) console.error('[stripe webhook] renewal email profile read failed:', ownerId, profileErr.message)
      profile = data
    }
    const recipient = (profile?.email || input.invoice.customer_email || '').trim()
    const marketingOptOut = profile?.email_opted_out === true

    const decision = decideRenewalFailedEmail({
      live: RENEWAL_FAILED_EMAIL_LIVE,
      billingReason: input.invoice.billing_reason,
      invoiceId,
      ownerId,
      ownerHasPaid: input.owner?.has_paid === true,
      subscriptionStatus: input.subscriptionStatus,
      alreadySentForInvoice,
      recipientEmail: recipient,
      marketingOptOut,
    })
    if (!decision.send) {
      await writeServerEvent({
        name: RENEWAL_FAILED_EMAIL_SKIPPED_EVENT,
        userId: ownerId,
        path: '/api/stripe/webhook',
        metadata: { ...base, reason: decision.reason },
      })
      return
    }

    const apiKey = process.env.RESEND_API_KEY
    if (!apiKey) {
      console.error('[stripe webhook] renewal email not sent: RESEND_API_KEY missing')
      await writeServerEvent({
        name: RENEWAL_FAILED_EMAIL_SKIPPED_EVENT,
        userId: ownerId,
        path: '/api/stripe/webhook',
        metadata: { ...base, reason: 'sender_unconfigured' },
      })
      return
    }

    // KINEO-CARTAO-RECUSADO-1510 — motivo humano (categoria) e botão na fatura hospedada da Stripe (sem login).
    // readInvoiceDeclineCategory nunca lança e tem teto de 2,5 s; sem motivo a carta diz a frase genérica.
    const reasonCategory = await readInvoiceDeclineCategory(input.invoice)
    const payLink = renewalPayUrl(input.invoice.hosted_invoice_url)
    const message = renewalFailedEmailMessage({
      language: renewalEmailLanguage(profile?.last_country || profile?.signup_country),
      tier: input.tier ?? input.owner?.plan ?? null,
      hostedInvoiceUrl: input.invoice.hosted_invoice_url,
      reasonCategory,
      stage: 'first',
    })
    let res: Response
    try {
      res = await fetch('https://api.resend.com/emails', {
        method: 'POST',
        signal: AbortSignal.timeout(RENEWAL_FAILED_EMAIL_TIMEOUT_MS),
        headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          from: RENEWAL_FAILED_EMAIL_FROM,
          to: [recipient],
          reply_to: RENEWAL_FAILED_EMAIL_REPLY_TO,
          subject: message.subject,
          text: message.text,
          html: message.html,
        }),
      })
    } catch (sendErr) {
      const detail = (sendErr instanceof Error ? sendErr.message : String(sendErr)).slice(0, 200)
      await recordEmailSend({ kind: RENEWAL_FAILED_EMAIL_KIND, priority: 'revenue', userId: ownerId, ok: false, detail, admin: supabase })
      await writeServerEvent({
        name: RENEWAL_FAILED_EMAIL_FAILED_EVENT,
        userId: ownerId,
        path: '/api/stripe/webhook',
        metadata: { ...base, language: message.language, error: detail },
      })
      console.warn('[stripe webhook] renewal email send threw (webhook continues):', invoiceId, detail)
      return
    }
    await recordResendResponse({ kind: RENEWAL_FAILED_EMAIL_KIND, priority: 'revenue', userId: ownerId, res, admin: supabase })
    if (!res.ok) {
      await writeServerEvent({
        name: RENEWAL_FAILED_EMAIL_FAILED_EVENT,
        userId: ownerId,
        path: '/api/stripe/webhook',
        metadata: { ...base, language: message.language, http_status: res.status },
      })
      console.warn('[stripe webhook] renewal email rejected by Resend (webhook continues):', invoiceId, res.status)
      return
    }

    const receipt = (await res.json().catch(() => null)) as { id?: unknown } | null
    const stamped = await writeServerEvent({
      name: RENEWAL_FAILED_EMAIL_EVENT,
      userId: ownerId,
      path: '/api/stripe/webhook',
      metadata: {
        ...base,
        language: message.language,
        marketing_opt_out: marketingOptOut,
        provider_id: typeof receipt?.id === 'string' ? receipt.id : null,
        // KINEO-CARTAO-RECUSADO-1510 — para medir: o botão foi a fatura hospedada ou o portal? e qual o motivo?
        link: payLink === RENEWAL_FAILED_UPDATE_CARD_URL ? 'portal' : 'hosted_invoice',
        reason_category: reasonCategory,
        stage: 'first',
      },
    })
    if (!stamped) console.error('[stripe webhook] renewal email SENT but not stamped — the next failure of this invoice may resend:', invoiceId)
    else console.log('[stripe webhook] renewal failed email sent:', ownerId?.slice(0, 8), invoiceId, message.language)
  } catch (err) {
    console.warn('[stripe webhook] renewal failed email threw (webhook continues):', invoiceId, err instanceof Error ? err.message : String(err))
  }
}

// KINEO-SPRINT-EVENTS-2026-07-15 — payment_success server-side tracking is
// ALREADY handled by recordPaymentSuccess() above (called at the top of the
// shared Checkout fulfillment case, covering immediate and delayed payment,
// subscription and pack paths. Session-level idempotency prevents double grant.

export async function POST(req: NextRequest) {
  const body = await req.text()
  const sig = req.headers.get('stripe-signature')

  if (!sig) {
    return NextResponse.json({ error: 'Missing stripe-signature header' }, { status: 400 })
  }

  if (!process.env.STRIPE_WEBHOOK_SECRET) {
    console.error('[stripe/webhook] STRIPE_WEBHOOK_SECRET is not set')
    return NextResponse.json({ error: 'Webhook secret is not configured' }, { status: 500 })
  }

  let event: Stripe.Event

  try {
    event = stripe.webhooks.constructEvent(body, sig, process.env.STRIPE_WEBHOOK_SECRET)
  } catch (err) {
    console.error('Webhook signature verification failed:', err)
    return NextResponse.json({ error: 'Invalid signature' }, { status: 400 })
  }

  const supabase = getAdminClient()
  let dedupeRowAcquired = false
  let entitlementPending = false
  let entitlementConfirmed = false
  let checkoutFulfillmentGuard: string | null = null
  let checkoutFulfillmentGuardAcquired = false

  // Idempotency guard. Stripe retries the same event on 5xx (or if our
  // response is slow), and this handler has read-modify-write paths that
  // would double-credit a user on retry. We dedupe on event.id by inserting
  // into `stripe_events` — duplicate inserts fail and we exit early.
  // Run this once in the Supabase SQL editor:
  //   create table if not exists public.stripe_events (
  //     id text primary key,
  //     received_at timestamptz default now()
  //   );
  try {
    const { error: dedupeErr } = await supabase
      .from('stripe_events')
      .insert({ id: event.id })
    if (!dedupeErr) {
      dedupeRowAcquired = true
    } else {
      // 23505 = unique_violation — we've already processed this event.
      if (dedupeErr.code === '23505') {
        const duplicateCheckout =
          event.type === 'checkout.session.completed' ||
          event.type === 'checkout.session.async_payment_succeeded' ||
          event.type === 'checkout.session.async_payment_failed'
        const duplicateSession = duplicateCheckout
          ? event.data.object as Stripe.Checkout.Session
          : null
        const duplicateSafeObservation =
          event.type === 'checkout.session.async_payment_failed' ||
          (event.type === 'checkout.session.completed' &&
            !checkoutPaymentIsSettled(duplicateSession?.payment_status))
        // Subscription fulfillment below is idempotent by subscription id and
        // an absolute balance write. Let it resume after a process crash even
        // when event.id was already claimed. Additive legacy packs retain the
        // strict event-level early return.
        // KINEO-EMPRESAS-COCKPIT-2026-09-24 — o pedido Empresas também retoma: se o processo morrer entre o
        // carimbo em stripe_events e o insert de dfy_order_paid, a reentrega da Stripe voltava aqui e saía
        // como duplicate:true — pedido pago sem linha no banco. recordPaymentSuccess e recordDfyOrderPaid
        // são idempotentes (dedupe por stripe_session_id + id determinístico), então reexecutar é seguro.
        // KINEO-PACOTE-3-FILMES-1610 — o pacote "3 filmes" também retoma: recordDfyFilms3OrderPaid é idempotente (UPDATE guardado
        // por status, stripe_session_id único, evento com id determinístico) e não concede nada.
        if (!duplicateSession || (!isKidsPackSession(duplicateSession) && duplicateSession.mode !== 'subscription' && !duplicateSafeObservation && !isDfyOrderSession(duplicateSession) && !isDfyFilms3Session(duplicateSession))) { // KINEO-KIDS-VENDA-2010 — o pack infantil também retoma (guard por sessão + pedido único por sessão; nada é creditado)
          return NextResponse.json({ received: true, duplicate: true })
        }
        console.warn('[stripe webhook] resuming idempotent Checkout event:', event.id, duplicateSession.id)
      }
      if (dedupeErr.code !== '23505') {
        // Fulfillment without its ledger is unsafe. A 5xx asks Stripe to retry
        // after the database recovers instead of risking a duplicate grant.
        console.error('[stripe webhook] dedupe insert error:', dedupeErr.code, dedupeErr.message)
        return NextResponse.json({ error: 'Webhook idempotency unavailable' }, { status: 500 })
      }
    }
  } catch (err) {
    console.error('[stripe webhook] dedupe threw:', err)
    return NextResponse.json({ error: 'Webhook idempotency unavailable' }, { status: 500 })
  }

  try {
    switch (event.type) {
      case 'checkout.session.completed':
      case 'checkout.session.async_payment_succeeded': {
        const session = event.data.object as Stripe.Checkout.Session

        // Delayed methods can complete Checkout while payment is still pending.
        // Grant access only after Stripe confirms settlement.
        const checkoutSettled = checkoutPaymentIsSettled(session.payment_status)
        if (!checkoutSettled) {
          await recordAsyncCheckoutState(session, 'pending')
          console.log('[stripe webhook] checkout payment pending; entitlement deferred:', session.id, session.payment_status)
          break
        }

        // Canonical conversion tracking happens before entitlement updates, so
        // a paid checkout remains visible even if a later profile write fails.
        // Tracking is ancillary: a temporary analytics failure must never stop
        // the paid user from receiving their entitlement.
        try {
          await recordPaymentSuccess(supabase, event.id, session)
        } catch (trackingError) {
          console.error('[stripe webhook] payment_success tracking threw:', trackingError)
        }

        // Both immediate and delayed success converge on this session key. A
        // legacy pack claims it before its additive grant; recurring checkout
        // publishes it only after the idempotent entitlement update succeeds.
        checkoutFulfillmentGuard = `checkout_fulfilled:${session.id}`

        // ── Path A: Legacy one-time credit-pack purchase via Payment Link ──
        // Push #020 moved off Payment Links onto Stripe Checkout subscriptions,
        // but old links may still exist in the wild. Keep the legacy mapping
        // so refunds / late webhooks don't lose users their pack.
        if (session.mode === 'payment') {
          // KINEO-EMPRESAS-DFY-2026-09-23 — ANTES da checagem de userId: quem
          // paga pelo Payment Link pode chegar sem client_reference_id (link
          // copiado, aberto em outro navegador). O pedido é gravado mesmo
          // assim, pelo e-mail do pagador; nada é concedido. Ver
          // isDfyOrderSession / recordDfyOrderPaid.
          // KINEO-FLUXO-NOVO-2026-09-25 — o fundador é avisado DEPOIS de o pedido estar gravado (se a gravação lança,
          // a Stripe reenvia e o aviso sai na volta): 1×/sessão, teto de 3 s, nunca lança (lib/founderAlert.ts).
          if (isDfyOrderSession(session)) {
            await recordDfyOrderPaid(supabase, event.id, session)
            await alertFounderDfyOrder(session)
            break
          }
          // KINEO-PACOTE-3-FILMES-1610 — "3 filmes feitos por nós" (US$ 19): ANTES do fallback por valor (1900 = legado
          // "$19 → 25 créditos" e bulk10). Grava o pedido pago, avisa o fundador (1×/sessão) e sai sem conceder nada.
          if (isDfyFilms3Session(session)) {
            const films3 = await recordDfyFilms3OrderPaid(supabase, event.id, session)
            await alertFounderDfyFilms3Order({ session, orderId: films3.orderId, topic: films3.topic, language: films3.language, style: films3.style })
            break
          }
          if (isKidsPackSession(session)) { // KINEO-KIDS-VENDA-2010 — o pack de 30 desenhos: pedido em FILA, NENHUM crédito concedido (o cron financia filme a filme); ANTES do fallback por valor (4900 = Kit BF / bulk30) e com o guard da sessão ANTES de gravar, como o pack legado
            entitlementPending = true // KINEO-KIDS-VENDA-2010
            const { error: kidsGuardError } = await supabase.from('stripe_events').insert({ id: checkoutFulfillmentGuard }) // KINEO-KIDS-VENDA-2010
            if (kidsGuardError && kidsGuardError.code === '23505') { entitlementConfirmed = true; entitlementPending = false; console.log('[stripe webhook] kids pack already fulfilled:', session.id); break } // KINEO-KIDS-VENDA-2010
            if (kidsGuardError) throw new RetryableEntitlementError(`Failed to acquire kids pack fulfillment guard (${session.id}): ${kidsGuardError.message}`) // KINEO-KIDS-VENDA-2010
            checkoutFulfillmentGuardAcquired = true // KINEO-KIDS-VENDA-2010
            const kidsPack = await fulfillKidsPack(supabase, session) // KINEO-KIDS-VENDA-2010
            if (!kidsPack.ok) throw new RetryableEntitlementError(kidsPack.error) // KINEO-KIDS-VENDA-2010 — o catch libera o guard e a Stripe reenvia: nunca cobra sem gravar o pedido
            entitlementConfirmed = true; entitlementPending = false // KINEO-KIDS-VENDA-2010
            console.log('[stripe webhook] kids pack:', kidsPack.detail, session.id) // KINEO-KIDS-VENDA-2010
            break // KINEO-KIDS-VENDA-2010
          } // KINEO-KIDS-VENDA-2010

          // #473 — Starter Pack ($4.90 → 10 Shorts) + legacy credit packs.
          // Prefer metadata.pack_credits (currency-proof) over the amount map,
          // and accept metadata.supabase_user_id as well as client_reference_id.
          const userId = session.metadata?.supabase_user_id ?? session.client_reference_id
          if (!userId) {
            console.warn('[stripe webhook] payment session has no user id', session.id)
            break
          }

          // KINEO-AVATAR-PACKS-RETIRED-2026-07-06 — the metadata.avatar_credits
          // crediting block (which topped up the SEPARATE profiles.avatar_credits
          // balance for the retired avatar packs) was removed here. No checkout
          // path sets metadata.avatar_credits anymore — avatar videos now cost
          // 120 universal video_credits — so the block was dead. Existing
          // profiles.avatar_credits balances are left untouched in the DB.
          // The Starter Pack / top-ups keep using metadata.pack_credits below.

          const metaCredits = Number(session.metadata?.pack_credits ?? 0)
          const amount = session.amount_total ?? 0

          // KINEO-PILOT-99-2026-07-26 — o piloto de $99 é a ÚNICA compra one-time
          // que também muda `plan`, então o reconhecimento aqui é o mais estrito
          // dos três fallbacks deste bloco:
          //   1. metadata.pack / metadata.plan_grant → caminho normal, exato;
          //   2. valor + moeda → só quando NÃO há metadata.pack alguma, isto é,
          //      numa sessão que perdeu a metadata.
          // A condição (2) precisa da guarda `packMeta === ''` porque o preço do
          // piloto COLIDIA com o Starter anual em USD (9900) e em BRL (49900) até
          // 28/09 (V8-A: Starter anual = 12900 / R$ 649,00). A guarda fica: o anual
          // é mode:'subscription' e nem chega neste bloco, mas se um dia virar
          // pagamento único e voltar a empatar, sem ela um comprador de plano anual
          // sairia daqui com plan='autopilot_pilot'.
          const packMeta = (session.metadata?.pack ?? '').trim()

          // KINEO-BULK-2026-07-27 — os pacotes de atacado colidem em VALOR com o
          // piloto: bulk10 e autopilot_pilot custam os dois 9900 em USD (e
          // bulk50 empata com o Starter anual em 37900). O fallback por valor
          // deste bloco não consegue desempatar, e errar aqui significa entregar
          // um plano Autopilot de $299/mês para quem comprou 10 vídeos.
          //
          // Por isso o fallback do piloto agora exige, além de não haver
          // metadata.pack, que o valor NÃO esteja na lista de valores ambíguos
          // (lib/checkoutPricing.ts::AMBIGUOUS_ONE_TIME_USD_AMOUNTS, cuja
          // completude é checada por checkPricingInvariants). Uma sessão de $99
          // sem metadata deixa de ser adivinhada e passa a ser recusada com log
          // — dá para consertar à mão em minutos, ao contrário de uma concessão
          // errada, que ninguém descobre.
          const amountIsAmbiguous = isAmbiguousOneTimeUsdAmount(amount, session.currency)
          const isAutopilotPilot =
            packMeta === 'autopilot_pilot' ||
            session.metadata?.plan_grant === AUTOPILOT_PILOT_PLAN ||
            (packMeta === '' && !amountIsAmbiguous && isAutopilotPilotAmount(amount, session.currency))

          // Atacado: reconhecido SÓ por metadata.pack exata. Não há e não pode
          // haver fallback por valor para estes quatro SKUs.
          const bulkPack = isBulkPackId(packMeta) ? BULK_PACKS[packMeta] : null

          if (packMeta === '' && amountIsAmbiguous) {
            console.error(
              '[stripe webhook] AMBIGUOUS one-time amount with no metadata.pack — refusing to guess:',
              amount, session.currency, session.id,
              '(bulk pack vs autopilot pilot vs annual plan share this amount; grant it by hand)',
            )
            break
          }

          let creditsToAdd = metaCredits > 0 ? metaCredits : 0
          if (creditsToAdd === 0) {
            // Legacy Payment-Link amounts (USD): $9 → 10, $19 → 25, $4.90 → 30.
            // These only fire for sessions with NO metadata.pack_credits, i.e.
            // hosted Payment Links created before the inline-price_data route
            // existed. Every session this app creates carries pack_credits.
            if (amount === 900) creditsToAdd = 10
            else if (amount === 1900) creditsToAdd = 25
            // KINEO-PRICING-V3D-2026-07-26 — mirrors PACK_CREDITS.starter (10 → 30).
            // KINEO-PASSE-AVULSO-2026-10-05 — o passe avulso agora é US$ 4,99 / 35 cr (PACK_PRICE_MINOR); a sessão
            // antiga de US$ 4,90 sem metadata segue recebendo os 30 cr que ELA comprou.
            else if (amount === PACK_PRICE_MINOR.usd) creditsToAdd = PACK_CREDITS.starter
            else if (amount === LEGACY_PACK_STARTER_PRICE_MINOR_490) creditsToAdd = LEGACY_PACK_STARTER_CREDITS_490
            // KINEO-PRICING-V3D-2026-07-26 — $2.90 had no legacy fallback at
            // all: a starter290 session that somehow lost its metadata would
            // have been logged as "unexpected amount_total" and the buyer would
            // have paid and received nothing.
            else if (amount === 290) creditsToAdd = PACK_CREDITS.starter290
            // KINEO-PILOT-99-2026-07-26 — o bug de $2.90 (branch para 490, nenhum
            // para 290 → cartão cobrado, zero creditado) não se repete aqui: todo
            // valor que o checkout pode cobrar por este SKU tem branch, nas TRÊS
            // moedas, e nenhum deles colide com outro SKU na mesma moeda.
            else if (isAutopilotPilot) creditsToAdd = AUTOPILOT_PILOT_CREDITS
            // KINEO-BULK-2026-07-27 — sessão de atacado que manteve
            // metadata.pack mas perdeu metadata.pack_credits. Derivar do id do
            // SKU é seguro (não depende do valor) e evita o bug do $2.90:
            // cartão cobrado, zero creditado.
            else if (bulkPack) creditsToAdd = bulkPack.credits
            // KINEO-PASSE-B-2026-09-28 — passe do Studio Ads que manteve metadata.pack mas perdeu
            // metadata.pack_credits: sem esta linha caía no "unexpected amount_total" e a pessoa pagava
            // US$19,90 sem crédito NEM acesso (o break vem antes do UPDATE). Só roda sem pack_credits; o
            // caminho normal continua concedendo o que a pessoa viu ao abrir o checkout (metaCredits).
            else if (packMeta === ADS_PASS_ID) creditsToAdd = ADS_PASS_CREDITS
            else if (packMeta === KIT_BF_PACK_ID) creditsToAdd = KIT_BF_CREDITS // KINEO-KIT-BF-VENDA-2010 — sessão do kit que perdeu metadata.pack_credits (nunca por valor: 4900 é também o bulk30)
          }

          if (creditsToAdd === 0) {
            console.warn('[stripe webhook] unexpected amount_total for credit pack:', amount, session.id)
            break
          }

          entitlementPending = true
          // Legacy packs are additive and have no transaction-capable purchase
          // ledger, so retain the conservative pre-write session marker here.
          const { error: packGuardError } = await supabase
            .from('stripe_events')
            .insert({ id: checkoutFulfillmentGuard })
          if (!packGuardError) {
            checkoutFulfillmentGuardAcquired = true
          } else if (packGuardError.code === '23505') {
            entitlementConfirmed = true
            entitlementPending = false
            console.log('[stripe webhook] credit pack already fulfilled:', session.id)
            break
          } else {
            throw new RetryableEntitlementError(
              `Failed to acquire credit-pack fulfillment guard (${session.id}): ${packGuardError.message}`
            )
          }

          // Legacy pack grants are additive. Record/reconcile the idempotent
          // commission before changing the balance, so a ledger failure can
          // safely release both guards and ask Stripe to retry without adding
          // the same credits twice.
          await recordAffiliateCommission(supabase, {
            userId,
            externalId: session.id,
            amountGross: session.amount_total ?? 0,
            currency: session.currency ?? 'usd',
            type: 'initial',
            paymentKind: 'one_time',
            attributionSystem: session.metadata?.affiliate_system,
            session,
          })

          const { data: profile, error: fetchErr } = await supabase
            .from('profiles')
            .select('video_credits')
            .eq('id', userId)
            .single()

          if (fetchErr) {
            throw new RetryableEntitlementError(
              `Failed to fetch profile for credit top-up (${userId}): ${fetchErr.message}`
            )
          }

          const current = profile?.video_credits ?? 0
          const next = current + creditsToAdd

          // KINEO-OFFER290-2026-07-07 — the first-purchase $2.90 offer is one per
          // account. When this session is the starter290 offer, also stamp
          // offer290_used=true so the buyer can never claim it again (checkout
          // rejects on that flag). Idempotent: this whole block only runs once
          // per event.id (stripe_events dedupe above).
          const isOffer290 = session.metadata?.pack === 'starter290'
          const profileUpdate: Record<string, unknown> = { video_credits: next, has_paid: true }
          if (isOffer290) profileUpdate.offer290_used = true
          // KINEO-STUDIO-ADS-2026-09-25 — passe do Studio Ads: o acesso (365 d) vai no MESMO UPDATE dos créditos e do
          // has_paid. Sem a coluna (migration 2026-09-25_studio_ads.sql não aplicada) o UPDATE inteiro falha, o erro
          // abaixo vira RetryableEntitlementError e a Stripe reenvia: nunca cobra sem conceder. Só este SKU escreve a
          // coluna, então nenhum outro pacote depende da migration. Recompra dentro do ano recomeça os 365 d a partir de hoje.
          const isAdsPass = packMeta === ADS_PASS_ID
          const adsUntilIso = isAdsPass ? adsAccessUntil(new Date()).toISOString() : null
          if (isAdsPass && adsUntilIso) profileUpdate[ADS_ACCESS_COLUMN] = adsUntilIso
          const isKitBf = packMeta === KIT_BF_PACK_ID // KINEO-KIT-BF-VENDA-2010
          const kitCur = isKitBf ? await supabase.from('profiles').select(ADS_ACCESS_COLUMN).eq('id', userId).single() : null // KINEO-KIT-BF-VENDA-2010 — o acesso atual (o kit nunca encurta um acesso maior)
          if (kitCur?.error) throw new RetryableEntitlementError(`Failed to read Studio Ads access for the Black Friday kit (${userId}): ${kitCur.error.message}`) // KINEO-KIT-BF-VENDA-2010 — sem a leitura (ou sem a coluna) = 500 e a Stripe reenvia; nada concedido ainda
          const kitUntilIso = isKitBf ? kitBfAccessUntilIso((kitCur?.data as { ads_access_until?: unknown } | null)?.ads_access_until) : null // KINEO-KIT-BF-VENDA-2010 — o MAIOR entre o acesso atual e 31/12 (fim do dia em Brasília)
          if (isKitBf && kitUntilIso) profileUpdate[ADS_ACCESS_COLUMN] = kitUntilIso // KINEO-KIT-BF-VENDA-2010 — no MESMO UPDATE dos créditos: sem a coluna, falha inteiro e a Stripe reenvia

          // KINEO-PILOT-99-2026-07-26 — este é o único ponto do Path A que escreve
          // `plan`. Duas regras:
          //  1) plan e plan_expires_at são escritos JUNTOS, no mesmo UPDATE. Se a
          //     coluna plan_expires_at não existir, o UPDATE inteiro falha e o
          //     plano NÃO é concedido — em vez de conceder um Autopilot eterno
          //     por $99. É o fail-closed que a migration exige.
          //  2) PROTECTED_EMAILS: o Path A nunca mexia em `plan`, então nunca
          //     checou. Agora mexe, então checa — os créditos continuam.
          if (isAutopilotPilot) {
            if (await isProtectedProfile(supabase, { userId })) {
              console.warn('[stripe webhook] autopilot_pilot: protected account, credits only, plan untouched:', userId)
            } else {
              profileUpdate.plan = AUTOPILOT_PILOT_PLAN
              profileUpdate.plan_expires_at = autopilotPilotExpiresAt().toISOString()
            }
          }

          const { error: updateErr } = await supabase
            .from('profiles')
            // KINEO-PACK-NOWM-2026-07-06 — mark buyer as paid so their free-plan
            // Fast renders come out watermark-free (the point of the $4.90 pack).
            .update(profileUpdate)
            .eq('id', userId)

          if (updateErr) {
            // KINEO-PILOT-99-2026-07-26 — 42703 = coluna inexistente. Se for isto,
            // a migration não foi aplicada e o SKU está INERTE. Erro retentável
            // (o guard de fulfillment é liberado no finally), então o Stripe
            // reenvia e o pagamento se resolve sozinho assim que a migration rodar.
            if ((isAdsPass || isKitBf) && ((updateErr as { code?: string }).code === '42703' || new RegExp(ADS_ACCESS_COLUMN).test(updateErr.message ?? ''))) { // KINEO-KIT-BF-VENDA-2010 — o kit também escreve a coluna; era: if (isAdsPass && …
              console.error(
                '[stripe webhook] ads_pass NOT GRANTED: profiles.' + ADS_ACCESS_COLUMN + ' is missing. ' +
                'Apply migrations_pending/2026-09-25_studio_ads.sql — the customer HAS BEEN CHARGED ' +
                `and this event will keep retrying until the column exists (session ${session.id}).`
              )
            }
            if (isAutopilotPilot && ((updateErr as { code?: string }).code === '42703' || /plan_expires_at/.test(updateErr.message ?? ''))) {
              console.error(
                '[stripe webhook] autopilot_pilot NOT GRANTED: profiles.plan_expires_at is missing. ' +
                'Apply migrations_pending/2026-07-26_autopilot_pilot_plan_expiry.sql — the customer HAS BEEN CHARGED ' +
                `and this event will keep retrying until the column exists (session ${session.id}).`
              )
            }
            throw new RetryableEntitlementError(
              `Failed to add credits (${userId}): ${updateErr.message}`
            )
          } else {
            entitlementConfirmed = true
            entitlementPending = false
            console.log(`[stripe webhook] +${creditsToAdd} credits → user ${userId} (now ${next})`)
            if (isAdsPass) {
              // Evento de servidor DEPOIS do UPDATE confirmado (a concessão é o fato; o evento é o registro).
              await writeServerEvent({
                name: 'ads_access_granted',
                userId,
                path: '/api/stripe/webhook',
                metadata: { stripe_session_id: session.id, until: adsUntilIso, credits: creditsToAdd, reason: 'pass' },
              })
              // KINEO-FLUXO-NOVO-2026-09-25 — a página promete revisão humana em 24 h: o fundador sabe do passe na hora.
              // Depois da concessão confirmada; 1×/sessão, teto de 3 s, nunca lança (lib/founderAlert.ts).
              await alertFounderAdsPass({ session, userId, credits: creditsToAdd, until: adsUntilIso })
            }
            if (isKitBf) await writeServerEvent({ name: KIT_BF_EVENTS.purchased, userId, path: '/api/stripe/webhook', metadata: { stripe_session_id: session.id, credits: creditsToAdd, until: kitUntilIso, amount_total: session.amount_total ?? null, currency: session.currency ?? null, kit_version: session.metadata?.kit_version ?? KIT_BF_VERSION } }) // KINEO-KIT-BF-VENDA-2010 — o evento de compra DEPOIS da concessão confirmada (a retentativa não chega aqui: o guard da sessão já está gravado)
            if (isAutopilotPilot) {
              console.log(`[stripe webhook] autopilot_pilot granted → user ${userId}, expires in ${AUTOPILOT_PILOT_DAYS}d`)
            }
            // KINEO-BULK-2026-07-27 — o momento do dinheiro, com nome próprio.
            // `payment_success` já registra esta sessão (com pack e amount_total),
            // mas contar atacado a partir dele exige filtrar metadata. Este evento
            // fecha o funil bulk_checkout_started → bulk_purchase_completed sem
            // ninguém precisar reconstruir a coorte na mão. Escrito DEPOIS do
            // grant confirmado: um evento de compra que não corresponde a crédito
            // concedido é pior que evento nenhum.
            if (bulkPack) {
              await recordBulkPurchase(supabase, {
                userId,
                session,
                videos: bulkPack.videos,
                credits: creditsToAdd,
                sku: packMeta,
              })
              console.log(`[stripe webhook] bulk pack ${packMeta}: ${bulkPack.videos} videos → user ${userId}`)
            }
          }
          // KINEO-REVERSE-TRIAL-P2-2026-08-07 — chegar aqui = crédito CONCEDIDO
          // (o ramo de erro lança antes). Um pack/piloto comprado durante ou
          // logo após o trial também é conversão.
          await markTrialConverted(supabase, userId, { source: 'checkout_payment', stripeRef: session.id })
          break
        }

        // ── Path B: Subscription checkout ──
        // ═══ KINEO-COMPRA-SEM-LOGIN-2026-10-06 — o dono da compra de quem não tinha conta ═══════════════════════
        // A sessão de convidado (kineo_guest=1, sempre mode 'subscription') nasce sem supabase_user_id. Aqui, antes do
        // grant, o webhook acha a conta pelo e-mail que a Stripe coletou ou cria uma (lib/stripe/guestCheckout.ts), e
        // carimba o dono no Customer, na Assinatura e na própria sessão da Stripe. O mesmo carimbo entra no objeto
        // desta entrega: daqui para baixo payment_success e o Path B leem EXATAMENTE o que leriam numa compra logada.
        // Qualquer falha = RetryableEntitlementError → 500 → a Stripe reenvia (o resolver é idempotente: mesmo e-mail,
        // carimbo em app_metadata, eventos com id determinístico). Sem kineo_guest=1, nada disto roda.
        // Conta NASCIDA desta compra: depois do grant sai UM e-mail "sua conta está pronta" (cobre quem fechou a aba).
        if (isKidsAutopilotSession(session)) { // KINEO-KIDS-VENDA-2010 — o piloto infantil é assinatura À PARTE (a pessoa pode ter Creator/Studio junto): nunca toca em plan/stripe_subscription_id; pedido de 30 por ciclo + has_paid; ANTES do Path B de sempre, que escreveria plan='basic'
          entitlementPending = true // KINEO-KIDS-VENDA-2010
          const kidsSubId = typeof session.subscription === 'string' ? session.subscription : session.subscription?.id ?? null // KINEO-KIDS-VENDA-2010
          if (!session.metadata?.supabase_user_id || !kidsSubId) throw new RetryableEntitlementError(`Kids autopilot Checkout missing ids (${session.id})`) // KINEO-KIDS-VENDA-2010
          const { error: kidsSubGuardError } = await supabase.from('stripe_events').insert({ id: checkoutFulfillmentGuard }) // KINEO-KIDS-VENDA-2010
          if (kidsSubGuardError && kidsSubGuardError.code === '23505') { entitlementConfirmed = true; entitlementPending = false; console.log('[stripe webhook] kids autopilot already fulfilled:', session.id); break } // KINEO-KIDS-VENDA-2010
          if (kidsSubGuardError) throw new RetryableEntitlementError(`Failed to acquire kids autopilot fulfillment guard (${session.id}): ${kidsSubGuardError.message}`) // KINEO-KIDS-VENDA-2010
          checkoutFulfillmentGuardAcquired = true // KINEO-KIDS-VENDA-2010
          let kidsSub: Stripe.Subscription // KINEO-KIDS-VENDA-2010
          try { kidsSub = await stripe.subscriptions.retrieve(kidsSubId) } catch (e) { throw new RetryableEntitlementError(`Failed to verify kids autopilot subscription (${kidsSubId}): ${e instanceof Error ? e.message : String(e)}`) } // KINEO-KIDS-VENDA-2010 — estado VIVO da Stripe (dono + active/trialing)
          const kidsAuto = await fulfillKidsAutopilot(supabase, session, kidsSub) // KINEO-KIDS-VENDA-2010
          if (!kidsAuto.ok) throw new RetryableEntitlementError(kidsAuto.error) // KINEO-KIDS-VENDA-2010 — o catch libera o guard e a Stripe reenvia
          entitlementConfirmed = true; entitlementPending = false // KINEO-KIDS-VENDA-2010
          console.log('[stripe webhook] kids autopilot:', kidsAuto.detail, session.id) // KINEO-KIDS-VENDA-2010
          break // KINEO-KIDS-VENDA-2010
        } // KINEO-KIDS-VENDA-2010
        let sendGuestReadyEmail: (() => Promise<void>) | null = null
        if (isGuestCheckoutSession(session)) {
          entitlementPending = true
          let guestOwner: GuestCheckoutOwner
          try {
            guestOwner = await resolveGuestCheckoutOwner(guestOwnerDepsFor(supabase, stripe), session)
          } catch (guestOwnerError) {
            const reason = guestOwnerError instanceof Error ? guestOwnerError.message : String(guestOwnerError)
            throw new RetryableEntitlementError(`Guest checkout owner unresolved (${session.id}): ${reason}`)
          }
          session.metadata = { ...(session.metadata ?? {}), supabase_user_id: guestOwner.userId }
          // O payment_success de cima pulou esta sessão (dono ainda desconhecido); agora ele sai com o user_id.
          try {
            await recordPaymentSuccess(supabase, event.id, session)
          } catch (trackingError) {
            console.error('[stripe webhook] guest payment_success tracking threw:', trackingError)
          }

          // ═══ KINEO-CUPOM-CONVIDADO-2026-10-07 — desconto de boas-vindas numa conta que JÁ tinha pago ═══════════════
          // Sem conta, ninguém pôde checar "um desconto de boas-vindas por cliente" antes de cobrar, e a Stripe não checa
          // por e-mail (sessão sem `customer` conta como primeira transação: docs.stripe.com/payments/checkout/discounts).
          // Risco aceito pelo fundador em 07/10 (20% de UM mês): aqui ele vira fato, no padrão do guest_conflict — evento
          // com dono e id determinístico (reentrega não duplica; falha de gravação = 500 e a Stripe reenvia, antes do
          // grant) e aviso ao fundador 1×/sessão. O grant segue igual: a pessoa pagou o que a tela prometeu.
          if (guestOwner.welcomePromoReuse) {
            const { error: reuseEventError } = await supabase.from('events').insert({
              id: deterministicEventUuid(GUEST_CHECKOUT_EVENTS.welcomePromoReused, session.id),
              name: GUEST_CHECKOUT_EVENTS.welcomePromoReused,
              user_id: guestOwner.userId,
              path: '/api/stripe/webhook',
              metadata: {
                source: 'stripe_webhook',
                version: GUEST_CHECKOUT_VERSION,
                stripe_session_id: session.id,
                stripe_subscription_id: typeof session.subscription === 'string' ? session.subscription : session.subscription?.id ?? null,
                reuse_reason: guestOwner.welcomePromoReuse,
                conflict: guestOwner.conflict,
                tier: session.metadata?.tier ?? null,
                amount_total: session.amount_total ?? null,
                amount_discount: session.total_details?.amount_discount ?? null,
                currency: session.currency ?? null,
                ...guestWelcomePromoEventMetadata(session.metadata),
              },
            })
            if (reuseEventError && reuseEventError.code !== '23505') {
              throw new RetryableCheckoutAnalyticsError(`Guest welcome promo reuse not recorded (${session.id}): ${reuseEventError.message}`)
            }
            await alertFounderOnce({
              kind: 'guest_welcome_promo_reused',
              stripeSessionId: session.id,
              subject: '[Kineo] Desconto de boas-vindas usado por conta que já pagou (compra sem login)',
              text:
                `Sessão ${session.id} pagou ${paidAmountLabel(session.amount_total, session.currency)} (${session.metadata?.tier ?? 'plano'}) ` +
                `com o desconto de boas-vindas (${WELCOME20_PERCENT_OFF}% do 1º mês; desconto de ` +
                `${paidAmountLabel(session.total_details?.amount_discount, session.currency)}) num e-mail cuja conta JÁ tinha pago antes ` +
                `(${guestOwner.welcomePromoReuse}). ` +
                (guestOwner.conflict
                  ? `A conta tem plano ativo (${guestOwner.conflict}): nada foi concedido — ver o aviso de conflito desta sessão. `
                  : 'O plano foi concedido normalmente (o mesmo grant do caminho logado). ') +
                'Risco aceito em 07/10 (o desconto é de um mês): nada a fazer, salvo se repetir — o evento ' +
                `${GUEST_CHECKOUT_EVENTS.welcomePromoReused} conta os casos. user_id=${guestOwner.userId}`,
            })
          }

          // O e-mail já tinha plano ativo vindo de OUTRA assinatura. O caminho logado teria recusado antes de cobrar
          // ("You already have a Kineo subscription"); aqui o dinheiro já entrou. Nada é sobrescrito nem concedido: o
          // conflito vira marcador (a página /checkout/guest lê) + evento com dono, e o fundador é avisado (1×/sessão).
          // A renovação desta 2ª assinatura cai no ramo "superseded" e não toca o perfil.
          if (guestOwner.conflict) {
            const { error: conflictMarkerError } = await supabase
              .from('stripe_events')
              .insert({ id: guestConflictMarkerId(session.id) })
            if (conflictMarkerError && conflictMarkerError.code !== '23505') {
              throw new RetryableCheckoutAnalyticsError(`Guest conflict marker not recorded (${session.id}): ${conflictMarkerError.message}`)
            }
            const { error: conflictEventError } = await supabase.from('events').insert({
              id: deterministicEventUuid(GUEST_CHECKOUT_EVENTS.conflict, session.id),
              name: GUEST_CHECKOUT_EVENTS.conflict,
              user_id: guestOwner.userId,
              path: '/api/stripe/webhook',
              metadata: {
                source: 'stripe_webhook',
                version: GUEST_CHECKOUT_VERSION,
                stripe_session_id: session.id,
                stripe_subscription_id: typeof session.subscription === 'string' ? session.subscription : session.subscription?.id ?? null,
                conflict: guestOwner.conflict,
                tier: session.metadata?.tier ?? null,
                amount_total: session.amount_total ?? null,
                currency: session.currency ?? null,
              },
            })
            if (conflictEventError && conflictEventError.code !== '23505') {
              throw new RetryableCheckoutAnalyticsError(`Guest conflict event not recorded (${session.id}): ${conflictEventError.message}`)
            }
            await alertFounderOnce({
              kind: 'guest_conflict',
              stripeSessionId: session.id,
              subject: `[Kineo] Compra sem login caiu em conta que JÁ tem plano (${guestOwner.conflict})`,
              text:
                `Sessão ${session.id} pagou ${paidAmountLabel(session.amount_total, session.currency)} (${session.metadata?.tier ?? 'plano'}) ` +
                `com um e-mail que já tem acesso pago (${guestOwner.conflict}). Nada foi concedido nem sobrescrito: a conta ` +
                `segue no plano de antes e esta 2ª assinatura está ativa na Stripe. Decidir: reembolsar/cancelar a nova ` +
                `ou trocar o plano à mão. user_id=${guestOwner.userId}`,
            })
            entitlementConfirmed = true
            entitlementPending = false
            console.warn('[stripe webhook] guest checkout conflict recorded; no grant:', session.id, guestOwner.conflict)
            break
          }
          if (guestOwner.created) {
            const readyOwner = guestOwner
            sendGuestReadyEmail = async () => {
              await sendGuestAccountReadyEmailOnce({
                admin: supabase,
                stripeSessionId: session.id,
                userId: readyOwner.userId,
                email: readyOwner.email,
                secret: process.env.SUPABASE_SERVICE_ROLE_KEY,
                resendKey: process.env.RESEND_API_KEY,
                from: process.env.RESEND_FROM_EMAIL || 'Kineo <support@usekineo.com>',
              })
            }
          }
        }
        const userId = session.metadata?.supabase_user_id
        const customerId = typeof session.customer === 'string'
          ? session.customer
          : session.customer?.id ?? null
        const subscriptionId = typeof session.subscription === 'string'
          ? session.subscription
          : session.subscription?.id ?? null
        // KINEO-AUTOPILOT-299-2026-07-26 — 'autopilot' added. Unknown values
        // still collapse to 'basic', unchanged.
        const tier: CheckoutPlanTier =
          session.metadata?.tier === 'pro' ? 'pro'
            : session.metadata?.tier === 'starter' ? 'starter'
              : session.metadata?.tier === 'autopilot' ? 'autopilot'
                : session.metadata?.tier === 'autopilot_lite' ? 'autopilot_lite' // KINEO-AUTOPILOT-LITE
                  : session.metadata?.tier === 'business' ? 'business' // KINEO-BUSINESS-84-2026-10-09
                    : 'basic'

        entitlementPending = true
        if (!userId || !customerId || !subscriptionId) {
          throw new RetryableEntitlementError(
            `Settled subscription Checkout missing authoritative ids (${session.id})`
          )
        }

        // Conversion — 3-day trial: if payment_status is 'no_payment_required'
        // the subscription is in trial. Grant 5 preview credits so the user
        // can experience the product before paying; full credits are granted
        // by the invoice.payment_succeeded handler on Day 4 first charge.
        // KINEO-TRIAL-1DOLAR-LIGADO-2026-09-07 — o trial de 7 dias cobra $1 no ato
        // (add_invoice_items), entao payment_status vem 'paid' e amount_total=100;
        // o carimbo card_trial na metadata da sessao e o que diz "isto e trial":
        // concede TRIAL_GRANT_CREDITS agora; o mes cheio entra no dia 8 pela
        // invoice.payment_succeeded (subscription_cycle), como ja acontecia.
        const isTrial = session.payment_status === 'no_payment_required' || session.metadata?.card_trial === '1'
        // KINEO-STUDIO-400-2026-07-06 — Studio(pro)=400 (aligned with pricing.ts
        // + UI; was 600 here, 360 there → margin leak). Creator(basic) 240, Starter 50.
        // KINEO-PRICING-V3B-2026-07-10 — Creator $24.90 grants 150 credits
        // (1 Hollywood film/month included). pro/starter ALINHADOS ao rebase
        // 2:1 (200/25, iguais ao lib/pricing.ts) — fecha o leak de margem.
        // KINEO-PRICING-V3D-2026-07-26 — single source (lib/checkoutPricing).
        const planCredits = TIER_CREDITS[tier]
        // KINEO-PRICING-V3D-2026-07-26 — DEFECT (b). A discounted first month
        // gets a discounted grant. The checkout route writes the reduced number
        // into session.metadata.intro_credits (and plan_credits) whenever the
        // intro coupon is actually applied; it is read HERE, at
        // checkout.session.completed, and NOWHERE ELSE.
        //
        // This deliberately does NOT read subscription.metadata.intro. That
        // flag is permanent — it is the anti-abuse marker meaning "this
        // customer has used their one intro" — so keying the reduced grant off
        // it would under-grant every renewal for the life of the subscription.
        // invoice.payment_succeeded (the renewal path) grants TIER_CREDITS.
        const introCreditsRaw = Number(session.metadata?.intro_credits ?? 0)
        const introApplied = session.metadata?.intro === '1' &&
          Number.isFinite(introCreditsRaw) &&
          introCreditsRaw > 0 &&
          introCreditsRaw <= planCredits
        const firstMonthCredits = introApplied ? Math.floor(introCreditsRaw) : planCredits
        // ⚠️ KINEO-TRIAL-CARTAO-2026-08-20 — os 5 créditos eram do trial de 3
        // dias que nunca chegou a rodar (5cr não compram NADA: um Seedance
        // custa 20). O trial novo é de 7 dias COM CARTÃO e o grant precisa
        // valer o que a página prometeu: TRIAL_GRANT_CREDITS (80 = 4 filmes).
        // Se a pessoa deu o cartão e recebeu 5 créditos, ela cancela no mesmo
        // dia — e com razão. O restante do plano entra no dia 8, quando a
        // primeira fatura é paga (invoice.payment_succeeded, caminho que já
        // existe e concede TIER_CREDITS).
        // KINEO-TRIAL-1DOLAR-LIGADO-2026-09-07 — trial de cartao ($1) recebe
        // CARD_TRIAL_GRANT_CREDITS (80); o trial sem cobranca (3 dias, nunca ligado)
        // continua em TRIAL_GRANT_CREDITS. O mes cheio entra no dia 8.
        const isCardTrial = session.metadata?.card_trial === '1'
        const creditsToGrant = isCardTrial ? CARD_TRIAL_GRANT_CREDITS : isTrial ? TRIAL_GRANT_CREDITS : firstMonthCredits
        const subscriptionFulfillmentId = `checkout_fulfilled:${session.id}`
        const publishSubscriptionFulfillment = async (): Promise<void> => {
          const { error: fulfillmentCompleteError } = await supabase
            .from('stripe_events')
            .insert({ id: subscriptionFulfillmentId })
          if (fulfillmentCompleteError && fulfillmentCompleteError.code !== '23505') {
            throw new RetryableEntitlementError(
              `Failed to publish Checkout fulfillment (${session.id}): ${fulfillmentCompleteError.message}`
            )
          }
        }

        const { data: fulfilledSession, error: fulfilledLookupError } = await supabase
          .from('stripe_events')
          .select('id')
          .eq('id', subscriptionFulfillmentId)
          .maybeSingle()
        if (fulfilledLookupError) {
          throw new RetryableEntitlementError(
            `Failed to verify Checkout fulfillment (${session.id}): ${fulfilledLookupError.message}`
          )
        }
        if (fulfilledSession?.id === subscriptionFulfillmentId) {
          entitlementConfirmed = true
          entitlementPending = false
          await recordAffiliateCommission(supabase, { userId, externalId: session.id, amountGross: session.amount_total ?? 0, currency: session.currency ?? 'usd', type: 'initial', paymentKind: 'subscription', attributionSystem: session.metadata?.affiliate_system, session, plan: session.metadata?.tier })
          // KINEO-REVERSE-TRIAL-P2-2026-08-07 — cobre a janela de crash entre
          // o publish do fulfillment e o carimbo da primeira execução: o resume
          // idempotente passa por aqui, e a UPDATE guardada faz 0 linhas quando
          // já convertido.
          await markTrialConverted(supabase, userId, { source: 'checkout_subscription_resumed', stripeRef: session.id })
          // KINEO-COMPRA-SEM-LOGIN-2026-10-06 — a entrega anterior pode ter morrido entre o grant e o e-mail (1×/sessão).
          if (sendGuestReadyEmail) await sendGuestReadyEmail()
          console.log('[stripe webhook] subscription Checkout already fulfilled:', session.id)
          break
        }

        let currentSubscription: Stripe.Subscription
        try {
          currentSubscription = await stripe.subscriptions.retrieve(subscriptionId)
        } catch (subscriptionLookupError) {
          const message = subscriptionLookupError instanceof Error
            ? subscriptionLookupError.message
            : String(subscriptionLookupError)
          throw new RetryableEntitlementError(
            `Failed to verify current subscription state (${subscriptionId}): ${message}`
          )
        }
        const currentSubscriptionCustomerId = typeof currentSubscription.customer === 'string'
          ? currentSubscription.customer
          : currentSubscription.customer?.id ?? null
        const currentSubscriptionUserId = currentSubscription.metadata?.supabase_user_id
        if (
          currentSubscriptionCustomerId !== customerId ||
          currentSubscriptionUserId !== userId
        ) {
          throw new RetryableEntitlementError(
            `Subscription identity mismatch for settled Checkout (${session.id})`
          )
        }
        const subscriptionGrantsAccess =
          currentSubscription.status === 'active' || currentSubscription.status === 'trialing'
        if (!subscriptionGrantsAccess) {
          // A late/replayed Checkout event must never reactivate a subscription
          // that Stripe now reports as canceled, unpaid, paused or otherwise
          // non-access. The original payment remains recorded for analytics and
          // affiliate accounting, then this stale event is closed permanently.
          await recordAffiliateCommission(supabase, { userId, externalId: session.id, amountGross: session.amount_total ?? 0, currency: session.currency ?? 'usd', type: 'initial', paymentKind: 'subscription', attributionSystem: session.metadata?.affiliate_system, session, plan: session.metadata?.tier })
          await publishSubscriptionFulfillment()
          entitlementConfirmed = true
          entitlementPending = false
          console.warn('[stripe webhook] stale Checkout replay ignored for non-access subscription:', session.id, subscriptionId, currentSubscription.status)
          break
        }
        // KINEO-AUTOPILOT-299-2026-07-26 — 'autopilot' added. Unlike the parse
        // above this one keeps `null` as its fallback: null means "the live
        // subscription carries no recognizable tier", which must NOT be treated
        // as a tier change.
        const currentSubscriptionTier: CheckoutPlanTier | null =
          currentSubscription.metadata?.tier === 'pro'
            ? 'pro'
            : currentSubscription.metadata?.tier === 'starter'
              ? 'starter'
              : currentSubscription.metadata?.tier === 'basic'
                ? 'basic'
                : currentSubscription.metadata?.tier === 'autopilot'
                  ? 'autopilot'
                  : currentSubscription.metadata?.tier === 'autopilot_lite'
                    ? 'autopilot_lite' // KINEO-AUTOPILOT-LITE
                    : currentSubscription.metadata?.tier === 'business'
                      ? 'business' // KINEO-BUSINESS-84-2026-10-09
                      : null
        if (currentSubscriptionTier && currentSubscriptionTier !== tier) {
          // The same Stripe subscription can be changed to another tier after
          // its original Checkout. A delayed replay of that old Checkout must
          // not add the old grant or downgrade the account back to its historic
          // tier. The live subscription metadata is authoritative here.
          await recordAffiliateCommission(supabase, { userId, externalId: session.id, amountGross: session.amount_total ?? 0, currency: session.currency ?? 'usd', type: 'initial', paymentKind: 'subscription', attributionSystem: session.metadata?.affiliate_system, session, plan: session.metadata?.tier })
          await publishSubscriptionFulfillment()
          entitlementConfirmed = true
          entitlementPending = false
          console.warn('[stripe webhook] stale Checkout replay ignored after subscription tier change:', session.id, tier, currentSubscriptionTier)
          break
        }

        const { data: currentProfile, error: currentProfileErr } = await supabase
          .from('profiles')
          .select('video_credits, stripe_subscription_id, plan, is_pro')
          .eq('id', userId)
          .single()

        if (currentProfileErr) {
          throw new RetryableEntitlementError(
            `Failed to read subscription profile (${userId}): ${currentProfileErr.message}`
          )
        }

        const current = currentProfile?.video_credits ?? 0
        const expectedPlan = isTrial ? `${tier}_trial` : tier
        const resumedGrant =
          currentProfile?.stripe_subscription_id === subscriptionId &&
          (currentProfile?.plan === expectedPlan || (isTrial && currentProfile?.plan === tier)) &&
          currentProfile?.is_pro === true
        // The first grant is additive so paid pack credits remain in the
        // account. A retry sees the same subscription id and writes the current
        // absolute balance unchanged; concurrent first events read the same
        // balance and converge on the same absolute next value.
        const next = resumedGrant ? current : current + creditsToGrant

        // Push #088 — Pro plan also includes 1 cinematic token / month.
        // KINEO-AUTOPILOT-299-2026-07-26 — Autopilot gets one too: at $299 it
        // sits above Studio, and withholding a $0-marginal-cost token from the
        // most expensive plan would be indefensible if anyone noticed.
        const cinematicTokensForTier = (tier === 'pro' || tier === 'autopilot') ? 1 : 0

        if (!resumedGrant) {
          const { data: updatedProfile, error: subUpdErr } = await supabase
            .from('profiles')
            .update({
              is_pro: true,
              plan: expectedPlan,
              stripe_customer_id: customerId,
              stripe_subscription_id: subscriptionId,
              video_credits: next,
              cinematic_tokens: isTrial ? 0 : cinematicTokensForTier,
              has_paid: true, // KINEO-PACK-NOWM-2026-07-06 — clean output for paid users
            })
            .eq('id', userId)
            .select('id')
            .maybeSingle()

          if (subUpdErr || !updatedProfile?.id) {
            throw new RetryableEntitlementError(
              `Subscription credit grant failed (${userId}): ${subUpdErr?.message ?? 'profile row missing'}`
            )
          }
        }

        // Commission insert is independently idempotent by external_id. Run it
        // before publishing fulfillment so a crash cannot leave a permanent
        // completed marker with the commission missing.
        await recordAffiliateCommission(supabase, { userId, externalId: session.id, amountGross: session.amount_total ?? 0, currency: session.currency ?? 'usd', type: 'initial', paymentKind: 'subscription', attributionSystem: session.metadata?.affiliate_system, session, plan: session.metadata?.tier })

        // This marker means completed, so publish it only after the idempotent
        // profile update. If publication fails, Stripe retries; the same
        // subscription id + absolute balance write is harmless on that retry.
        await publishSubscriptionFulfillment()

        entitlementConfirmed = true
        entitlementPending = false
        console.log(`[stripe webhook] ${isTrial ? 'TRIAL' : 'subscription'} start: ${tier} (${resumedGrant ? 'resumed idempotently' : `balance ${current}→${next}`}) → user ${userId}`)

        // KINEO-REVERSE-TRIAL-P2-2026-08-07 — assinatura criada = conversão do
        // reverse trial. Vale também para isTrial (sub em trial do Stripe): o
        // plano vira `${tier}_trial`, que isPayingProfile já conta como pagante
        // — o webhook e o cron dão o MESMO veredito sobre a mesma linha.
        await markTrialConverted(supabase, userId, { source: 'checkout_subscription', stripeRef: session.id })

        // KINEO-COMPRA-SEM-LOGIN-2026-10-06 — conta nascida desta compra, plano já concedido: "sua conta está pronta"
        // (1×/sessão Stripe, nunca lança). Conta que já existia: sendGuestReadyEmail fica null (ela recebe só o link
        // que a página /checkout/guest manda).
        if (sendGuestReadyEmail) await sendGuestReadyEmail()

        break
      }

      case 'checkout.session.async_payment_failed': {
        const session = event.data.object as Stripe.Checkout.Session
        await recordAsyncCheckoutState(session, 'failed')
        break
      }

      case 'checkout.session.expired': {
        // Push #259 — track abandoned checkouts so we can measure drop-off.
        // Supabase SQL to create the table (run once in the SQL editor):
        //
        //   create table if not exists public.checkout_abandoned (
        //     id uuid default gen_random_uuid() primary key,
        //     user_id uuid references auth.users(id),
        //     tier text,
        //     currency text,
        //     amount_total bigint,
        //     stripe_session_id text unique,
        //     expired_at timestamptz default now()
        //   );
        const expiredSession = event.data.object as Stripe.Checkout.Session
        const abandonedUserId = expiredSession.metadata?.supabase_user_id ?? null
        const abandonedTier = expiredSession.metadata?.tier ?? null

        try {
          const { error: abanErr } = await supabase
            .from('checkout_abandoned')
            .insert({
              user_id: abandonedUserId,
              tier: abandonedTier,
              currency: expiredSession.currency,
              amount_total: expiredSession.amount_total,
              stripe_session_id: expiredSession.id,
            })
          if (abanErr && abanErr.code !== '42P01' && abanErr.code !== '23505') {
            // 42P01 = table doesn't exist yet (migration not applied — non-fatal)
            // 23505 = duplicate — already recorded
            console.error('[stripe webhook] checkout_abandoned insert error:', abanErr.code, abanErr.message)
          } else {
            console.log(`[stripe webhook] checkout abandoned: session=${expiredSession.id} user=${abandonedUserId} tier=${abandonedTier}`)
          }
        } catch (abanCatch) {
          console.warn('[stripe webhook] checkout_abandoned insert threw:', abanCatch)
        }

        // ═══════════════════════════════════════════════════════════════════
        // KINEO-PAREDE-CHECKOUT-2026-08-16 — a expiração também vira EVENTO.
        // ═══════════════════════════════════════════════════════════════════
        // POR QUE: `checkout_abandoned` é o livro-caixa VERDADEIRO de quem
        // chegou na página de pagamento (o webhook escreve, o servidor da
        // Stripe manda), e `events` só conhecia `checkout_started`, que é
        // emitido pelo BROWSER. As duas contagens divergem por ~2x: para INR,
        // `events` conhecia 11 pessoas em 42 dias e o livro-caixa conhece 27.
        // Todo funil da operação foi lido em `events`, logo todo funil
        // SUBCONTOU o abandono de checkout. Este evento fecha o par
        // `checkout_started` → `checkout_session_expired` dentro da MESMA
        // tabela, para que a taxa de fechamento exista sem ninguém
        // reconstruir coorte na mão em duas fontes.
        //
        // ⚠️ DESCONTINUIDADE: esta linha nasce hoje. Um salto em
        // `checkout_session_expired` a partir deste deploy é o INSTRUMENTO
        // nascendo, não abandono novo. O histórico verdadeiro está em
        // `checkout_abandoned` desde 25/05/2026 e continua lá.
        //
        // SERVER_ONLY (app/api/events/route.ts): se o sink do browser pudesse
        // cunhar isto, um burst forjado faria a parede do checkout parecer
        // maior do que é e mandaria a operação consertar o lugar errado.
        let expiredWritten = false
        try {
          expiredWritten = await writeServerEvent({
            name: 'checkout_session_expired',
            userId: abandonedUserId,
            path: '/api/stripe/webhook',
            metadata: {
              source: 'stripe_webhook',
              stripe_event_id: event.id,
              stripe_session_id: expiredSession.id,
              tier: abandonedTier,
              billing: expiredSession.metadata?.billing ?? null,
              pack: expiredSession.metadata?.pack ?? null,
              checkout_origin: expiredSession.metadata?.checkout_origin ?? null,
              plan_fit_planned_engine: expiredSession.metadata?.plan_fit_planned_engine ?? null,
              plan_fit_monthly_videos: expiredSession.metadata?.plan_fit_monthly_videos ?? null,
              plan_fit_monthly_credits: expiredSession.metadata?.plan_fit_monthly_credits ?? null,
              plan_fit_seconds: expiredSession.metadata?.plan_fit_seconds ?? null,
              plan_fit_recommended_tier: expiredSession.metadata?.plan_fit_recommended_tier ?? null,
              plan_fit_selected_tier_matches: expiredSession.metadata?.plan_fit_selected_tier_matches ?? null,
              plan_fit_video_id: expiredSession.metadata?.plan_fit_video_id ?? null,
              intro: expiredSession.metadata?.intro === '1',
              currency: expiredSession.currency ?? null,
              // KINEO-PAGAR-SETTLEMENT-NO-FUNIL-2026-09-10 — `currency` acima é
              // a moeda REAL da Stripe, mas o MESMO nome em `checkout_started`
              // é o preço de LISTA (sempre 'usd'). Repetir a verdade sob um
              // nome que não colide deixa o par started→expired comparável sem
              // ninguém precisar saber qual dos dois sentidos vale em cada
              // evento. `settlement_reason` diz POR QUE a sessão nasceu nessa
              // moeda (ip_country, language, prior_br_card_failure, forced,
              // default) — sem ele, uma parede brasileira é indistinguível de
              // uma parede americana que por acaso pagaria em real.
              settlement_currency: expiredSession.metadata?.settlement_currency ?? null,
              settlement_reason: expiredSession.metadata?.settlement_reason ?? null,
              list_price_usd_minor: expiredSession.metadata?.list_price_usd_minor ?? null,
              amount_total: expiredSession.amount_total ?? null,
              checkout_mode: expiredSession.mode ?? null,
              // `payment_status` separa duas mortes MUITO diferentes:
              // 'unpaid' = nunca digitou cartão; 'no_payment_required' = sessão
              // de valor zero. Sem isto, "expirou" mistura quem desistiu com
              // quem tentou e foi recusado.
              payment_status: expiredSession.payment_status ?? null,
              customer_country:
                expiredSession.customer_details?.address?.country ?? null,
              // ═══════════════════════════════════════════════════════════
              // KINEO-PAIS-DA-PAREDE-2026-08-17 — o campo acima é null SEMPRE
              // nesta parede, e isso foi MEDIDO, não suposto: as 10 primeiras
              // leituras do instrumento (17/08, 04:10Z–14:10Z) trouxeram
              // `customer_country: null` nas 10. A Stripe só preenche
              // `customer_details.address` quando a pessoa DIGITA o endereço,
              // e a parede é precisamente o lugar onde ninguém digita nada.
              //
              // `ip_country` vem da metadata que a rota de checkout carimba na
              // CRIAÇÃO da sessão (x-vercel-ip-country — o mesmo header que
              // resolve moeda e região). Ele existe para toda sessão criada
              // após o deploy de 17/08, inclusive as que morrem sem um
              // caractere digitado.
              //
              // Os dois campos ficam LADO A LADO de propósito: são coisas
              // diferentes e vão discordar. `customer_country` é declaração do
              // comprador (raro, mas verdadeiro); `ip_country` é inferência de
              // rede (sempre presente, e uma VPN mente). Colapsar os dois num
              // campo só apagaria essa diferença exatamente quando ela importa.
              //
              // ⚠️ DESCONTINUIDADE: sessões criadas ANTES deste deploy não têm
              // a metadata e continuarão com `ip_country: null` até expirarem
              // (janela de 2h). Um null depois de 17/08 + 2h é defeito; antes
              // disso é só idade.
              ip_country: expiredSession.metadata?.ip_country ?? null,
              // ═══════════════════════════════════════════════════════════
              // KINEO-SEGUNDA-TENTATIVA-2026-08-17 — O ATIVO QUE ESTÁVAMOS
              // JOGANDO FORA (leitura pura; NENHUM e-mail muda aqui).
              // ═══════════════════════════════════════════════════════════
              // Medição de 17/08 (30 dias, contas internas fora): 84% das
              // pessoas tocam a Stripe UMA vez e somem; quem tenta de novo
              // converte ~3x mais e responde por metade dos pagantes do mês.
              // A alavanca não é a página de pagamento — é fazer existir uma
              // SEGUNDA TENTATIVA.
              //
              // `after_expiration.recovery.enabled` está ligado desde
              // 03/08 (rota de checkout, linha ~1003), o que significa que a
              // Stripe MINTA uma URL de retomada para CADA sessão que expira.
              // `grep -rn "recovered_url\|recovery.url"` em app/ e lib/
              // devolvia zero: nunca foi lida por ninguém. Toda expiração
              // desde 03/08 gerou esse ativo e o descartou.
              //
              // Isso importa porque `KINEO-RECOVERY-NO-MINT-LINK-2026-08-11`
              // (cron send-recovery) documentou as DUAS armadilhas que
              // impediam um link de retomada no e-mail — preço (um link
              // `/api/stripe/checkout?tier=X` sem `intro=1` cobra 2,0–2,5x o
              // que a pessoa viu) e scanner corporativo (Outlook Safe Links
              // MINTA sessão a cada GET, sujando `checkout_attempted`). A URL
              // da própria Stripe **não tem nenhuma das duas**: ela É a sessão
              // original, com o preço original, e não cria sessão nova.
              //
              // ⚠️ POR QUE UM BOOLEANO E NÃO A URL: essa URL é uma credencial
              // de pagamento viva. `events` hoje bloqueia leitura anônima
              // (policy `no_public_read`, qual=false), mas guardar link de
              // pagamento em repouso o faz vazar para todo export de
              // analytics futuro, e essa é uma decisão de segurança que
              // ninguém pediu. O booleano responde à única pergunta que a
              // decisão precisa ("o ativo existe e quanto dura?"); quando o
              // fundador liberar o GATE #H, o remetente busca a URL fresca na
              // Stripe pelo `stripe_session_id`, que já está aqui do lado.
              //
              // NÃO ligo o link no e-mail nesta sprint DE PROPÓSITO: mexer em
              // e-mail do fluxo de pagamento é GATE #H do fundador, e o autor
              // de 11/08 já tinha parado exatamente aqui. Isto carrega a arma;
              // o gatilho continua sendo dele.
              recovery_url_available: Boolean(
                expiredSession.after_expiration?.recovery?.url,
              ),
              recovery_url_expires_at:
                expiredSession.after_expiration?.recovery?.expires_at ?? null,
            },
          })
          // A linha de `checkout_abandoned` tem FK em auth.users: uma conta
          // apagada derruba o INSERT inteiro e leva junto a MOEDA, que é a
          // única coisa que esta instrumentação existe para contar. Se o
          // evento não entrou com dono, ele entra sem dono. Perder o nome é
          // barato; perder o denominador corrompe o funil.
          if (!expiredWritten) {
            await writeServerEvent({
              name: 'checkout_session_expired',
              userId: null,
              path: '/api/stripe/webhook',
              metadata: {
                source: 'stripe_webhook',
                stripe_event_id: event.id,
                stripe_session_id: expiredSession.id,
                orphaned_user: true,
                tier: abandonedTier,
                checkout_origin: expiredSession.metadata?.checkout_origin ?? null,
                plan_fit_monthly_videos: expiredSession.metadata?.plan_fit_monthly_videos ?? null,
                plan_fit_planned_engine: expiredSession.metadata?.plan_fit_planned_engine ?? null,
                currency: expiredSession.currency ?? null,
                // KINEO-PAGAR-SETTLEMENT-NO-FUNIL-2026-09-10 — pela mesma razão
                // que a moeda sobrevive ao ramo órfão: a moeda de LIQUIDAÇÃO é
                // denominador de receita por país. Uma conta apagada é
                // justamente o caso em que ninguém pode reconstruir depois.
                settlement_currency: expiredSession.metadata?.settlement_currency ?? null,
                settlement_reason: expiredSession.metadata?.settlement_reason ?? null,
                amount_total: expiredSession.amount_total ?? null,
                payment_status: expiredSession.payment_status ?? null,
                // KINEO-PAIS-DA-PAREDE-2026-08-17 — mesma razão pela qual a
                // moeda sobrevive a este ramo: o país é DENOMINADOR, não
                // adorno. Uma conta apagada é justamente o caso em que o
                // perfil não pode mais informar a região depois; se o país
                // não vier aqui, ele não vem de lugar nenhum.
                ip_country: expiredSession.metadata?.ip_country ?? null,
              },
            })
          }
        } catch (expiredEventThrown) {
          console.warn('[stripe webhook] checkout_session_expired event threw:', expiredEventThrown)
        }
        break
      }

      // ═════════════════════════════════════════════════════════════════════
      // KINEO-PAREDE-CHECKOUT-2026-08-16 — O EVENTO QUE RESPONDE "POR QUÊ".
      // ═════════════════════════════════════════════════════════════════════
      // Medido em 16/08: 84 pessoas externas abriram uma sessão de checkout ao
      // vivo e foram embora; a empresa tem 7 pagantes na vida inteira. Dessas
      // 84, 27 (32%) são INR — e o histórico de `payment_success` é 100% USD:
      // nunca entrou uma rupia.
      //
      // O problema é que HOJE não dá para distinguir as duas causas, que pedem
      // remédios opostos:
      //   (a) o cartão foi RECUSADO  → é defeito técnico/regulatório nosso
      //       (RBI e-mandate: conta Stripe fora da Índia precisa registrar
      //        mandato para cobrança recorrente em cartão indiano — sem ele a
      //        cobrança off-session é recusada);
      //   (b) a pessoa MUDOU DE IDEIA → é preço/oferta.
      // Os dois deixam exatamente o mesmo rastro: `checkout_started` e silêncio.
      // Toda coorte definida por AUSÊNCIA passa por `events` antes de virar
      // decisão — e esta não tinha por onde passar.
      //
      // Um PaymentIntent é a fonte CANÔNICA da recusa. `charge.failed` chega
      // junto para cartão e vira apenas enriquecimento, com outro nome. Antes
      // ambos cunhavam `checkout_payment_failed`, duplicando uma mesma recusa.
      // Nenhum dos dois altera crédito, plano ou entitlement.
      case 'payment_intent.payment_failed': {
        const failedIntent = event.data.object as Stripe.PaymentIntent
        const lastError = failedIntent.last_payment_error ?? null
        // KINEO-RECUSA-COM-NOME-2026-09-07 — a escada inteira mora no
        // resolvedor (metadata do intent → assinatura da fatura → sessão de
        // checkout → customer_id → e-mail do customer). Antes daqui existiam
        // só os dois primeiros passos do fim da escada, e eles alcançam
        // exclusivamente quem já pagou uma vez.
        const invoiceContext = await resolvePaymentIntentInvoiceContext(failedIntent, supabase)
        const failedUserId: string | null = invoiceContext.ownerUserId

        const failureMetadata = buildCanonicalStripeCheckoutFailure({
          paymentIntentId: failedIntent.id,
          errorCode: lastError?.code ?? null,
          declineCode: lastError?.decline_code ?? null,
          currency: failedIntent.currency ?? null,
          amountMinor: failedIntent.amount ?? null,
          cardCountry: lastError?.payment_method?.card?.country ?? null,
          cardBrand: lastError?.payment_method?.card?.brand ?? null,
          cardFunding: lastError?.payment_method?.card?.funding ?? null,
          paymentMethodType: lastError?.payment_method?.type ?? null,
          hasInvoice: invoiceContext.hasInvoice,
          billingReason: invoiceContext.billingReason,
          identitySource: invoiceContext.identitySource,
          ownerResolved: Boolean(invoiceContext.ownerUserId),
          checkoutSessionId: invoiceContext.checkoutSessionId,
          subscriptionId: invoiceContext.subscriptionId,
          tier: invoiceContext.tier,
          ipCountry: invoiceContext.ipCountry,
          checkoutOrigin: invoiceContext.checkoutOrigin,
        })
        const failureRef = stripeFailureReference(failedIntent.id)
        const failureRecorded = await writeServerEvent({
          name: 'checkout_payment_failed',
          userId: failedUserId,
          path: '/api/stripe/webhook',
          sessionId: failureRef,
          dedupeMinutes: 24 * 60,
          metadata: failureMetadata,
        })
        if (!failureRecorded) {
          throw new RetryableCheckoutAnalyticsError('Could not persist canonical checkout failure')
        }
        break
      }

      case 'charge.failed': {
        const failedCharge = event.data.object as Stripe.Charge
        const paymentIntentId = stripeObjectId(failedCharge.payment_intent)
        if (!paymentIntentId) {
          console.warn('[stripe webhook] charge.failed without PaymentIntent; enrichment skipped')
          break
        }
        const chargeCustomerId =
          typeof failedCharge.customer === 'string'
            ? failedCharge.customer
            : failedCharge.customer?.id ?? null

        let chargeUserId: string | null = failedCharge.metadata?.supabase_user_id ?? null
        if (!chargeUserId && chargeCustomerId) {
          try {
            const { data: byCustomer } = await supabase
              .from('profiles')
              .select('id')
              .eq('stripe_customer_id', chargeCustomerId)
              .limit(1)
            chargeUserId = byCustomer?.[0]?.id ?? null
          } catch {
            console.warn('[stripe webhook] charge.failed customer lookup failed')
          }
        }

        const enrichmentRef = stripeFailureReference(paymentIntentId)
        const enrichmentRecorded = await writeServerEvent({
          name: 'checkout_payment_failure_enriched',
          userId: chargeUserId,
          path: '/api/stripe/webhook',
          sessionId: enrichmentRef,
          dedupeMinutes: 24 * 60,
          metadata: buildStripeChargeFailureEnrichment({
            paymentIntentId,
            errorCode: failedCharge.failure_code ?? null,
            declineCode: failedCharge.outcome?.reason ?? null,
            networkStatus: failedCharge.outcome?.network_status ?? null,
            riskLevel: failedCharge.outcome?.risk_level ?? null,
            cardCountry: failedCharge.payment_method_details?.card?.country ?? null,
            cardBrand: failedCharge.payment_method_details?.card?.brand ?? null,
            cardFunding: failedCharge.payment_method_details?.card?.funding ?? null,
            paymentMethodType: failedCharge.payment_method_details?.type ?? null,
          }),
        })
        if (!enrichmentRecorded) {
          throw new RetryableCheckoutAnalyticsError('Could not persist checkout failure enrichment')
        }
        break
      }

      case 'invoice.payment_succeeded': {
        // Handles two cases:
        // 1. Monthly renewal (billing_reason='subscription_cycle') — refill credits.
        // 2. First real payment after 3-day trial (billing_reason='subscription_cycle')
        //    — upgrades user from 5 trial credits to full plan credits.
        // Skip subscription_create: non-trial subscriptions already get full
        // credits via checkout.session.completed (payment_status='paid').
        const invoice = event.data.object as Stripe.Invoice & { billing_reason?: string; subscription?: string }
        const billingReason = invoice.billing_reason
        if (billingReason === 'subscription_create') break
        // KINEO-TROCA-DE-PLANO-2026-09-09 — fatura de troca de plano (proration)
        // NÃO é renovação: se caísse abaixo, o SET de créditos zeraria o saldo
        // do mês pelo grant (e o valor rateado, menor que o preço, ainda
        // acionaria o grant legado). A troca já cuidou dos créditos na rota.
        if (billingReason === 'subscription_update') {
          await supabase.from('events').insert({ name: 'subscription_update_invoice_paid', path: '/api/stripe/webhook', metadata: { invoice: invoice.id ?? null, amount_paid: invoice.amount_paid ?? 0, subscription: typeof invoice.subscription === 'string' ? invoice.subscription : null } })
          // KINEO-TROCA-BUSINESS-2026-10-10 — a ÚNICA exceção: a subida para o Business cobra a proration AGORA (rota
          // change-plan, 'always_invoice'), e os créditos da diferença só nascem AQUI, com esta fatura paga. A decisão
          // (lib/billing/trocaBusiness.ts) lê a metadata VIVA da assinatura: tier business + carimbo da troca + fatura
          // com cobrança, criada depois do carimbo. Qualquer outra fatura de troca segue sem crédito, como sempre.
          // Idempotente por troca (troca_business_granted:<assinatura>:<carimbo>, razão em `events`).
          const trocaSubscriptionId = typeof invoice.subscription === 'string' ? invoice.subscription : null
          if (trocaSubscriptionId) {
            entitlementPending = true
            let trocaSubscription: Stripe.Subscription
            try {
              trocaSubscription = await stripe.subscriptions.retrieve(trocaSubscriptionId)
            } catch (err) {
              const msg = err instanceof Error ? err.message : String(err)
              throw new RetryableEntitlementError(`Failed to load subscription for Business upgrade (${trocaSubscriptionId}): ${msg}`)
            }
            const trocaDecision = businessUpgradeGrantDecision({
              billingReason,
              invoice: { total: invoice.total, created: invoice.created },
              subscription: { id: trocaSubscription.id, metadata: trocaSubscription.metadata },
            })
            const trocaUserId = trocaSubscription.metadata?.supabase_user_id ?? null
            const trocaCustomerId = typeof trocaSubscription.customer === 'string' ? trocaSubscription.customer : trocaSubscription.customer?.id ?? null
            if (!trocaDecision.grant || !trocaUserId) {
              entitlementConfirmed = true
              entitlementPending = false
              if (trocaDecision.grant || trocaDecision.reason !== 'not_business_upgrade') console.warn('[stripe webhook] subscription_update invoice without Business grant:', invoice.id, trocaSubscriptionId, trocaDecision.grant ? 'no_owner' : trocaDecision.reason)
              break
            }
            if (!stripeSubscriptionKeepsAccess(trocaSubscription.status) || await isProtectedProfile(supabase, { userId: trocaUserId })) {
              entitlementConfirmed = true
              entitlementPending = false
              console.warn('[stripe webhook] Business upgrade grant skipped (no access or protected):', invoice.id, trocaSubscriptionId, trocaSubscription.status)
              break
            }
            const { data: trocaProfile, error: trocaProfileError } = await supabase
              .from('profiles')
              .select('id, stripe_customer_id, stripe_subscription_id')
              .eq('id', trocaUserId)
              .maybeSingle()
            if (trocaProfileError || !trocaProfile?.id) {
              throw new RetryableEntitlementError(`Failed to verify Business upgrade profile (${trocaUserId}): ${trocaProfileError?.message ?? 'profile row missing'}`)
            }
            if ((trocaProfile.stripe_customer_id && trocaProfile.stripe_customer_id !== trocaCustomerId) || (trocaProfile.stripe_subscription_id && trocaProfile.stripe_subscription_id !== trocaSubscriptionId)) {
              entitlementConfirmed = true
              entitlementPending = false
              console.error('[stripe webhook] Business upgrade grant refused: profile/subscription mismatch:', invoice.id, trocaSubscriptionId, trocaUserId)
              break
            }
            let trocaGrant: Awaited<ReturnType<typeof applyBusinessUpgradeGrant>>
            try {
              trocaGrant = await applyBusinessUpgradeGrant(supabase, {
                userId: trocaUserId,
                subscriptionId: trocaSubscriptionId,
                invoiceId: invoice.id ?? null,
                amountPaid: invoice.amount_paid ?? 0,
                currency: invoice.currency ?? 'usd',
                decision: trocaDecision,
                path: '/api/stripe/webhook',
              })
            } catch (err) {
              const msg = err instanceof Error ? err.message : String(err)
              throw new RetryableEntitlementError(`Business upgrade grant failed (${invoice.id}): ${msg}`)
            }
            entitlementConfirmed = true
            entitlementPending = false
            if (trocaGrant.status === 'ambiguous') console.error('[stripe webhook] Business upgrade grant ambiguous — check /admin/people:', invoice.id, trocaUserId, JSON.stringify(trocaGrant))
            else console.log('[stripe webhook] Business upgrade grant:', trocaGrant.status, invoice.id, trocaUserId)
            // A fatura da subida é cobrança do plano: comissão do afiliado na taxa do Business (20%), idempotente por fatura.
            await recordAffiliateCommission(supabase, { userId: trocaUserId, externalId: invoice.id ?? trocaSubscriptionId, amountGross: invoice.amount_paid ?? 0, currency: invoice.currency ?? 'usd', type: 'recurring', paymentKind: 'subscription', attributionSystem: trocaSubscription.metadata?.affiliate_system, plan: trocaSubscription.metadata?.tier })
          }
          break
        }

        const subscriptionId = typeof invoice.subscription === 'string' ? invoice.subscription : null
        if (!subscriptionId) break

        entitlementPending = true
        let subscription: Stripe.Subscription
        try {
          subscription = await stripe.subscriptions.retrieve(subscriptionId)
        } catch (err) {
          const msg = err instanceof Error ? err.message : String(err)
          throw new RetryableEntitlementError(
            `Failed to load subscription for renewal (${subscriptionId}): ${msg}`
          )
        }
        if (isKidsSubscription(subscription)) { // KINEO-KIDS-VENDA-2010 — fatura do piloto infantil: ciclo novo de 30 desenhos (idempotente por fatura), NUNCA o SET de créditos do plano (que zeraria o saldo do mês da pessoa)
          const kidsInv = await kidsInvoicePaid(supabase, subscription, { id: invoice.id ?? null, created: invoice.created ?? null, billing_reason: billingReason ?? null }) // KINEO-KIDS-VENDA-2010
          if (!kidsInv.ok) throw new RetryableEntitlementError(kidsInv.error) // KINEO-KIDS-VENDA-2010
          entitlementConfirmed = true; entitlementPending = false // KINEO-KIDS-VENDA-2010
          console.log('[stripe webhook] kids autopilot invoice:', kidsInv.detail, invoice.id) // KINEO-KIDS-VENDA-2010
          break // KINEO-KIDS-VENDA-2010
        } // KINEO-KIDS-VENDA-2010

        const renewalUserId = subscription.metadata?.supabase_user_id
        // KINEO-AUTOPILOT-299-2026-07-26 — 'autopilot' added.
        const renewalTier: CheckoutPlanTier =
          subscription.metadata?.tier === 'pro' ? 'pro'
            : subscription.metadata?.tier === 'starter' ? 'starter'
              : subscription.metadata?.tier === 'autopilot' ? 'autopilot'
                : subscription.metadata?.tier === 'autopilot_lite' ? 'autopilot_lite' // KINEO-AUTOPILOT-LITE
                  : subscription.metadata?.tier === 'business' ? 'business' // KINEO-BUSINESS-84-2026-10-09
                    : 'basic'
        // KINEO-STUDIO-400-2026-07-06 — renewal credits are SET (not added)
        // each cycle → no rollover between months.
        // KINEO-PRICING-V3D-2026-07-26 — single source (lib/checkoutPricing).
        // NOTE: this is the FULL grant even for a subscription that started on
        // the discounted intro month. subscription.metadata.intro stays '1'
        // forever (it is the one-intro-per-customer marker), so reading it here
        // would permanently under-grant every renewal. The reduced intro grant
        // is applied only once, at checkout.session.completed.
        // KINEO-MOEDA-LOCAL-2026-09-09 — fatura em reais é comparada com a tabela em reais.
        const renewalCredits = renewalCreditsForInvoice(renewalTier, invoice.amount_paid, invoice.currency)
        if (!renewalUserId) {
          entitlementPending = false
          break
        }
        const renewalCustomerId = typeof subscription.customer === 'string'
          ? subscription.customer
          : subscription.customer?.id ?? null
        if (!renewalCustomerId) {
          throw new RetryableEntitlementError(
            `Renewal subscription missing Customer (${subscriptionId})`
          )
        }
        if (await isProtectedProfile(supabase, { userId: renewalUserId })) {
          entitlementConfirmed = true
          entitlementPending = false
          console.log('[stripe webhook] renewal skipped for protected admin account:', renewalUserId)
          break
        }
        // KINEO-STRIPE-ATRASO-2026-09-28 — com a janela de 2 meses, a fatura de um mês pode ser paga em atraso enquanto
        // a do mês seguinte ainda falha: a assinatura segue past_due e o portão active/trialing jogava o pagamento fora
        // (pagou e não recebeu). past_due mantém o acesso pela regra única (lib/billing/subscriptionAccess.ts);
        // unpaid/canceled/incomplete_expired/paused seguem ignorados — e agora o descarte deixa rastro no banco.
        if (!stripeSubscriptionKeepsAccess(subscription.status)) {
          // Stripe events can arrive out of order. A historical paid invoice
          // must not reactivate/refill a subscription whose live state is now
          // canceled, unpaid, paused or otherwise non-access.
          entitlementConfirmed = true
          entitlementPending = false
          console.warn('[stripe webhook] stale renewal ignored for non-access subscription:', invoice.id, subscriptionId, subscription.status)
          await writeServerEvent({
            name: 'renewal_ignored_non_access',
            userId: renewalUserId,
            path: '/api/stripe/webhook',
            metadata: {
              invoice_ref: invoice.id ?? null,
              subscription_ref: subscriptionId,
              status: subscription.status,
            },
          })
          break
        }

        const { data: renewalProfile, error: renewalProfileError } = await supabase
          .from('profiles')
          .select('id, stripe_customer_id, stripe_subscription_id, plan, video_credits')
          .eq('id', renewalUserId)
          .maybeSingle()
        if (renewalProfileError || !renewalProfile?.id) {
          throw new RetryableEntitlementError(
            `Failed to verify renewal profile (${renewalUserId}): ${renewalProfileError?.message ?? 'profile row missing'}`
          )
        }
        if (renewalProfile.stripe_customer_id && renewalProfile.stripe_customer_id !== renewalCustomerId) {
          throw new RetryableEntitlementError(
            `Renewal Customer identity mismatch (${renewalUserId}, ${subscriptionId})`
          )
        }
        if (
          renewalProfile.stripe_subscription_id &&
          renewalProfile.stripe_subscription_id !== subscriptionId
        ) {
          // A paid invoice for an older duplicate subscription must never reset
          // the balance/tier belonging to the profile's newer subscription.
          entitlementConfirmed = true
          entitlementPending = false
          await recordAffiliateCommission(supabase, { userId: renewalUserId, externalId: invoice.id ?? subscriptionId, amountGross: invoice.amount_paid ?? 0, currency: invoice.currency ?? 'usd', type: 'recurring', paymentKind: 'subscription', attributionSystem: subscription.metadata?.affiliate_system, plan: subscription.metadata?.tier })
          console.warn('[stripe webhook] stale renewal ignored for superseded subscription:', invoice.id, subscriptionId, renewalProfile.stripe_subscription_id)
          break
        }

        // KINEO-STRIPE-ATRASO-2026-09-28 — renovação idempotente POR FATURA (mesmo padrão do checkout_fulfilled:).
        // O dedupe por event.id é liberado quando algo depois do crédito pede reenvio (ex.: ledger de afiliado);
        // sem esta chave o reenvio reaplicava o saldo da mesma fatura. Já concedida → só os passos idempotentes.
        const renewalGrantKey = invoice.id ? `renewal_granted:${invoice.id}` : null
        if (renewalGrantKey) {
          const { data: renewalGranted, error: renewalGrantLookupError } = await supabase
            .from('stripe_events')
            .select('id')
            .eq('id', renewalGrantKey)
            .maybeSingle()
          if (renewalGrantLookupError) {
            throw new RetryableEntitlementError(
              `Failed to verify renewal grant (${invoice.id}): ${renewalGrantLookupError.message}`
            )
          }
          if (renewalGranted?.id === renewalGrantKey) {
            entitlementConfirmed = true
            entitlementPending = false
            await markTrialConverted(supabase, renewalUserId, { source: 'invoice_payment_succeeded', stripeRef: invoice.id ?? subscriptionId })
            await recordAffiliateCommission(supabase, { userId: renewalUserId, externalId: invoice.id ?? subscriptionId, amountGross: invoice.amount_paid ?? 0, currency: invoice.currency ?? 'usd', type: 'recurring', paymentKind: 'subscription', attributionSystem: subscription.metadata?.affiliate_system, plan: subscription.metadata?.tier })
            console.log('[stripe webhook] renewal already granted for invoice:', invoice.id, subscriptionId)
            break
          }
        }

        // On renewal we set the balance to the plan amount rather than adding,
        // so unused credits from the prior cycle don't pile up indefinitely.
        // Push #088 — also reset cinematic_tokens on renewal: Pro = 1,
        // Basic = 0. Resetting (not adding) keeps the monthly cap honest
        // even if the user never spent the prior month's token.
        const renewalCinematicTokens = (renewalTier === 'pro' || renewalTier === 'autopilot') ? 1 : 0
        // KINEO-RENOVACAO-PRESERVA-CREDITO-COMPRADO-2026-09-25 — o SET apagava o crédito COMPRADO (barra, packs, passe)
        // e o dado pela casa. Agora só a cota do plano zera; o que passa de uma cota sobrevive (lib/credits/renewalBalance).
        const renovacao = renewalBalance(renewalProfile.video_credits, renewalCredits)
        // Push #416 — never let a legacy subscription renewal overwrite a
        // manually-managed admin account.
        const { data: renewedProfile, error: renewErr } = await supabase
          .from('profiles')
          .update({
            video_credits: renovacao.balance, // KINEO-RENOVACAO-PRESERVA-CREDITO-COMPRADO-2026-09-25
            is_pro: true,
            plan: renewalTier,
            cinematic_tokens: renewalCinematicTokens,
            stripe_customer_id: renewalCustomerId,
            stripe_subscription_id: subscriptionId,
          })
          .eq('id', renewalUserId)
          .select('id')
          .maybeSingle()

        if (renewErr || !renewedProfile?.id) {
          throw new RetryableEntitlementError(
            `Renewal credit refill failed (${renewalUserId}): ${renewErr?.message ?? 'profile row missing'}`
          )
        } else {
          entitlementConfirmed = true
          entitlementPending = false
          console.log(`[stripe webhook] renewal: ${renewalTier} (${renewalCredits} + ${renovacao.carried} carried = ${renovacao.balance}, cin=${renewalCinematicTokens}) → user ${renewalUserId}`)
        }
        // KINEO-STRIPE-ATRASO-2026-09-28 — a chave só nasce DEPOIS do crédito (se o update falhar, a renovação não se
        // perde). Se a inserção falhar, loga e segue: o crédito já foi dado e derrubar o webhook agora não desfaz nada.
        if (renewalGrantKey) {
          try {
            const { error: renewalGrantMarkError } = await supabase
              .from('stripe_events')
              .insert({ id: renewalGrantKey })
            if (renewalGrantMarkError && renewalGrantMarkError.code !== '23505') {
              console.error('[stripe webhook] renewal grant marker insert failed (credit already applied):', invoice.id, renewalGrantMarkError.code, renewalGrantMarkError.message)
            }
          } catch (renewalGrantMarkThrown) {
            console.error('[stripe webhook] renewal grant marker insert threw (credit already applied):', invoice.id, renewalGrantMarkThrown)
          }
        }
        // KINEO-PLACAR-TRIAL-2026-09-08 — a fatura paga (renovacao OU a primeira
        // cobranca do dia 8 depois do trial de $1) nunca virava evento: o placar so
        // via payment_success da sessao de checkout. Agora existe um evento por
        // fatura, com trial_conversion quando o plano anterior era *_trial.
        const previousPlanNormalized = String(renewalProfile.plan ?? '').toLowerCase()
        await writeServerEvent({
          name: 'subscription_invoice_paid',
          userId: renewalUserId,
          metadata: {
            source: 'stripe_webhook',
            billing_reason: billingReason ?? null,
            stripe_invoice_id: invoice.id ?? null,
            stripe_subscription_id: subscriptionId,
            tier: renewalTier,
            previous_plan: previousPlanNormalized || null,
            trial_conversion: previousPlanNormalized.endsWith('_trial'),
            amount_paid: invoice.amount_paid ?? 0,
            currency: invoice.currency ?? 'usd',
            credits_granted: renewalCredits,
            credits_carried: renovacao.carried, // KINEO-RENOVACAO-PRESERVA-CREDITO-COMPRADO-2026-09-25
            balance_after: renovacao.balance,
            carry_version: RENEWAL_CARRY_VERSION,
          },
        })

        // KINEO-REVERSE-TRIAL-P2-2026-08-07 — cobre pagamento que só chega como
        // invoice (ex.: primeira cobrança do dia 4 pós-trial do Stripe, ou sub
        // criada fora do Checkout). Quase sempre 0 linhas (o Checkout já
        // carimbou); idempotente e barato.
        await markTrialConverted(supabase, renewalUserId, { source: 'invoice_payment_succeeded', stripeRef: invoice.id ?? subscriptionId })
        await recordAffiliateCommission(supabase, { userId: renewalUserId, externalId: invoice.id ?? subscriptionId, amountGross: invoice.amount_paid ?? 0, currency: invoice.currency ?? 'usd', type: 'recurring', paymentKind: 'subscription', attributionSystem: subscription.metadata?.affiliate_system, plan: subscription.metadata?.tier })

        break
      }

      // ═══ KINEO-TRIAL-AVISO-2026-08-20 — O E-MAIL QUE PROTEGE A CONTA ═════
      // O Stripe dispara este evento 3 dias antes de o trial virar cobrança.
      // Mandar o aviso NÃO é gentileza: trial que cobra de surpresa vira
      // contestação de cartão, e contestação em volume derruba a conta Stripe
      // inteira. Ou seja, este e-mail é o que torna o modelo sustentável — e é
      // também o que faz a pessoa que VAI ficar se sentir respeitada.
      // Deliberadamente sem venda: só o fato, a data, o valor e como cancelar.
      case 'customer.subscription.trial_will_end': {
        const sub = event.data.object as Stripe.Subscription
        const trialUserId = sub.metadata?.supabase_user_id ?? null
        const trialEnd = sub.trial_end ? new Date(sub.trial_end * 1000) : null
        if (trialUserId && trialEnd && process.env.RESEND_API_KEY) {
          try {
            const { data: prof } = await supabase
              .from('profiles').select('email, email_opted_out').eq('id', trialUserId).maybeSingle()
            const to = (prof?.email ?? '') as string
            if (to && !prof?.email_opted_out) {
              const amount = ((sub.items.data[0]?.price?.unit_amount ?? 0) / 100).toFixed(2)
              const when = trialEnd.toLocaleDateString('en-US', { month: 'long', day: 'numeric' })
              const manage = `${process.env.NEXT_PUBLIC_APP_URL ?? 'https://www.usekineo.com'}/account`
              await fetch('https://api.resend.com/emails', {
                method: 'POST',
                headers: { Authorization: `Bearer ${process.env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
                body: JSON.stringify({
                  from: 'Kineo Team <hello@usekineo.com>',
                  to: [to],
                  reply_to: 'hello@usekineo.com',
                  subject: `Your Kineo trial ends ${when} — ${amount} unless you cancel`,
                  text: `Hey,\n\nQuick heads up, no surprises: your free week of Kineo ends on ${when}, and your card will be charged $${amount} for the first month.\n\nIf Kineo is working for you, there is nothing to do — your credits renew and you keep going.\n\nIf it is not, cancel in one click here and you will not be charged: ${manage}\n\nEither way, thanks for giving it a real try.\n\nKineo Team\nusekineo.com`,
                  html: `<div style="font-family:Arial,sans-serif;font-size:15px;color:#111;line-height:1.6;max-width:480px;"><p>Hey,</p><p>Quick heads up, no surprises: your free week of Kineo ends on <strong>${when}</strong>, and your card will be charged <strong>$${amount}</strong> for the first month.</p><p>If Kineo is working for you, there is nothing to do — your credits renew and you keep going.</p><p>If it is not, <a href="${manage}" style="color:#2997ff">cancel in one click here</a> and you will not be charged.</p><p>Either way, thanks for giving it a real try.</p><p style="margin:0 0 2px">Kineo Team</p><p style="margin:0"><a href="https://www.usekineo.com" style="color:#2997ff">usekineo.com</a></p></div>`,
                }),
              })
