    s.escolhaMedia = { marker: 'KINEO-ADS-ESCOLHA-2310', voice: { status: narrated ? 'new' : 'done', attempt: 1 }, music: { status: s.plan.ajusteLive?.music === true ? 'new' : 'skipped' } }
