  const cropFn = ih && productUrl ? await inHandCropLib().then((m) => (m ? m.adsV2InHandCropper({ userId: order.user_id, cacheKey: order.id, productUrl }) : undefined)) : undefined // KINEO-ADS-MAO-JUIZ-1610 — a fidelidade compara os RECORTES (o real só com o objeto do plano × o gerado)
  const verdict = ih && productUrl ? await lockVision().then((v) => (v && typeof v.adsV2InHandLabelJudge === 'function' ? v.adsV2InHandLabelJudge(productUrl, stored, undefined, tag?.object ?? null, undefined, cropFn) : null)).catch(() => null) : null // KINEO-ADS-MAO-JUIZ-1610 — o juiz em 2 etapas (inventário + fidelidade) · KINEO-ADS-PRODUTO-NA-MAO-1610 · KINEO-ADS-MAO-AJUSTE-3-1610 — + o objeto único (os dois juntos = reprova) e a pessoa extra
  let step = ih ? ih.adsV2InHandJudgeStep({ verdict, previousReason: row.reason }) : 'keep' // KINEO-ADS-PRODUTO-NA-MAO-1610 — sem a lib ou sem juiz: a foto segue · KINEO-ADS-MAO-JUIZ-1610 — let (o teto do packshot abaixo)
  const softOnly = !!ih && typeof ih.adsV2InHandSoftOnly === 'function' && ih.adsV2InHandSoftOnly(verdict) // KINEO-ADS-MAO-JUIZ-1610 — reprovou SÓ em "both_objects"/"extra_person" (rótulo e produto certos)
  let packshotsUsed: number | null = null // KINEO-ADS-MAO-JUIZ-1610
