  } catch (e) { // KINEO-APRESENTADOR-V2-AJUSTE-1710
    console.warn(`[ads-v2] ajuste da voz do apresentador v2 falhou order=${order.id}:`, e instanceof Error ? e.message : String(e)) // KINEO-APRESENTADOR-V2-AJUSTE-1710
