      const balance = Number((prof.data as { video_credits?: number } | null)?.video_credits ?? 0)
      if (!(balance >= cost)) return v2Fail('out_of_credits', 402, { needed: cost, balance })
    }

    // Trava condicional: só um início por pedido; o índice único parcial deixa só UM anúncio ativo por conta.
    const generationId = randomUUID()
    // KINEO-ADS-AMOSTRA-2026-10-09 — a amostra trava com a chave 'adssample-…' (sem débito) e credits_charged 0.
    const billingRef = sampleRun ? adsSampleRef(orderId, generationId) : adsV2BillingRef(orderId, generationId)
    const lock = await admin
      .from('ads_v2_orders')
      .update({ status: 'generating', generation_id: generationId, billing_ref: billingRef, credits_charged: sampleRun ? 0 : cost, started_at: new Date().toISOString(), error: null, ...(cena?.plan.ajusteLive?.version === 'KINEO-ADS-CENA-RETOMADA-2110' ? { plan } : {}) }) // KINEO-ADS-CENA-SEGUE-2110 — persist corrected copy/notes in the existing atomic start claim.
      .eq('id', orderId)
      .eq('user_id', uid)
      .in('status', ['draft', 'planned'])
      .select('id')
      .maybeSingle()
    if (lock.error) return lock.error.code === '23505' ? v2Fail('another_active', 409) : v2Fail('start_failed', 502)
    if (!lock.data) return v2Fail('not_startable', 409)
    locked = { id: orderId, user_id: uid, billing_ref: billingRef }

    // Débito com o padrão confiável (intenção → saldo → débito → releitura do ledger). A amostra NÃO debita (KINEO-ADS-AMOSTRA-2026-10-09).
    const charge: AdsV2ChargeResult = sampleRun ? { ok: true, balance: null } : await chargeAdsV2(admin, { userId: uid, billingRef, cost })
    if (!charge.ok) {
      if (!charge.debitPossible) {
        // Provado que nada foi debitado: o pedido volta a 'planned' (só esta geração).
        await admin.from('ads_v2_orders').update({ status: 'planned', generation_id: null, billing_ref: null, credits_charged: 0, started_at: null })
          .eq('id', orderId).eq('generation_id', generationId).eq('status', 'generating')
      } else {
        await failAdsV2Order(admin, locked, `charge_${charge.code}`, '/api/ads/v2/start')
      }
      locked = null
      return v2Fail(charge.code, charge.status, charge.balance !== undefined ? { needed: cost, balance: charge.balance } : {})
    }

    if (sampleRun) {
      // KINEO-ADS-AMOSTRA-2026-10-09 — o rastro da amostra (o custo é nosso: conta o teto e o US$ estimado).
      await writeServerEvent({ name: 'ads_sample_started', userId: uid, path: '/api/ads/v2/start', metadata: { order_id: orderId, generation_id: generationId, billing_ref: billingRef, tier: order.tier, seconds: order.seconds, usd_estimate: usd.totalUsd, credits_list: cost, format: samplePresenter ? 'presenter' : 'close_real', watermark: true } }) // KINEO-HOME-3-CARDS-1910 — o formato da amostra (Close real ou com a pessoa) // KINEO-CLOSE-REAL-1910 — + o formato e a marca-d'água; era: o mesmo evento sem format/watermark
    }

    // Planos da geração (text nasce 'skipped_text' e nunca vai à fal).
    if (cena) { const costs = cena95CostTableOf(cena.plan) ?? (cena.plan.voice_mode ? cenaCosts(undefined, cena.plan.voice_mode) : cenaCosts()); locked = null; await writeEscolhaEvent('render_started', uid, orderId, plan, { credits: cost }); await writeServerEvent({ name: 'ads_cena_started', userId: uid, path: '/api/ads/v2/start', metadata: { order_id: orderId, route: cena.route, credits: cost, costs } }); return v2Json({ order_id: orderId, status: 'generating', credits: cost, costs, status_url: `/api/ads/v2/status?order_id=${orderId}` }, 202) } // KINEO-ADS-CENA-2110 KINEO-ADS-CENA-AJUSTE-2110 — resposta e evento usam o modo salvo; nenhum plano legado é enviado; /status e cron avançam a cena
    const rows = buildInitialShotRows(orderId, order.tier, plan)
    const ins = await admin.from('ads_v2_shots').upsert(rows, { onConflict: 'order_id,idx,attempt', ignoreDuplicates: true })
    if (ins.error) {
      await failAdsV2Order(admin, locked, 'shots_insert_failed', '/api/ads/v2/start')
      locked = null
      return v2Fail('start_failed', 502)
    }
    locked = null

    const fresh = (await loadAdsV2Order(admin, orderId, uid)).order
    const sent = fresh ? await dispatchAdsV2Shots(admin, fresh, started + DISPATCH_BUDGET_MS) : 0
    await writeServerEvent({
      name: 'ads_v2_started',
      userId: uid,
      path: '/api/ads/v2/start',
      metadata: {
        order_id: orderId, generation_id: generationId, billing_ref: billingRef, tier: order.tier, seconds: order.seconds, credits: sampleRun ? 0 : cost, sample: sampleRun,
        usd_estimate: usd.totalUsd, shots: rows.length, text_shots: rows.filter((r) => r.kind === 'text').length, submitted_now: sent, ms: Date.now() - started,
      },
    })
    // KINEO-EQUIPE-BUSINESS-2026-10-10 — rastro de auditoria: o MEMBRO agiu no workspace do dono (o pedido e a cobrança são do dono).
    if (access.role === 'member') await writeServerEvent({ name: 'ads_order_by_member', userId: user.id, path: '/api/ads/v2/start', metadata: { owner_id: uid, action: 'start', order_id: orderId, billing_ref: billingRef, credits: sampleRun ? 0 : cost } })
    const shots = (await loadAdsV2Shots(admin, orderId)) ?? []
    return v2Json(fresh ? { ...adsV2View(fresh, shots), usd_estimate: usd } : { order_id: orderId, status: 'generating' }, 202)
  } catch (e) {
    console.warn('[ads/v2/start] falhou:', e instanceof Error ? e.message : String(e))
    if (locked && admin) await failAdsV2Order(admin, locked, `exception:${e instanceof Error ? e.message : String(e)}`, '/api/ads/v2/start').catch(() => null)
    return v2Fail('start_failed', 502)
  }
}

lib/growth/checkoutSuccessFlow.ts.before:
export const AUTOPILOT_CHECKOUT_SUCCESS_VERSION = 'autopilot_checkout_success_v1' as const

export type CheckoutSuccessFlow =
  | {
      kind: 'self_serve'
      destination: '/studio'
    }
  | {
      kind: 'autopilot'
      destination: string
    }

type SearchParamsReader = Pick<URLSearchParams, 'get'>

const STRIPE_SESSION_ID = /^cs_(?:live|test)_[A-Za-z0-9]{1,255}$/

function safeStripeSessionId(value: string | null): string | null {
  const normalized = value?.trim() ?? ''
  return STRIPE_SESSION_ID.test(normalized) ? normalized : null
}

export function readCheckoutSuccessFlow(params: SearchParamsReader): CheckoutSuccessFlow {
  if (params.get('tier') !== 'autopilot') {
    return {
      kind: 'self_serve',
      destination: '/studio',
    }
  }

  const sessionId = safeStripeSessionId(params.get('session_id'))
  const query = new URLSearchParams({ success: 'true', tier: 'autopilot' })
  if (sessionId) query.set('session_id', sessionId)

  return {
    kind: 'autopilot',
    destination: `/autopilot?${query.toString()}`,
  }
}

export function buildSubscriptionCheckoutSuccessUrl(input: {
  appUrl: string
  tier: string
  currency: string
  amount: number
}): string {
  const autopilotTier = input.tier === 'autopilot' ? '&tier=autopilot' : ''
  return `${input.appUrl}/checkout/success?success=true&currency=${input.currency}&amount=${input.amount}${autopilotTier}&session_id={CHECKOUT_SESSION_ID}`
}

export function isAutopilotEntitlementReady(plan: unknown): boolean {
  return plan === 'autopilot'
}

export function readyCheckoutSuccessDestination(
  flow: CheckoutSuccessFlow,
  plan: unknown,
): string | null {
  if (flow.kind === 'self_serve') return flow.destination
  return isAutopilotEntitlementReady(plan) ? flow.destination : null
}

