  ar: /تمامًا|يبقى|مطابق/, ur: /بالکل|رہتا ہے/, hi: /बिल्कुल|जैसा रहेगा/, id: /persis|tetap|identik/i, vi: /giữ nguyên|y hệt|giống hệt/i,
}
