await vermelho('M5 packshot somando um plano em vez de trocar', SRC.lists, '  return shots.map((s) => s.idx !== at ? s : {', '  return [...shots, { ...shots[0], idx: shots.length }].map((s) => s.idx !== at ? s : {', (m) => p1(m))
